window.POPQUIZ_SAMPLE_BUNDLE = {"catalog": {"version": "3.9.2", "totalSets": 71, "sets": [{"id": "jh-health-set1", "school": "jh", "schoolName": "中学校", "subject": "health", "subjectName": "保健体育", "topic": "心身の発達と心の健康", "title": "セット1: 成長の急加速！「発育急進期」のひみつ", "description": "身長や体重が急激に伸びる発育急進期、成長の個人差、脳や神経の発達についての3問。", "dataFile": "sample/junior_high/health/health.json", "questionCount": 3, "questionTypes": "4択・〇×", "previewQuestions": [{"type": "4choice", "question": "生まれてから大人になるまでに、身長や体重が急激に発育する時期は一生のうち何回あるでしょう？"}, {"type": "2choice", "question": "思春期（第2発育急進期）が始まる時期や成長のスピードには、一人ひとり「個人差」がある。"}, {"type": "2choice", "question": "脳や脊髄などの「神経系」は、思春期にはすでに大人とほぼ同じレベルまで発育が進んでいる。"}], "searchText": "セット1: 成長の急加速！「発育急進期」のひみつ 身長や体重が急激に伸びる発育急進期、成長の個人差、脳や神経の発達についての3問。 中学校 保健体育 心身の発達と心の健康 生まれてから大人になるまでに、身長や体重が急激に発育する時期は一生のうち何回あるでしょう？ 人間には身長や体重が急激に伸びる「発育急進期」が2回あります。1回目は乳児期（生後1年）、2回目は中学生前後の「思春期（第2発育急進期）」です！ 思春期（第2発育急進期）が始まる時期や成長のスピードには、一人ひとり「個人差」がある。 正解！思春期の成長が早く始まる人もいればゆっくり進む人もいます。背の伸び方や体の変化には大きな個人差があるため、人と比べすぎないことが大切です。 脳や脊髄などの「神経系」は、思春期にはすでに大人とほぼ同じレベルまで発育が進んでいる。 正解！脳や脊髄などの神経系は幼児期から急速に発達し、思春期の頃には大人とほぼ同じ（約100%）まで発達が完了しています。"}, {"id": "jh-health-set2", "school": "jh", "schoolName": "中学校", "subject": "health", "subjectName": "保健体育", "topic": "心身の発達と心の健康", "title": "セット2: 肺と心臓のパワーアップ！「呼吸器と循環器」", "description": "肺活量の増大、心臓の働き、脈拍数の変化など呼吸器・循環器の発達についての3問。", "dataFile": "sample/junior_high/health/health.json", "questionCount": 3, "questionTypes": "4択", "previewQuestions": [{"type": "4choice", "question": "呼吸器（鼻・のど・気管・肺など）の発達によって起こる体の変化として、正しいものはどれ？"}, {"type": "4choice", "question": "血液を全身の血管へ力強く送り出す「循環器」の中心となる臓器は次のうちどれ？"}, {"type": "4choice", "question": "思春期に心臓や血管などの循環器が発達すると、安静時の「脈拍数」はどう変化するでしょう？"}], "searchText": "セット2: 肺と心臓のパワーアップ！「呼吸器と循環器」 肺活量の増大、心臓の働き、脈拍数の変化など呼吸器・循環器の発達についての3問。 中学校 保健体育 心身の発達と心の健康 呼吸器（鼻・のど・気管・肺など）の発達によって起こる体の変化として、正しいものはどれ？ 呼吸器が発達すると、肺活量（1回に吸い込める空気の量）がグンと増大し、安静時の呼吸数はかえって減少して効率の良い呼吸ができるようになります。 血液を全身の血管へ力強く送り出す「循環器」の中心となる臓器は次のうちどれ？ 循環器は心臓と血管（動脈・静脈・毛細血管）から成ります。心臓が力強いポンプとして収縮することで、酸素や栄養を乗せた血液が全身へ循環します。 思春期に心臓や血管などの循環器が発達すると、安静時の「脈拍数」はどう変化するでしょう？ 心臓が大きく強く育ち、1回の拍動で送り出せる血液量（拍出量）が増えるため、安静時の脈拍数（1分間の心拍数）は少なくなっていきます。"}, {"id": "jh-health-set3", "school": "jh", "schoolName": "中学校", "subject": "health", "subjectName": "保健体育", "topic": "心身の発達と心の健康", "title": "セット3: 体力を高める！「思春期の運動と持久力」", "description": "持久力を伸ばす最適期、運動強度の目安、「少しきつい」運動の継続についての3問。", "dataFile": "sample/junior_high/health/health.json", "questionCount": 3, "questionTypes": "4択・〇×", "previewQuestions": [{"type": "4choice", "question": "思春期は、呼吸器や循環器の機能を高めるある体力を伸ばすのに最も適した時期です。その体力とは？"}, {"type": "4choice", "question": "思春期に持久力を効果的に高める運動の強さ（強度）の目安として、最も適切なものはどれ？"}, {"type": "2choice", "question": "運動の効果を高めるためには、たまに激しい運動をするよりも「継続的」に行うことが大切である。"}], "searchText": "セット3: 体力を高める！「思春期の運動と持久力」 持久力を伸ばす最適期、運動強度の目安、「少しきつい」運動の継続についての3問。 中学校 保健体育 心身の発達と心の健康 思春期は、呼吸器や循環器の機能を高めるある体力を伸ばすのに最も適した時期です。その体力とは？ 思春期は肺や心臓が著しく成長するため、長く運動を続ける「持久力（全身持久力）」を高めるのに一生の中で最も適したゴールデンエイジです！ 思春期に持久力を効果的に高める運動の強さ（強度）の目安として、最も適切なものはどれ？ 脈拍が適度に上がり、「少しきついな」と感じる程度の有酸素運動（ジョギング、水泳、球技など）を続けることが、心肺機能の向上に最も効果的です。 運動の効果を高めるためには、たまに激しい運動をするよりも「継続的」に行うことが大切である。 正解！たまに無理な運動をするよりも、週に数回など継続して運動習慣をつけることで、呼吸器や循環器の機能が着実に高まります。"}, {"id": "jh-health-set4", "school": "jh", "schoolName": "中学校", "subject": "health", "subjectName": "保健体育", "topic": "心身の発達と心の健康", "title": "セット4: 体の変化の司令塔！「ホルモンと生殖器官」", "description": "下垂体からの性腺刺激ホルモン、精巣と卵巣の発達についての3問。", "dataFile": "sample/junior_high/health/health.json", "questionCount": 3, "questionTypes": "4択", "previewQuestions": [{"type": "4choice", "question": "思春期になると、脳の底にあるどこから「性腺刺激ホルモン」が分泌され始めるでしょう？"}, {"type": "4choice", "question": "男子の生殖器官で、精子をつくり男性ホルモンを活発に分泌する器官はどこ？"}, {"type": "4choice", "question": "女子の生殖器官で、卵子を成熟させ女性ホルモンを活発に分泌する器官はどこ？"}], "searchText": "セット4: 体の変化の司令塔！「ホルモンと生殖器官」 下垂体からの性腺刺激ホルモン、精巣と卵巣の発達についての3問。 中学校 保健体育 心身の発達と心の健康 思春期になると、脳の底にあるどこから「性腺刺激ホルモン」が分泌され始めるでしょう？ 脳の「下垂体」から性腺刺激ホルモンが血液中へ分泌され、それが精巣や卵巣を刺激して大人の体への成熟をスタートさせます。 男子の生殖器官で、精子をつくり男性ホルモンを活発に分泌する器官はどこ？ 下垂体の刺激によって「精巣」が発達し、精子がつくられ始めるとともに、男性ホルモンの働きで声変わりや筋肉の発達など男性らしい体つきになります。 女子の生殖器官で、卵子を成熟させ女性ホルモンを活発に分泌する器官はどこ？ 「卵巣」が発達して卵子が成熟するようになり、女性ホルモンの働きによって乳房の発達や皮下脂肪の増加など女性らしい丸みのある体つきになります。"}, {"id": "jh-health-set5", "school": "jh", "schoolName": "中学校", "subject": "health", "subjectName": "保健体育", "topic": "心身の発達と心の健康", "title": "セット5: 生命をつなぐリズム！「排卵と月経」", "description": "成熟した卵子の排卵、子宮内膜と月経の仕組み、成熟の個人差についての3問。", "dataFile": "sample/junior_high/health/health.json", "questionCount": 3, "questionTypes": "4択・〇×", "previewQuestions": [{"type": "4choice", "question": "卵巣の中で成熟した卵子が、周期的に卵巣の外（卵管）へ押し出される現象を何という？"}, {"type": "4choice", "question": "受精しなかったとき、充血して厚くなった子宮内膜がはがれ落ちて血液とともに体外へ出る現象は？"}, {"type": "2choice", "question": "思春期の前半はホルモンの分泌がまだ不安定なため、月経の周期や射精の時期が不規則でも心配しすぎる必要はない。"}], "searchText": "セット5: 生命をつなぐリズム！「排卵と月経」 成熟した卵子の排卵、子宮内膜と月経の仕組み、成熟の個人差についての3問。 中学校 保健体育 心身の発達と心の健康 卵巣の中で成熟した卵子が、周期的に卵巣の外（卵管）へ押し出される現象を何という？ 約1か月に1回、成熟した卵子が卵巣の壁を破って卵管へと飛び出す現象を「排卵」と呼びます。 受精しなかったとき、充血して厚くなった子宮内膜がはがれ落ちて血液とともに体外へ出る現象は？ 受精卵を迎えるために厚く準備された子宮内膜が、妊娠しなかった場合に不要となり剥がれて体外へ排出されるのが「月経（生理）」です。 思春期の前半はホルモンの分泌がまだ不安定なため、月経の周期や射精の時期が不規則でも心配しすぎる必要はない。 正解！思春期の生殖機能は完成へと向かう途中のため、周期が乱れるのはごく自然なことです。体が成長するにつれて次第にリズムが安定していきます。"}, {"id": "jh-health-set6", "school": "jh", "schoolName": "中学校", "subject": "health", "subjectName": "保健体育", "topic": "心身の発達と心の健康", "title": "セット6: 命の誕生の奇跡！「受精から妊娠へ」", "description": "精子と卵子の受精、受精卵の着床、母体内での妊娠についての3問。", "dataFile": "sample/junior_high/health/health.json", "questionCount": 3, "questionTypes": "4択", "previewQuestions": [{"type": "4choice", "question": "射精された精子が子宮を通って卵管へ進み、卵子と1つに結びつくことを何という？"}, {"type": "4choice", "question": "細胞分裂を繰り返しながら移動した受精卵が、子宮内膜の中に潜り込んで定着することを何という？"}, {"type": "4choice", "question": "着床が完了してから赤ちゃんが生まれるまでの、母体内に胎児が宿って育っている状態を何という？"}], "searchText": "セット6: 命の誕生の奇跡！「受精から妊娠へ」 精子と卵子の受精、受精卵の着床、母体内での妊娠についての3問。 中学校 保健体育 心身の発達と心の健康 射精された精子が子宮を通って卵管へ進み、卵子と1つに結びつくことを何という？ 数億個の精子の中からたった1つの精子が卵子と結合することを「受精」といい、ここから新しい生命の設計図が動き出します。 細胞分裂を繰り返しながら移動した受精卵が、子宮内膜の中に潜り込んで定着することを何という？ 受精卵が子宮の内側にしっかりと根を下ろすように定着することを「着床」といい、着床が完了した時点で「妊娠」が成立します。 着床が完了してから赤ちゃんが生まれるまでの、母体内に胎児が宿って育っている状態を何という？ 母体の中で胎児を育てる状態を「妊娠」と呼びます。胎児は約38週（約9〜10か月）かけて母体から酸素や栄養をもらいながら成長します。"}, {"id": "jh-health-set7", "school": "jh", "schoolName": "中学校", "subject": "health", "subjectName": "保健体育", "topic": "心身の発達と心の健康", "title": "セット7: こころの成長！「性意識と人間関係」", "description": "性意識の芽生え、性的欲求の自然な理解、適切な情報の選択と相談についての3問。", "dataFile": "sample/junior_high/health/health.json", "questionCount": 3, "questionTypes": "4択・〇×", "previewQuestions": [{"type": "4choice", "question": "思春期になると、身体の発達に伴って異性への関心や好意を持つなど、心にある変化が現れます。これを何という？"}, {"type": "2choice", "question": "思春期に性的な関心や性的欲求が高まることは、人間として恥ずかしい異常なことである。"}, {"type": "4choice", "question": "ネットやSNSなどの性情報に対処するとき、最も適切な態度は次のうちどれ？"}], "searchText": "セット7: こころの成長！「性意識と人間関係」 性意識の芽生え、性的欲求の自然な理解、適切な情報の選択と相談についての3問。 中学校 保健体育 心身の発達と心の健康 思春期になると、身体の発達に伴って異性への関心や好意を持つなど、心にある変化が現れます。これを何という？ 異性を意識したり特別な好意を抱くようになる心の働きを「性意識」と呼びます。これも思春期を迎えた誰にでも起こる自然な成長の表れです。 思春期に性的な関心や性的欲求が高まることは、人間として恥ずかしい異常なことである。 誤り（×）です！性的な関心や欲求が生じるのは、ホルモンの働きによる成熟の証拠であり、ごく自然なことです。大切なのは相手を尊重し適切な行動をとることです。 ネットやSNSなどの性情報に対処するとき、最も適切な態度は次のうちどれ？ ネット上には誤った情報や危険な情報も混ざっています。科学的で正しい情報を選択し、不安や悩みがあれば保護者や先生、専門の相談窓口を頼りましょう。"}, {"id": "jh-health-set8", "school": "jh", "schoolName": "中学校", "subject": "health", "subjectName": "保健体育", "topic": "心身の発達と心の健康", "title": "セット8: こころの司令塔！「脳の働きと心の健康」", "description": "大脳の知的能力、経験による情意機能の発達、心の健康の調和についての3問。", "dataFile": "sample/junior_high/health/health.json", "questionCount": 3, "questionTypes": "4択・〇×", "previewQuestions": [{"type": "4choice", "question": "言葉を使う・記憶する・理解する・論理的に判断するなど、高度な「知的能力」を司る脳の器官はどこ？"}, {"type": "2choice", "question": "喜怒哀楽などの感情や意欲などの情意機能は、生まれつき決まっていて成長しても変化しない。"}, {"type": "2choice", "question": "「心の健康」を保つためには、知的能力・情意機能・社会性の働きがバランスよく調和することが大切である。"}], "searchText": "セット8: こころの司令塔！「脳の働きと心の健康」 大脳の知的能力、経験による情意機能の発達、心の健康の調和についての3問。 中学校 保健体育 心身の発達と心の健康 言葉を使う・記憶する・理解する・論理的に判断するなど、高度な「知的能力」を司る脳の器官はどこ？ 大脳（大脳皮質）は、思考、学習、記憶、言葉、判断など、人間らしい高度な知的能力のすべてをコントロールしている中枢です。 喜怒哀楽などの感情や意欲などの情意機能は、生まれつき決まっていて成長しても変化しない。 誤り（×）です！感情や意欲などの情意機能は、読書や友達との関わり、成功や失敗といったさまざまな「経験」や「学習」を通して豊かに発達していきます。 「心の健康」を保つためには、知的能力・情意機能・社会性の働きがバランスよく調和することが大切である。 正解！正しい知識（知的能力）、思いやりや意欲（情意機能）、ルールを守り人と協調する力（社会性）がバランスよく働くことで、心が健康に保たれます。"}, {"id": "jh-health-set9", "school": "jh", "schoolName": "中学校", "subject": "health", "subjectName": "保健体育", "topic": "心身の発達と心の健康", "title": "セット9: おとなへのステップ！「思春期の特徴と自己形成」", "description": "精神的自立、親への反抗や葛藤、自立に向けた歩みについての3問。", "dataFile": "sample/junior_high/health/health.json", "questionCount": 3, "questionTypes": "4択・〇×", "previewQuestions": [{"type": "4choice", "question": "大人の保護に依存していた状態から抜け出し、自分自身の考えや責任で行動しようとすることを何という？"}, {"type": "2choice", "question": "思春期に親や先生に対して口答えしたり反抗的な態度をとってしまうのは、自立に向けた自然な葛藤の表れである。"}, {"type": "2choice", "question": "中学生になれば、何の努力や経験もなくても誰でも簡単に自動的に自立できる。"}], "searchText": "セット9: おとなへのステップ！「思春期の特徴と自己形成」 精神的自立、親への反抗や葛藤、自立に向けた歩みについての3問。 中学校 保健体育 心身の発達と心の健康 大人の保護に依存していた状態から抜け出し、自分自身の考えや責任で行動しようとすることを何という？ 思春期は「精神的自立」を始める大切な時期です。自分で考え、自分の責任で判断して行動できる大人へと少しずつ歩みを進めていきます。 思春期に親や先生に対して口答えしたり反抗的な態度をとってしまうのは、自立に向けた自然な葛藤の表れである。 正解！自立したいという気持ちと、まだ甘えたい依存心が心の中でぶつかり合い、口答えや反抗として表れやすくなります。これも大人の階段を登る自然な過程です。 中学生になれば、何の努力や経験もなくても誰でも簡単に自動的に自立できる。 誤り（×）です！自立は年齢が上がれば勝手にできるものではなく、日々の生活経験や失敗、友人や周囲の人との関わりを通して少しずつ身についていくものです。"}, {"id": "jh-health-set10", "school": "jh", "schoolName": "中学校", "subject": "health", "subjectName": "保健体育", "topic": "心身の発達と心の健康", "title": "セット10: 総まとめ！「思春期マスター総合クイズ」", "description": "成長の個人差の尊重、生活習慣の基本、相談の大切さについての総まとめ3問。", "dataFile": "sample/junior_high/health/health.json", "questionCount": 3, "questionTypes": "〇×", "previewQuestions": [{"type": "2choice", "question": "思春期の身体や心の発育スピードには大きな「個人差」があるため、他人と違っていても焦ったり劣等感を持つ必要はない。"}, {"type": "2choice", "question": "思春期の心身の健康を支える基本は、「バランスの良い食事」「適度な運動」「十分な睡眠・休養」の3つである。"}, {"type": "2choice", "question": "悩みや不安、希望などを何でも相談できる親友や、信頼できる大人を持つことは心の健康に役立つ。"}], "searchText": "セット10: 総まとめ！「思春期マスター総合クイズ」 成長の個人差の尊重、生活習慣の基本、相談の大切さについての総まとめ3問。 中学校 保健体育 心身の発達と心の健康 思春期の身体や心の発育スピードには大きな「個人差」があるため、他人と違っていても焦ったり劣等感を持つ必要はない。 正解！成長の早い・遅いは一人ひとり違います。自分の個性を受け止め、お互いの成長の違いを認め合って尊重することが大切です。 思春期の心身の健康を支える基本は、「バランスの良い食事」「適度な運動」「十分な睡眠・休養」の3つである。 正解！急速に身体が大きくなり、勉強や部活でエネルギーを使う思春期だからこそ、食事・運動・睡眠の基本的生活習慣が健康な成長の土台になります。 悩みや不安、希望などを何でも相談できる親友や、信頼できる大人を持つことは心の健康に役立つ。 正解！思春期は心に悩みや不安を抱えやすい時期です。自分の思いを話せる友人や、家族・先生・相談員など信頼できる大人を持つことが大きな支えになります。"}, {"id": "jh-history-set1", "school": "jh", "schoolName": "中学校", "subject": "social_history", "subjectName": "社会（歴史）", "topic": "1. 古代（縄文〜平安）", "title": "セット1: 縄文・弥生・古墳時代", "description": "縄文土器と弥生土器の違い、稲作の始まり、大仙陵古墳などの古墳時代についての3問。", "dataFile": "sample/junior_high/history/history.json", "questionCount": 3, "questionTypes": "4択・〇×", "previewQuestions": [{"type": "4choice", "question": "約1万数千年前から始まった縄文時代の人々が、煮炊きや貯蔵に使った土器の特徴として正しいものはどれでしょう？"}, {"type": "4choice", "question": "弥生時代に大陸から伝わり、人々の定住や貧富の差・身分の違いを生む大きなきっかけとなったものは何でしょう？"}, {"type": "2choice", "question": "古墳時代に造られた「前方後円墳」の代表例である大仙陵古墳（仁徳天皇陵古墳）は、大阪府堺市にある日本最大の古墳である。"}], "searchText": "セット1: 縄文・弥生・古墳時代 縄文土器と弥生土器の違い、稲作の始まり、大仙陵古墳などの古墳時代についての3問。 中学校 社会（歴史） 1. 古代（縄文〜平安） 約1万数千年前から始まった縄文時代の人々が、煮炊きや貯蔵に使った土器の特徴として正しいものはどれでしょう？ 縄文土器は低い温度で焼かれたため厚手で黒っぽく、表面に縄目の文様（縄文）があるのが特徴です。弥生時代になると、うす手でかたい弥生土器が使われるようになります。 弥生時代に大陸から伝わり、人々の定住や貧富の差・身分の違いを生む大きなきっかけとなったものは何でしょう？ 弥生時代に水田での稲作が広まると、収穫したお米を貯蔵できるようになりました。その結果、食料や土地をめぐる争いや貧富の差が生まれ、やがて小さな「クニ」ができていきました。 古墳時代に造られた「前方後円墳」の代表例である大仙陵古墳（仁徳天皇陵古墳）は、大阪府堺市にある日本最大の古墳である。 正解！鍵穴のような形をした前方後円墳は、大和政権（ヤマト王権）の強い権力を示すシンボルでした。中でも大阪府堺市の大仙陵古墳は、世界最大級の墳墓の一つです。"}, {"id": "jh-history-set2", "school": "jh", "schoolName": "中学校", "subject": "social_history", "subjectName": "社会（歴史）", "topic": "1. 古代（縄文〜平安）", "title": "セット2: 飛鳥時代（聖徳太子と大化の改新）", "description": "聖徳太子の政治（冠位十二階・十七条の憲法）、法隆寺、大化の改新についての3問。", "dataFile": "sample/junior_high/history/history.json", "questionCount": 3, "questionTypes": "4択・〇×", "previewQuestions": [{"type": "4choice", "question": "推古天皇の摂政として活躍した聖徳太子が、家柄にとらわれず能力のある人を役人に登用するために定めた制度は何でしょう？"}, {"type": "4choice", "question": "645年、中大兄皇子と中臣鎌足らが蘇我氏を倒し、天皇中心の国づくりを目指して始めた政治改革を何というでしょう？"}, {"type": "2choice", "question": "聖徳太子が建てたとされる奈良県の「法隆寺」は、現在残っている木造建築としては世界最古の建物である。"}], "searchText": "セット2: 飛鳥時代（聖徳太子と大化の改新） 聖徳太子の政治（冠位十二階・十七条の憲法）、法隆寺、大化の改新についての3問。 中学校 社会（歴史） 1. 古代（縄文〜平安） 推古天皇の摂政として活躍した聖徳太子が、家柄にとらわれず能力のある人を役人に登用するために定めた制度は何でしょう？ 「冠位十二階」は、冠の色で12の位を表し、有力豪族だけでなく才能ある人物を取り立てる仕組みでした。同じころ「十七条の憲法」も定めて役人の心構えを示しました。 645年、中大兄皇子と中臣鎌足らが蘇我氏を倒し、天皇中心の国づくりを目指して始めた政治改革を何というでしょう？ 645年に始まった「大化の改新」では、土地と人民をすべて国のものとする「公地公民」の原則が打ち出されました。日本で最初の年号「大化」が使われたことでも有名です。 聖徳太子が建てたとされる奈良県の「法隆寺」は、現在残っている木造建築としては世界最古の建物である。 正解！法隆寺の五重塔や金堂などは飛鳥時代の建築様式を今に伝える「世界最古の木造建築群」であり、1993年に日本で初めてユネスコの世界文化遺産に登録されました。"}, {"id": "jh-history-set3", "school": "jh", "schoolName": "中学校", "subject": "social_history", "subjectName": "社会（歴史）", "topic": "1. 古代（縄文〜平安）", "title": "セット3: 奈良時代（平城京と天平文化）", "description": "平城京の誕生、聖武天皇と東大寺の大仏、墾田永年私財法についての3問。", "dataFile": "sample/junior_high/history/history.json", "questionCount": 3, "questionTypes": "4択・〇×", "previewQuestions": [{"type": "4choice", "question": "710年、唐の長安をモデルにして現在の奈良県に造られた都を何というでしょう？"}, {"type": "4choice", "question": "奈良時代、飢きんや疫病から国を守るために「仏教の力」に頼ろうとした聖武天皇が、奈良の都に造らせたものは何でしょう？"}, {"type": "2choice", "question": "743年に朝廷が出した「墾田永年私財法」により、自分で新しく開墾した土地は、一生だけでなく永久に自分の土地（私有地）にできるようになった。"}], "searchText": "セット3: 奈良時代（平城京と天平文化） 平城京の誕生、聖武天皇と東大寺の大仏、墾田永年私財法についての3問。 中学校 社会（歴史） 1. 古代（縄文〜平安） 710年、唐の長安をモデルにして現在の奈良県に造られた都を何というでしょう？ 「なんと（710）立派な平城京」の語呂合わせで有名な平城京です！ちなみに794年に移された京都の都が「平安京（なくよ794うぐいす平安京）」です。 奈良時代、飢きんや疫病から国を守るために「仏教の力」に頼ろうとした聖武天皇が、奈良の都に造らせたものは何でしょう？ 聖武天皇は全国に国分寺・国分尼寺を建てさせ、その中心として奈良の東大寺に巨大な大仏（盧舎那仏）を造りました。行基などの協力もあり、752年に大仏開眼供養が行われました。 743年に朝廷が出した「墾田永年私財法」により、自分で新しく開墾した土地は、一生だけでなく永久に自分の土地（私有地）にできるようになった。 正解！口分田が不足したため、開墾を奨励する目的で「墾田永年私財法」が出されました。これにより貴族や寺社が広大な私有地（荘園）を持つようになり、公地公民の仕組みが崩れていきました。"}, {"id": "jh-history-set4", "school": "jh", "schoolName": "中学校", "subject": "social_history", "subjectName": "社会（歴史）", "topic": "1. 古代（縄文〜平安）", "title": "セット4: 平安時代（国風文化と武士の台頭）", "description": "藤原氏の摂関政治、かな文字と国風文化、平清盛などの武士の台頭についての3問。", "dataFile": "sample/junior_high/history/history.json", "questionCount": 3, "questionTypes": "4択・〇×", "previewQuestions": [{"type": "4choice", "question": "平安時代の中ごろ、天皇が幼いときは「摂政」、成人してからは「関白」となって政治の実権をにぎり、全盛期を築いた一族はどれでしょう？"}, {"type": "4choice", "question": "平安時代に日本独自の「かな文字」が広まり、紫式部の『源氏物語』や清少納言の『枕草子』などが生まれた文化を何というでしょう？"}, {"type": "2choice", "question": "平安時代の終わりごろ、武士として初めて太政大臣にまで出世し、日宋貿易で大きな利益を上げたのは「源頼朝」である。"}], "searchText": "セット4: 平安時代（国風文化と武士の台頭） 藤原氏の摂関政治、かな文字と国風文化、平清盛などの武士の台頭についての3問。 中学校 社会（歴史） 1. 古代（縄文〜平安） 平安時代の中ごろ、天皇が幼いときは「摂政」、成人してからは「関白」となって政治の実権をにぎり、全盛期を築いた一族はどれでしょう？ 藤原道長・頼通の父子の時代に摂関政治は絶頂期を迎えました。道長が詠んだ「この世をば わが世とぞ思ふ 望月の…」の歌はとても有名ですね。 平安時代に日本独自の「かな文字」が広まり、紫式部の『源氏物語』や清少納言の『枕草子』などが生まれた文化を何というでしょう？ 遣唐使の廃止（894年）後、唐の文化をそのまま真似るのではなく、日本の風土や生活に合った優雅な「国風文化」が花開きました。十二単や寝殿造もこの時代の特徴です。 平安時代の終わりごろ、武士として初めて太政大臣にまで出世し、日宋貿易で大きな利益を上げたのは「源頼朝」である。 ひっかけ問題！武士として初めて太政大臣になり日宋貿易を進めたのは「平清盛（たいらのきよもり）」です。その後、壇ノ浦の戦いで平氏を滅ぼして鎌倉幕府を開いたのが源頼朝です。"}, {"id": "jh-history-set5", "school": "jh", "schoolName": "中学校", "subject": "social_history", "subjectName": "社会（歴史）", "topic": "2. 中世（鎌倉〜室町）", "title": "セット5: 鎌倉時代（幕府の成立と元寇）", "description": "源頼朝の鎌倉幕府、守護と地頭、御成敗式目、2度の元寇についての3問。", "dataFile": "sample/junior_high/history/history.json", "questionCount": 3, "questionTypes": "4択・〇×", "previewQuestions": [{"type": "4choice", "question": "鎌倉幕府を開いた源頼朝が、国ごとに置いて治安維持にあたらせた役職と、荘園・公領ごとに置いて税の取り立てをさせた役職の組み合わせはどれでしょう？"}, {"type": "4choice", "question": "1232年、第3代執権の北条泰時が、裁判の公平さを保つために定めた武家社会で最初の成文法（ルールブック）を何というでしょう？"}, {"type": "2choice", "question": "13世紀後半にモンゴル帝国（元）が2度にわたって日本に攻めてきた「元寇（文永の役・弘安の役）」では、御家人たちの防戦や暴風雨により撃退することができた。"}], "searchText": "セット5: 鎌倉時代（幕府の成立と元寇） 源頼朝の鎌倉幕府、守護と地頭、御成敗式目、2度の元寇についての3問。 中学校 社会（歴史） 2. 中世（鎌倉〜室町） 鎌倉幕府を開いた源頼朝が、国ごとに置いて治安維持にあたらせた役職と、荘園・公領ごとに置いて税の取り立てをさせた役職の組み合わせはどれでしょう？ 頼朝は全国の国に「守護」、荘園や公領に「地頭」を配置し、御家人との間に「ご恩と奉公」という主従関係を結びました。これが武家政治の本格的な始まりです。 1232年、第3代執権の北条泰時が、裁判の公平さを保つために定めた武家社会で最初の成文法（ルールブック）を何というでしょう？ それまでの朝廷の法律ではなく、武士の間の道徳や慣習をまとめた全51か条の「御成敗式目」が制定されました。このルールは後の江戸時代まで長く手本とされました。 13世紀後半にモンゴル帝国（元）が2度にわたって日本に攻めてきた「元寇（文永の役・弘安の役）」では、御家人たちの防戦や暴風雨により撃退することができた。 正解！石塁（防塁）を築いた武士たちの防戦と、暴風雨による元軍の撤退により日本を守り抜きました。しかし新しい領地が増えなかったため恩賞が不足し、幕府が衰退する原因となりました。"}, {"id": "jh-history-set6", "school": "jh", "schoolName": "中学校", "subject": "social_history", "subjectName": "社会（歴史）", "topic": "2. 中世（鎌倉〜室町）", "title": "セット6: 室町時代（金閣・銀閣と下剋上）", "description": "足利義満の勘合貿易・北山文化、応仁の乱、東山文化（銀閣）についての3問。", "dataFile": "sample/junior_high/history/history.json", "questionCount": 3, "questionTypes": "4択・〇×", "previewQuestions": [{"type": "4choice", "question": "第3代将軍の足利義満が、倭寇（海賊）と区別するための「勘合（合い札）」を使って行った中国（明）との貿易を何というでしょう？"}, {"type": "4choice", "question": "1467年、将軍の後継ぎ争いなどをきっかけに京都で始まり、約11年間も続いて京都を焼け野原にした大きな戦乱は何でしょう？"}, {"type": "2choice", "question": "第8代将軍の足利義政が建てた「銀閣」を中心とする東山文化からは、今日の茶道や生け花（華道）、書院造などにつながる日本の伝統文化が多く生まれた。"}], "searchText": "セット6: 室町時代（金閣・銀閣と下剋上） 足利義満の勘合貿易・北山文化、応仁の乱、東山文化（銀閣）についての3問。 中学校 社会（歴史） 2. 中世（鎌倉〜室町） 第3代将軍の足利義満が、倭寇（海賊）と区別するための「勘合（合い札）」を使って行った中国（明）との貿易を何というでしょう？ 明との正式な貿易船であることを証明する「勘合」を持たせたことから「勘合貿易」と呼ばれます。これにより莫大な利益を得た義満は、京都に金閣（鹿苑寺）を建てました。 1467年、将軍の後継ぎ争いなどをきっかけに京都で始まり、約11年間も続いて京都を焼け野原にした大きな戦乱は何でしょう？ 「人の世むな（1467）しい応仁の乱」で覚えやすい大乱です。この戦乱によって幕府の権威は大きく下がり、実力のある者が上の者を倒す「下剋上」の戦国時代へと突入していきました。 第8代将軍の足利義政が建てた「銀閣」を中心とする東山文化からは、今日の茶道や生け花（華道）、書院造などにつながる日本の伝統文化が多く生まれた。 正解！金閣の豪華な「北山文化」に対し、銀閣の「東山文化」はわび・さびを大切にする落ち着いた文化で、現在の和室（畳・障子・床の間がある書院造）の原型が完成しました。"}, {"id": "jh-history-set7", "school": "jh", "schoolName": "中学校", "subject": "social_history", "subjectName": "社会（歴史）", "topic": "3. 近世（安土桃山〜江戸）", "title": "セット7: 安土桃山時代（信長・秀吉の天下統一）", "description": "織田信長の楽市・楽座、豊臣秀吉の太閤検地・刀狩、鉄砲・キリスト教伝来についての3問。", "dataFile": "sample/junior_high/history/history.json", "questionCount": 3, "questionTypes": "4択・〇×", "previewQuestions": [{"type": "4choice", "question": "織田信長が安土城の城下町などで、商工業者の組合である「座」の独占権をなくし、自由な商売を認めた政策を何というでしょう？"}, {"type": "4choice", "question": "豊臣秀吉が全国の田畑の広さや土地のよしあしを統一の基準（京枡など）で調べ、年貢の基準となる収穫高を「石高」で表した政策は何でしょう？"}, {"type": "2choice", "question": "1543年にポルトガル人が種子島に「鉄砲」を伝えた後、1549年にはフランシスコ・ザビエルによって日本にキリスト教が伝えられた。"}], "searchText": "セット7: 安土桃山時代（信長・秀吉の天下統一） 織田信長の楽市・楽座、豊臣秀吉の太閤検地・刀狩、鉄砲・キリスト教伝来についての3問。 中学校 社会（歴史） 3. 近世（安土桃山〜江戸） 織田信長が安土城の城下町などで、商工業者の組合である「座」の独占権をなくし、自由な商売を認めた政策を何というでしょう？ 信長は「楽市・楽座」によって市場の税や関所をなくし、商業を活発にして経済力を大きく伸ばしました。また鉄砲を組織的に活用して長篠の戦いに勝利したことも有名です。 豊臣秀吉が全国の田畑の広さや土地のよしあしを統一の基準（京枡など）で調べ、年貢の基準となる収穫高を「石高」で表した政策は何でしょう？ 「太閤検地」によって耕作者が検地帳に登録され、同時に実施した「刀狩」と合わせて、武士と農民の身分を厳しく分ける「兵農分離」が完成しました。 1543年にポルトガル人が種子島に「鉄砲」を伝えた後、1549年にはフランシスコ・ザビエルによって日本にキリスト教が伝えられた。 正解！「いごよ（1543）く伝わる鉄砲」「いごよ（1549）く広まるキリスト教」の順です。これらをきっかけにヨーロッパの人々（南蛮人）との「南蛮貿易」が盛んになりました。"}, {"id": "jh-history-set8", "school": "jh", "schoolName": "中学校", "subject": "social_history", "subjectName": "社会（歴史）", "topic": "3. 近世（安土桃山〜江戸）", "title": "セット8: 江戸時代（幕藩体制・鎖国・開国）", "description": "参勤交代、鎖国と長崎出島の貿易、ペリー来航による開国についての3問。", "dataFile": "sample/junior_high/history/history.json", "questionCount": 3, "questionTypes": "4択・〇×", "previewQuestions": [{"type": "4choice", "question": "江戸幕府の第3代将軍・徳川家光が大名たちを従わせるために義務づけた、1年おきに江戸と自分の領地を行き来させる制度を何というでしょう？"}, {"type": "4choice", "question": "鎖国中も、幕府が長崎の出島に貿易を許したヨーロッパの国はどこでしょう？（中国と合わせて2か国のみ貿易）"}, {"type": "2choice", "question": "1853年、アメリカ合衆国のペリーが黒船を率いて浦賀に現れ、日本に開国を求めた結果、翌年に日米和親条約が結ばれて鎖国が終わった。"}], "searchText": "セット8: 江戸時代（幕藩体制・鎖国・開国） 参勤交代、鎖国と長崎出島の貿易、ペリー来航による開国についての3問。 中学校 社会（歴史） 3. 近世（安土桃山〜江戸） 江戸幕府の第3代将軍・徳川家光が大名たちを従わせるために義務づけた、1年おきに江戸と自分の領地を行き来させる制度を何というでしょう？ 大名に妻子を江戸に住まわせ、莫大な費用がかかる行列で往復させる「参勤交代」により、大名が幕府に反抗する力を弱めました。一方で街道や宿場町が発達するきっかけにもなりました。 鎖国中も、幕府が長崎の出島に貿易を許したヨーロッパの国はどこでしょう？（中国と合わせて2か国のみ貿易） キリスト教を広めずに貿易だけを行うと約束した「オランダ」と「中国（清）」の船だけが長崎での貿易を許されました。その他、朝鮮・琉球王国・アイヌの人々とも交流を続けていました。 1853年、アメリカ合衆国のペリーが黒船を率いて浦賀に現れ、日本に開国を求めた結果、翌年に日米和親条約が結ばれて鎖国が終わった。 正解！1854年の「日米和親条約」で下田と函館の2港を開き、さらに1858年の「日米修好通商条約」で自由貿易が始まりましたが、関税自主権がないなどの不平等条約でした。"}, {"id": "jh-history-set9", "school": "jh", "schoolName": "中学校", "subject": "social_history", "subjectName": "社会（歴史）", "topic": "4. 近代・現代（明治〜現代）", "title": "セット9: 明治〜大正時代（近代国家とデモクラシー）", "description": "大日本帝国憲法、大正デモクラシーと普通選挙法、明治維新の大改革についての3問。", "dataFile": "sample/junior_high/history/history.json", "questionCount": 3, "questionTypes": "4択・〇×", "previewQuestions": [{"type": "4choice", "question": "1889年、アジアで最初の近代憲法として発布され、翌年の第1回帝国議会開設へとつながった憲法は何でしょう？"}, {"type": "4choice", "question": "大正時代、国民が自由や権利を求めて盛り上がった「大正デモクラシー」の流れの中で、1925年に成立した選挙に関する法律はどれでしょう？"}, {"type": "2choice", "question": "明治時代、新政府が近代化を進めるために「廃藩置県」「学制」「徴兵令」「地租改正」などの大改革を行い、富国強兵と殖産興業を目指した。"}], "searchText": "セット9: 明治〜大正時代（近代国家とデモクラシー） 大日本帝国憲法、大正デモクラシーと普通選挙法、明治維新の大改革についての3問。 中学校 社会（歴史） 4. 近代・現代（明治〜現代） 1889年、アジアで最初の近代憲法として発布され、翌年の第1回帝国議会開設へとつながった憲法は何でしょう？ 伊藤博文らが中心となってプロイセン（ドイツ）の憲法を参考に作成した「大日本帝国憲法」が発布され、日本は立憲主義の国となりました。 大正時代、国民が自由や権利を求めて盛り上がった「大正デモクラシー」の流れの中で、1925年に成立した選挙に関する法律はどれでしょう？ 納税額による制限をなくし、満25歳以上のすべての男子に選挙権を与えた「普通選挙法」が1925年に成立しました。（※同じ年に社会主義運動などを取り締まる治安維持法も作られました） 明治時代、新政府が近代化を進めるために「廃藩置県」「学制」「徴兵令」「地租改正」などの大改革を行い、富国強兵と殖産興業を目指した。 正解！これらの「明治維新」の改革と、官営模範工場の代表である富岡製糸場の設立などにより、日本は急速に近代産業国家へと発展していきました。"}, {"id": "jh-history-set10", "school": "jh", "schoolName": "中学校", "subject": "social_history", "subjectName": "社会（歴史）", "topic": "4. 近代・現代（明治〜現代）", "title": "セット10: 昭和〜現代（戦後復興と現代の日本）", "description": "日本国憲法の三大原則、国際連合への加盟と高度経済成長、沖縄本土復帰についての3問。", "dataFile": "sample/junior_high/history/history.json", "questionCount": 3, "questionTypes": "4択・〇×", "previewQuestions": [{"type": "4choice", "question": "1946年に公布され、翌年5月3日に施行された「日本国憲法」の三大原則の組み合わせとして正しいものはどれでしょう？"}, {"type": "4choice", "question": "日本が国際社会への復帰を果たした1956年（昭和31年）に、日本が加盟を認められた世界最大の国際組織は何でしょう？"}, {"type": "2choice", "question": "1972年5月15日、第二次世界大戦後からアメリカの統治下にあった沖縄が日本に返還（本土復帰）された。"}], "searchText": "セット10: 昭和〜現代（戦後復興と現代の日本） 日本国憲法の三大原則、国際連合への加盟と高度経済成長、沖縄本土復帰についての3問。 中学校 社会（歴史） 4. 近代・現代（明治〜現代） 1946年に公布され、翌年5月3日に施行された「日本国憲法」の三大原則の組み合わせとして正しいものはどれでしょう？ 「国民主権」「基本的人権の尊重」「平和主義」が日本国憲法の三大原則です！ちなみに公布日の11月3日は「文化の日」、施行日の5月3日は「憲法記念日」になっています。 日本が国際社会への復帰を果たした1956年（昭和31年）に、日本が加盟を認められた世界最大の国際組織は何でしょう？ 1956年に日ソ共同宣言によってソ連と国交を回復したことで、日本は国際連合（UN）への加盟が認められました。その後、1964年には東京オリンピックや新幹線開通とともに高度経済成長が進みました。 1972年5月15日、第二次世界大戦後からアメリカの統治下にあった沖縄が日本に返還（本土復帰）された。 正解！佐藤栄作首相らの交渉により、1972年に沖縄の施政権が日本へ返還されました。同じ1972年には日中共同声明が出され、中国との国交も正常化されました。"}, {"id": "jh-geo-set1", "school": "jh", "schoolName": "中学校", "subject": "social_geo", "subjectName": "社会（地理）", "topic": "1. 世界の姿と地域", "title": "セット1: 地球の姿・緯度と経度・時差", "description": "六大陸と三大洋、赤道・本初子午線、経度と時差の計算についての3問。", "dataFile": "sample/junior_high/geography/geography.json", "questionCount": 3, "questionTypes": "4択・〇×", "previewQuestions": [{"type": "4choice", "question": "地球上にある6つの大陸のうち、面積が最も大きい大陸はどれでしょう？"}, {"type": "4choice", "question": "イギリスのロンドンを通る、経度0度の基準となる線を何というでしょう？"}, {"type": "2choice", "question": "経度が15度ちがうごとに、世界では1時間の時差が生じる。"}], "searchText": "セット1: 地球の姿・緯度と経度・時差 六大陸と三大洋、赤道・本初子午線、経度と時差の計算についての3問。 中学校 社会（地理） 1. 世界の姿と地域 地球上にある6つの大陸のうち、面積が最も大きい大陸はどれでしょう？ ユーラシア大陸はアジアとヨーロッパを含む世界最大の大陸で、地球の陸地の約3分の1以上を占めています。 イギリスのロンドンを通る、経度0度の基準となる線を何というでしょう？ ロンドン郊外の旧グリニッジ天文台を通る経度0度の線が「本初子午線」です。ちなみに日本の標準時子午線は東経135度（兵庫県明石市などを通過）です。 経度が15度ちがうごとに、世界では1時間の時差が生じる。 正解！地球は24時間で1回転（360度）するため、360 ÷ 24 = 15度ごとに1時間の時差が生まれます。東経135度の日本は、経度0度のロンドンより9時間進んでいます。"}, {"id": "jh-geo-set2", "school": "jh", "schoolName": "中学校", "subject": "social_geo", "subjectName": "社会（地理）", "topic": "1. 世界の姿と地域", "title": "セット2: 世界の気候帯と人々のくらし", "description": "熱帯・乾燥帯・温帯・冷帯・寒帯の気候区分と生活の工夫についての3問。", "dataFile": "sample/junior_high/geography/geography.json", "questionCount": 3, "questionTypes": "4択・〇×", "previewQuestions": [{"type": "4choice", "question": "一年中気温が高く降水量も多い赤道周辺の「熱帯」で、スコールが降る地域に見られる住居の工夫はどれでしょう？"}, {"type": "4choice", "question": "サハラ砂漠などの「乾燥帯」で、水や草を求めて移動しながらラクダやヒツジを育てる生活様式を何というでしょう？"}, {"type": "2choice", "question": "同じ緯度に位置する東京とイタリアのローマを比較すると、夏は乾燥し冬に雨が多い「地中海性気候」にあたるのは東京である。"}], "searchText": "セット2: 世界の気候帯と人々のくらし 熱帯・乾燥帯・温帯・冷帯・寒帯の気候区分と生活の工夫についての3問。 中学校 社会（地理） 1. 世界の姿と地域 一年中気温が高く降水量も多い赤道周辺の「熱帯」で、スコールが降る地域に見られる住居の工夫はどれでしょう？ 熱帯の地域では、高温多湿や害虫・洪水を防ぐため、床を高くして風通しを良くした「高床式住居」が多く見られます。 サハラ砂漠などの「乾燥帯」で、水や草を求めて移動しながらラクダやヒツジを育てる生活様式を何というでしょう？ 雨が少なく農作物が育ちにくいステップや砂漠の周辺では、家畜と水草を求めて移動する「遊牧」や、オアシス周辺での灌漑農業が行われます。 同じ緯度に位置する東京とイタリアのローマを比較すると、夏は乾燥し冬に雨が多い「地中海性気候」にあたるのは東京である。 ひっかけ問題！ローマなどの南ヨーロッパが「地中海性気候」（夏の乾燥に強いオリーブやブドウの栽培が盛ん）です。東京は四季の変化がはっきりした温暖湿潤気候です。"}, {"id": "jh-geo-set3", "school": "jh", "schoolName": "中学校", "subject": "social_geo", "subjectName": "社会（地理）", "topic": "1. 世界の姿と地域", "title": "セット3: 世界の国々と州の特色", "description": "アジア・ヨーロッパ・アフリカ・アメリカ州の地域的特徴についての3問。", "dataFile": "sample/junior_high/geography/geography.json", "questionCount": 3, "questionTypes": "4択・〇×", "previewQuestions": [{"type": "4choice", "question": "アメリカ合衆国で、同じ作物（トウモロコシや小麦など）を広い土地で適した地域を選んで大規模に育てる農業の仕組みを何というでしょう？"}, {"type": "4choice", "question": "ヨーロッパの多くの国が加盟し、国境を越えて人や物・お金が自由に行き来でき、共通通貨「ユーロ」も使われている地域統合組織はどれでしょう？"}, {"type": "2choice", "question": "アフリカ大陸の国境線には、過去の植民地支配の影響から、緯線や経線に沿った直線的な国境が多く見られる。"}], "searchText": "セット3: 世界の国々と州の特色 アジア・ヨーロッパ・アフリカ・アメリカ州の地域的特徴についての3問。 中学校 社会（地理） 1. 世界の姿と地域 アメリカ合衆国で、同じ作物（トウモロコシや小麦など）を広い土地で適した地域を選んで大規模に育てる農業の仕組みを何というでしょう？ アメリカでは気候や地形に合わせて、西経100度より東はトウモロコシや大豆、西は小麦や放牧など「適地適作」による大規模な商業的農業が行われています。 ヨーロッパの多くの国が加盟し、国境を越えて人や物・お金が自由に行き来でき、共通通貨「ユーロ」も使われている地域統合組織はどれでしょう？ EU（ヨーロッパ連合）は経済や政治での協力を深めるためにつくられ、パスポートなしでの移動や単一通貨ユーロの導入などを行っています。 アフリカ大陸の国境線には、過去の植民地支配の影響から、緯線や経線に沿った直線的な国境が多く見られる。 正解！19世紀にヨーロッパ列強がアフリカを分割した際、現地の民族や地形を無視して地図上で定規を引くように国境を決めたため、直線的な国境が多く残っています。"}, {"id": "jh-geo-set4", "school": "jh", "schoolName": "中学校", "subject": "social_geo", "subjectName": "社会（地理）", "topic": "2. 日本の姿と産業", "title": "セット4: 日本の位置・領土と地形", "description": "日本の東西南北端、排他的経済水域（EEZ）、日本の山地と平野についての3問。", "dataFile": "sample/junior_high/geography/geography.json", "questionCount": 3, "questionTypes": "4択・〇×", "previewQuestions": [{"type": "4choice", "question": "日本の領土の「最南端」と「最東端」の組み合わせとして正しいものはどれでしょう？"}, {"type": "4choice", "question": "日本の国土のうち、山地や丘陵などが占める割合はおよそ何％くらいでしょう？"}, {"type": "2choice", "question": "沿岸から200海里までの範囲で、水産資源や海底の鉱物資源を優先的に利用できる海域を「排他的経済水域（EEZ）」という。"}], "searchText": "セット4: 日本の位置・領土と地形 日本の東西南北端、排他的経済水域（EEZ）、日本の山地と平野についての3問。 中学校 社会（地理） 2. 日本の姿と産業 日本の領土の「最南端」と「最東端」の組み合わせとして正しいものはどれでしょう？ 最北端が択捉島（北海道）、最西端が与那国島（沖縄県）、最南端が沖ノ鳥島（東京都）、最東端が南鳥島（東京都）です。特に沖ノ鳥島は広大な排他的経済水域（EEZ）を守る重要な島です！ 日本の国土のうち、山地や丘陵などが占める割合はおよそ何％くらいでしょう？ 日本の国土の約4分の3（約75％）は山地や丘陵地で、森林が国土の約3分の2を占めています。そのため川は短く流れが急で、河口には扇状地や三角州などの平野ができます。 沿岸から200海里までの範囲で、水産資源や海底の鉱物資源を優先的に利用できる海域を「排他的経済水域（EEZ）」という。 正解！領海（12海里）の外側にある「排他的経済水域」は、他国の船の航行は自由ですが、魚や石油・メタンハイドレートなどの資源に関する権利は沿岸国が独占します。"}, {"id": "jh-geo-set5", "school": "jh", "schoolName": "中学校", "subject": "social_geo", "subjectName": "社会（地理）", "topic": "2. 日本の姿と産業", "title": "セット5: 日本の気候と自然災害", "description": "季節風と海流、6つの気候区分、ハザードマップと防災についての3問。", "dataFile": "sample/junior_high/geography/geography.json", "questionCount": 3, "questionTypes": "4択・〇×", "previewQuestions": [{"type": "4choice", "question": "冬の日本海側（北陸や東北の日本海側など）に世界有数の大雪をもたらす主な原因となる風と海流の組み合わせはどれでしょう？"}, {"type": "4choice", "question": "九州地方と本州の間の瀬戸内海沿岸（瀬戸内の気候）に見られる気候の特徴として正しいものはどれでしょう？"}, {"type": "2choice", "question": "洪水・津波・土砂災害などの危険が予想される場所や避難場所を示した地図を「ハザードマップ（防災マップ）」という。"}], "searchText": "セット5: 日本の気候と自然災害 季節風と海流、6つの気候区分、ハザードマップと防災についての3問。 中学校 社会（地理） 2. 日本の姿と産業 冬の日本海側（北陸や東北の日本海側など）に世界有数の大雪をもたらす主な原因となる風と海流の組み合わせはどれでしょう？ 冬にシベリアから吹く冷たい「北西の季節風」が、日本海を流れる暖かい「対馬海流」から大量の水蒸気を受け取り、日本の脊梁山脈にぶつかって大雪を降らせます。 九州地方と本州の間の瀬戸内海沿岸（瀬戸内の気候）に見られる気候の特徴として正しいものはどれでしょう？ 瀬戸内地方は中国山地と四国山地に挟まれているため、季節風が山を越える際に水分を落とし、年間を通して雨が少なく温暖な気候になります（ため池が多いのもこのため）。 洪水・津波・土砂災害などの危険が予想される場所や避難場所を示した地図を「ハザードマップ（防災マップ）」という。 正解！日本は環太平洋造山帯に位置し、地震・火山・台風などの自然災害が多い国です。日頃から自宅や学校周辺のハザードマップを確認しておくことが命を守ります。"}, {"id": "jh-geo-set6", "school": "jh", "schoolName": "中学校", "subject": "social_geo", "subjectName": "社会（地理）", "topic": "2. 日本の姿と産業", "title": "セット6: 日本の資源・エネルギーと産業", "description": "エネルギー自給率と再生可能エネルギー、日本の工業地帯・工業地域についての3問。", "dataFile": "sample/junior_high/geography/geography.json", "questionCount": 3, "questionTypes": "4択・〇×", "previewQuestions": [{"type": "4choice", "question": "日本のエネルギー自給率は先進国の中で低い水準ですが、近年注目されている太陽光・風力・地熱・水力・バイオマスなどのエネルギーをまとめて何というでしょう？"}, {"type": "4choice", "question": "愛知県を中心に自動車工業（トヨタなど）が非常に発達し、工業製品出荷額が長年日本一となっている工業地帯はどれでしょう？"}, {"type": "2choice", "question": "高速道路のインターチェンジや空港の近くに立地し、重さは軽いが値段の高いIC（集積回路）などを製造する工業を「臨海型工業」という。"}], "searchText": "セット6: 日本の資源・エネルギーと産業 エネルギー自給率と再生可能エネルギー、日本の工業地帯・工業地域についての3問。 中学校 社会（地理） 2. 日本の姿と産業 日本のエネルギー自給率は先進国の中で低い水準ですが、近年注目されている太陽光・風力・地熱・水力・バイオマスなどのエネルギーをまとめて何というでしょう？ 自然界に常に存在する太陽や風、地熱（大分県や東北などで盛ん）などを使い、CO2をほとんど出さずにくり返し利用できるエネルギーを「再生可能エネルギー」といいます。 愛知県を中心に自動車工業（トヨタなど）が非常に発達し、工業製品出荷額が長年日本一となっている工業地帯はどれでしょう？ 名古屋市や豊田市を中心とする「中京工業地帯」は、輸送用機械（自動車など）の生産が圧倒的で、日本の工業製品出荷額で第1位を誇ります。 高速道路のインターチェンジや空港の近くに立地し、重さは軽いが値段の高いIC（集積回路）などを製造する工業を「臨海型工業」という。 ひっかけ問題！ICなどの先端技術産業が内陸の高速道路や空港近くに立地する形は「内陸型工業（臨空型工業）」です。「臨海型工業」は石油化学や製鉄など重い原料を輸入する港の近くに立地します。"}, {"id": "jh-geo-set7", "school": "jh", "schoolName": "中学校", "subject": "social_geo", "subjectName": "社会（地理）", "topic": "3. 日本の諸地域", "title": "セット7: 九州地方・中国四国地方", "description": "シラス台地と畜産・IC産業、中国山地・瀬戸内工業地域についての3問。", "dataFile": "sample/junior_high/geography/geography.json", "questionCount": 3, "questionTypes": "4択・〇×", "previewQuestions": [{"type": "4choice", "question": "鹿児島県や宮崎県南部にかけて広がる、火山灰が積もってできた水はけのよい台地で、サツマイモ栽培や肉牛・豚の畜産が盛んな場所を何というでしょう？"}, {"type": "4choice", "question": "九州地方で、福岡空港や大分空港、熊本空港などの周辺に多く進出し、「シリコンアイランド」とも呼ばれた産業は何でしょう？"}, {"type": "2choice", "question": "温暖な高知平野（四国地方）では、ビニールハウスを利用して冬から春に出荷時期を早める「抑制栽培」が盛んに行われている。"}], "searchText": "セット7: 九州地方・中国四国地方 シラス台地と畜産・IC産業、中国山地・瀬戸内工業地域についての3問。 中学校 社会（地理） 3. 日本の諸地域 鹿児島県や宮崎県南部にかけて広がる、火山灰が積もってできた水はけのよい台地で、サツマイモ栽培や肉牛・豚の畜産が盛んな場所を何というでしょう？ 南九州の「シラス台地」は水はけが良すぎるため稲作には不向きでしたが、その特性を活かしてサツマイモなどの畑作や、全国トップクラスの畜産業が発展しました。 九州地方で、福岡空港や大分空港、熊本空港などの周辺に多く進出し、「シリコンアイランド」とも呼ばれた産業は何でしょう？ 豊かなきれいな水と労働力、そして空輸に便利な空港が多いことから半導体関連工場が集積し、九州は「シリコンアイランド」と呼ばれました。近年も新工場建設が進んでいます！ 温暖な高知平野（四国地方）では、ビニールハウスを利用して冬から春に出荷時期を早める「抑制栽培」が盛んに行われている。 ひっかけ問題！暖かい気候やビニールハウスを利用して他の地域より「早く」出荷するのは「促成栽培（そくせいさいばい）」です！「抑制栽培」は長野県などの冷涼な高地で夏に出荷時期を「遅らせる」方法です。"}, {"id": "jh-geo-set8", "school": "jh", "schoolName": "中学校", "subject": "social_geo", "subjectName": "社会（地理）", "topic": "3. 日本の諸地域", "title": "セット8: 近畿地方・中部地方", "description": "京阪神大都市圏、東海・中央高地・北陸の工業や農業についての3問。", "dataFile": "sample/junior_high/geography/geography.json", "questionCount": 3, "questionTypes": "4択・〇×", "previewQuestions": [{"type": "4choice", "question": "京都の西陣織や輪島塗、名古屋の陶磁器など、その土地の歴史の中で受け継がれてきた伝統的な工業を何というでしょう？"}, {"type": "4choice", "question": "中部地方の中央高地（長野県など）の涼しい気候を生かして、夏にレタスやキャベツを出荷する農業を何というでしょう？"}, {"type": "2choice", "question": "近畿地方にある日本最大の湖「琵琶湖」は、滋賀県だけでなく京都府や大阪府などの人々にとっても大切な飲み水（水がめ）となっている。"}], "searchText": "セット8: 近畿地方・中部地方 京阪神大都市圏、東海・中央高地・北陸の工業や農業についての3問。 中学校 社会（地理） 3. 日本の諸地域 京都の西陣織や輪島塗、名古屋の陶磁器など、その土地の歴史の中で受け継がれてきた伝統的な工業を何というでしょう？ 近畿や北陸など歴史ある地域では、昔ながらの技術と地元の原料を生かした「伝統的工芸品」の生産が今も受け継がれています。 中部地方の中央高地（長野県など）の涼しい気候を生かして、夏にレタスやキャベツを出荷する農業を何というでしょう？ 標高が高く夏でも涼しい長野県の野辺山原などでは、平地で作れない夏場に出荷を合わせる「抑制栽培（高冷地農業）」が盛んです！ 近畿地方にある日本最大の湖「琵琶湖」は、滋賀県だけでなく京都府や大阪府などの人々にとっても大切な飲み水（水がめ）となっている。 正解！琵琶湖の水は瀬田川から宇治川・淀川となって大阪湾へ注いでおり、京阪神約1,400万人の生活や工業を支えるかけがえのない水源です。"}, {"id": "jh-geo-set9", "school": "jh", "schoolName": "中学校", "subject": "social_geo", "subjectName": "社会（地理）", "topic": "3. 日本の諸地域", "title": "セット9: 関東地方の特色と東京大都市圏", "description": "日本最大の関東平野、東京一極集中、近郊農業と輸送網についての3問。", "dataFile": "sample/junior_high/geography/geography.json", "questionCount": 3, "questionTypes": "4択・〇×", "previewQuestions": [{"type": "4choice", "question": "千葉・埼玉・茨城など、大都市東京のすぐ近くで新鮮な野菜や花を育てて素早く出荷する農業を何というでしょう？"}, {"type": "4choice", "question": "昼間は通勤・通学で人口が多く、夜間になると住宅地に人が帰って人口が大きく減る、都心部に起きる現象を何というでしょう？"}, {"type": "2choice", "question": "都市部にアスファルトやコンクリートが増え、冷暖房などの排熱も加わることで、郊外に比べて都市の中心部の気温が高くなる現象を「ヒートアイランド現象」という。"}], "searchText": "セット9: 関東地方の特色と東京大都市圏 日本最大の関東平野、東京一極集中、近郊農業と輸送網についての3問。 中学校 社会（地理） 3. 日本の諸地域 千葉・埼玉・茨城など、大都市東京のすぐ近くで新鮮な野菜や花を育てて素早く出荷する農業を何というでしょう？ 大消費地である大都市の周辺で、輸送費を抑えて新鮮な作物を届ける「近郊農業」が関東平野一帯で盛んに行われています。 昼間は通勤・通学で人口が多く、夜間になると住宅地に人が帰って人口が大きく減る、都心部に起きる現象を何というでしょう？ 都心のオフィス街などは地価が高いため郊外に住宅が広がり、都心の夜の人口が減る「ドーナツ化現象」が起きました。（近年は高層マンション増加で都心回帰も進んでいます） 都市部にアスファルトやコンクリートが増え、冷暖房などの排熱も加わることで、郊外に比べて都市の中心部の気温が高くなる現象を「ヒートアイランド現象」という。 正解！等温線を描くと都市が暖かい「島」のように見えることから「ヒートアイランド現象」と呼ばれます。屋上緑化や風の道づくりなどの対策が進められています。"}, {"id": "jh-geo-set10", "school": "jh", "schoolName": "中学校", "subject": "social_geo", "subjectName": "社会（地理）", "topic": "3. 日本の諸地域", "title": "セット10: 東北・北海道地方", "description": "東北の稲作（やませ対策）と祭り、北海道の酪農・畑作・青函トンネルについての3問。", "dataFile": "sample/junior_high/geography/geography.json", "questionCount": 3, "questionTypes": "4択・〇×", "previewQuestions": [{"type": "4choice", "question": "夏に東北地方の太平洋側から吹き、冷害を引き起こす原因となってきた冷たく湿った風を何というでしょう？"}, {"type": "4choice", "question": "北海道の東部に広がる「根釧（こんせん）台地」で、冷涼な気候と広い土地を生かして非常に盛んに行われている産業は何でしょう？"}, {"type": "2choice", "question": "青森県と北海道を海底で結び、現在は北海道新幹線も通っているトンネルは「青函（せいかん）トンネル」である。"}], "searchText": "セット10: 東北・北海道地方 東北の稲作（やませ対策）と祭り、北海道の酪農・畑作・青函トンネルについての3問。 中学校 社会（地理） 3. 日本の諸地域 夏に東北地方の太平洋側から吹き、冷害を引き起こす原因となってきた冷たく湿った風を何というでしょう？ オホーツク海気団から吹く冷たい「やませ」から稲を守るため、東北では寒さに強い品種の改良（あきたこまち・ひとめぼれ等）が努力されてきました。 北海道の東部に広がる「根釧（こんせん）台地」で、冷涼な気候と広い土地を生かして非常に盛んに行われている産業は何でしょう？ 根釧台地は夏でも冷涼で濃霧が発生しやすいため穀物より牧草の育成に向いており、大規模な「酪農」が盛んです。日本の生乳生産量の半分以上は北海道です！ 青森県と北海道を海底で結び、現在は北海道新幹線も通っているトンネルは「青函（せいかん）トンネル」である。 正解！「青」森と「函」館を結ぶことから「青函トンネル」（全長約53.85km）と名付けられ、1988年に開通しました。"}, {"id": "jh-civics-set1", "school": "jh", "schoolName": "中学校", "subject": "social_civics", "subjectName": "社会（公民）", "topic": "1. 人権と日本国憲法", "title": "セット1: 現代社会と少子高齢化・情報化", "description": "少子高齢化、グローバル化、情報リテラシーとルールについての3問。", "dataFile": "sample/junior_high/civics/civics.json", "questionCount": 3, "questionTypes": "4択・〇×", "previewQuestions": [{"type": "4choice", "question": "日本の人口において、65歳以上の割合が高くなり子どもの割合が減っていく社会の変化を何というでしょう？"}, {"type": "4choice", "question": "インターネットやSNSから得られるたくさんの情報の中から、正しい情報を見極めて適切に使いこなす能力を何というでしょう？"}, {"type": "2choice", "question": "年齢や障害の有無、言語のちがいなどにかかわらず、最初からすべての人にとって使いやすいように設計することを「ユニバーサルデザイン」という。"}], "searchText": "セット1: 現代社会と少子高齢化・情報化 少子高齢化、グローバル化、情報リテラシーとルールについての3問。 中学校 社会（公民） 1. 人権と日本国憲法 日本の人口において、65歳以上の割合が高くなり子どもの割合が減っていく社会の変化を何というでしょう？ 日本は世界でもトップクラスの長寿国となり、65歳以上の割合が29％を超える「超高齢社会」と、出生数の減少による「少子化」が同時に進んでいます。 インターネットやSNSから得られるたくさんの情報の中から、正しい情報を見極めて適切に使いこなす能力を何というでしょう？ フェイクニュースや誤情報に惑わされないよう、情報の根拠を確かめ多角的に判断する力「メディア・リテラシー（情報活用能力）」が現代社会ではとても重要です。 年齢や障害の有無、言語のちがいなどにかかわらず、最初からすべての人にとって使いやすいように設計することを「ユニバーサルデザイン」という。 正解！シャンプーボトルのきざみや、ピクトグラム、ノンステップバスなどが代表例です。障害物を取り除く「バリアフリー」から一歩進んだ考え方です。"}, {"id": "jh-civics-set2", "school": "jh", "schoolName": "中学校", "subject": "social_civics", "subjectName": "社会（公民）", "topic": "1. 人権と日本国憲法", "title": "セット2: 日本国憲法の三大原則と平和主義", "description": "国民主権・基本的人権の尊重・平和主義、立憲主義と憲法改正の手続きについての3問。", "dataFile": "sample/junior_high/civics/civics.json", "questionCount": 3, "questionTypes": "4択・〇×", "previewQuestions": [{"type": "4choice", "question": "日本国憲法第9条に定められており、戦争の放棄・戦力の不保持・交戦権の否認をうたっている三大原則の一つは何でしょう？"}, {"type": "4choice", "question": "日本国憲法を改正する場合、衆議院と参議院それぞれの総議員のどれだけの賛成で「発議」し、その後国民投票を行う必要があるでしょう？"}, {"type": "2choice", "question": "日本国憲法において、天皇は国の「元首（政治の実権を持つトップ）」と定められている。"}], "searchText": "セット2: 日本国憲法の三大原則と平和主義 国民主権・基本的人権の尊重・平和主義、立憲主義と憲法改正の手続きについての3問。 中学校 社会（公民） 1. 人権と日本国憲法 日本国憲法第9条に定められており、戦争の放棄・戦力の不保持・交戦権の否認をうたっている三大原則の一つは何でしょう？ 日本国憲法の三大原則は「国民主権」「基本的人権の尊重」「平和主義」です。第9条では戦争を二度とくり返さない決意として平和主義が定められています。 日本国憲法を改正する場合、衆議院と参議院それぞれの総議員のどれだけの賛成で「発議」し、その後国民投票を行う必要があるでしょう？ 憲法は国の最高法規であり簡単に変えられないよう、衆参各議院の「総議員の3分の2以上」の賛成で国会が発議し、さらに「国民投票の過半数の賛成」が必要です（第96条）。 日本国憲法において、天皇は国の「元首（政治の実権を持つトップ）」と定められている。 ひっかけ問題！日本国憲法第1条では、天皇は「日本国の象徴であり日本国民統合の象徴」と定められており、内閣の助言と承認により「国事行為」を行いますが、政治に関する権能は持ちません。"}, {"id": "jh-civics-set3", "school": "jh", "schoolName": "中学校", "subject": "social_civics", "subjectName": "社会（公民）", "topic": "1. 人権と日本国憲法", "title": "セット3: 基本的人権の尊重と新しい人権", "description": "自由権・平等権・社会権・参政権、新しい人権（知る権利・プライバシー権）についての3問。", "dataFile": "sample/junior_high/civics/civics.json", "questionCount": 3, "questionTypes": "4択・〇×", "previewQuestions": [{"type": "4choice", "question": "憲法第25条の「すべて国民は、健康で文化的な最低限度の生活を営む権利を有する」は、どの人権を定めたものでしょう？"}, {"type": "4choice", "question": "時代の変化に伴い主張されるようになった「新しい人権」のうち、自分に関する個人情報をみだりに他人に知られない権利を何というでしょう？"}, {"type": "2choice", "question": "基本的人権は「侵すことのできない永久の権利」であるが、他人の人権を守るためなどの理由から「公共の福祉」による一定の制限を受けることがある。"}], "searchText": "セット3: 基本的人権の尊重と新しい人権 自由権・平等権・社会権・参政権、新しい人権（知る権利・プライバシー権）についての3問。 中学校 社会（公民） 1. 人権と日本国憲法 憲法第25条の「すべて国民は、健康で文化的な最低限度の生活を営む権利を有する」は、どの人権を定めたものでしょう？ 国に人間らしい生活の保障を求めることができる「生存権」は「社会権」の中心です。教育を受ける権利（第26条）や勤労の権利（第27条）も社会権に含まれます。 時代の変化に伴い主張されるようになった「新しい人権」のうち、自分に関する個人情報をみだりに他人に知られない権利を何というでしょう？ SNSやデジタル化が進んだ現代では、個人の情報や私生活を保護する「プライバシーの権利」や、行政に情報を公開させる「知る権利」などが重視されています。 基本的人権は「侵すことのできない永久の権利」であるが、他人の人権を守るためなどの理由から「公共の福祉」による一定の制限を受けることがある。 正解！自分の権利や自由を主張するときも、他の人の人権を傷つけてはいけません。お互いの人権を調整する基準を「公共の福祉」といいます。"}, {"id": "jh-civics-set4", "school": "jh", "schoolName": "中学校", "subject": "social_civics", "subjectName": "社会（公民）", "topic": "2. 政治のしくみと地方自治", "title": "セット4: 国会と内閣のしくみ", "description": "国権の最高機関（二院制）、議院内閣制、予算と法律の議決についての3問。", "dataFile": "sample/junior_high/civics/civics.json", "questionCount": 3, "questionTypes": "4択・〇×", "previewQuestions": [{"type": "4choice", "question": "日本の国会は「衆議院」と「参議院」からなる二院制です。任期が4年で解散があり、「衆議院の優越」が認められている理由はなぜでしょう？"}, {"type": "4choice", "question": "内閣が国会の信任に基づいて成り立ち、国会に対して連帯して責任を負う政治の仕組みを何というでしょう？"}, {"type": "2choice", "question": "衆議院で可決された「予算案」が参議院で否決され、両院協議会でも意見がまとまらない場合でも、最終的には衆議院の議決が国会の議決となる。"}], "searchText": "セット4: 国会と内閣のしくみ 国権の最高機関（二院制）、議院内閣制、予算と法律の議決についての3問。 中学校 社会（公民） 2. 政治のしくみと地方自治 日本の国会は「衆議院」と「参議院」からなる二院制です。任期が4年で解散があり、「衆議院の優越」が認められている理由はなぜでしょう？ 衆議院は任期4年・解散ありで最新の民意が反映されやすいため、法律案・予算・条約・内閣総理大臣の指名などで「衆議院の優越」が認められています。 内閣が国会の信任に基づいて成り立ち、国会に対して連帯して責任を負う政治の仕組みを何というでしょう？ 日本は「議院内閣制」を採用しており、内閣総理大臣は国会議員の中から国会で指名され、国務大臣の過半数も国会議員から選ばれます。 衆議院で可決された「予算案」が参議院で否決され、両院協議会でも意見がまとまらない場合でも、最終的には衆議院の議決が国会の議決となる。 正解！予算の議決、条約の承認、内閣総理大臣の指名では、両院協議会を経ても一致しないとき、または一定期間議決しないときは衆議院の議決が国会の議決になります。"}, {"id": "jh-civics-set5", "school": "jh", "schoolName": "中学校", "subject": "social_civics", "subjectName": "社会（公民）", "topic": "2. 政治のしくみと地方自治", "title": "セット5: 裁判所と三権分立・裁判員制度", "description": "三権分立の抑制と均衡、三審制と違憲審査権、裁判員制度についての3問。", "dataFile": "sample/junior_high/civics/civics.json", "questionCount": 3, "questionTypes": "4択・〇×", "previewQuestions": [{"type": "4choice", "question": "最高裁判所が持つ、国会で作った法律や内閣の命令が憲法に違反していないかを判断する権限を何というでしょう？"}, {"type": "4choice", "question": "同じ事件について、不服がある場合に最高3回まで裁判をやり直すことができる「三審制」が採用されている主な理由はどれでしょう？"}, {"type": "2choice", "question": "重大な刑事事件の第一審の裁判に、選挙権を持つ一般の国民からくじで選ばれた6人が裁判官と参加する仕組みを「裁判員制度」という。"}], "searchText": "セット5: 裁判所と三権分立・裁判員制度 三権分立の抑制と均衡、三審制と違憲審査権、裁判員制度についての3問。 中学校 社会（公民） 2. 政治のしくみと地方自治 最高裁判所が持つ、国会で作った法律や内閣の命令が憲法に違反していないかを判断する権限を何というでしょう？ 裁判所（最終的には最高裁判所）は「憲法の番人」とも呼ばれ、法律や行政行為が憲法に違反していないかを審査する「違憲審査権」を持っています。 同じ事件について、不服がある場合に最高3回まで裁判をやり直すことができる「三審制」が採用されている主な理由はどれでしょう？ 裁判官も人間であるため、誤判（えん罪など）を絶対に防ぐ目的で、地方裁判所→高等裁判所→最高裁判所へと上訴できる「三審制」がとられています。 重大な刑事事件の第一審の裁判に、選挙権を持つ一般の国民からくじで選ばれた6人が裁判官と参加する仕組みを「裁判員制度」という。 正解！国民の健全な常識を裁判に反映させ、司法への理解を深めるために2009年から「裁判員制度」が始まりました（裁判官3人＋裁判員6人）。"}, {"id": "jh-civics-set6", "school": "jh", "schoolName": "中学校", "subject": "social_civics", "subjectName": "社会（公民）", "topic": "2. 政治のしくみと地方自治", "title": "セット6: 地方自治と選挙・政治参加", "description": "「民主主義の学校」地方自治、直接請求権、18歳選挙権についての3問。", "dataFile": "sample/junior_high/civics/civics.json", "questionCount": 3, "questionTypes": "4択・〇×", "previewQuestions": [{"type": "4choice", "question": "都道府県や市区町村などの地方公共団体が、住民の意思にもとづいて地域の政治を自分たちで治める仕組みを何というでしょう？"}, {"type": "4choice", "question": "住民が一定数以上の署名を集めることで、条例の制定・改廃や、首長・議員の解職（リコール）などを求めることができる権利を何というでしょう？"}, {"type": "2choice", "question": "現在の日本の選挙では、衆議院・参議院および地方選挙の「選挙権（投票できる年齢）」は満18歳以上である。"}], "searchText": "セット6: 地方自治と選挙・政治参加 「民主主義の学校」地方自治、直接請求権、18歳選挙権についての3問。 中学校 社会（公民） 2. 政治のしくみと地方自治 都道府県や市区町村などの地方公共団体が、住民の意思にもとづいて地域の政治を自分たちで治める仕組みを何というでしょう？ 「地方自治は民主主義の学校」と呼ばれます。住民が首長（知事・市区町村長）と地方議会議員をどちらも直接選挙で選ぶ「二元代表制」をとっています。 住民が一定数以上の署名を集めることで、条例の制定・改廃や、首長・議員の解職（リコール）などを求めることができる権利を何というでしょう？ 地方自治では、選挙だけでなく、一定数以上の署名を集めて住民の意思を直接政治にぶつける「直接請求権」が認められています。 現在の日本の選挙では、衆議院・参議院および地方選挙の「選挙権（投票できる年齢）」は満18歳以上である。 正解！2015年の公職選挙法改正により、満20歳以上から「満18歳以上」に引き下げられました。高校3年生のうちから政治に参加できます！"}, {"id": "jh-civics-set7", "school": "jh", "schoolName": "中学校", "subject": "social_civics", "subjectName": "社会（公民）", "topic": "3. 経済・くらしと国際社会", "title": "セット7: 消費生活と市場経済のしくみ", "description": "需要量と供給量・均衡価格、独占禁止法、クーリング・オフ制度についての3問。", "dataFile": "sample/junior_high/civics/civics.json", "questionCount": 3, "questionTypes": "4択・〇×", "previewQuestions": [{"type": "4choice", "question": "市場において、「買いたい量（需要量）」と「売りたい量（供給量）」が一致したときに決まる価格を何というでしょう？"}, {"type": "4choice", "question": "訪問販売や電話勧誘などで契約してしまった場合でも、一定の期間内（例：8日間）であれば無条件で契約を取り消せる消費者保護制度は何でしょう？"}, {"type": "2choice", "question": "大企業同士が話し合って勝手に商品の値段をつり上げる「カルテル」などを禁止し、公正で自由な競争を守る法律を「独占禁止法」という。"}], "searchText": "セット7: 消費生活と市場経済のしくみ 需要量と供給量・均衡価格、独占禁止法、クーリング・オフ制度についての3問。 中学校 社会（公民） 3. 経済・くらしと国際社会 市場において、「買いたい量（需要量）」と「売りたい量（供給量）」が一致したときに決まる価格を何というでしょう？ 需要と供給のバランスによって自然に決まる価格を「均衡価格（市場価格）」といいます。品不足（需要＞供給）になると価格が上がり、余ると価格が下がります。 訪問販売や電話勧誘などで契約してしまった場合でも、一定の期間内（例：8日間）であれば無条件で契約を取り消せる消費者保護制度は何でしょう？ 「頭を冷やして考え直す」という意味の「クーリング・オフ制度」です。ただし店舗に出向いて買った場合や、自ら通信販売サイトで注文した場合などは原則対象外なので注意しましょう！ 大企業同士が話し合って勝手に商品の値段をつり上げる「カルテル」などを禁止し、公正で自由な競争を守る法律を「独占禁止法」という。 正解！公正取引委員会が監視役となり、独占禁止法にもとづいて消費者が不利益を被らないよう自由な競争環境を守っています。"}, {"id": "jh-civics-set8", "school": "jh", "schoolName": "中学校", "subject": "social_civics", "subjectName": "社会（公民）", "topic": "3. 経済・くらしと国際社会", "title": "セット8: 企業・金融・財政と税の役割", "description": "株式会社のしくみ、日本銀行の役割、直接税と間接税についての3問。", "dataFile": "sample/junior_high/civics/civics.json", "questionCount": 3, "questionTypes": "4択・〇×", "previewQuestions": [{"type": "4choice", "question": "お金の流通量を調整し、「発券銀行」「銀行の銀行」「政府の銀行」という3つの役割を担う日本の中心となる機関は何でしょう？"}, {"type": "4choice", "question": "税金を納める人（お店など）と、実際に税金を負担する人（消費者）が異なる「間接税」にあたる税金は次のうちどれでしょう？"}, {"type": "2choice", "question": "不景気のときには、国は公共事業を増やしたり減税をしたりして、世の中に出回るお金を増やす「財政政策」を行うことがある。"}], "searchText": "セット8: 企業・金融・財政と税の役割 株式会社のしくみ、日本銀行の役割、直接税と間接税についての3問。 中学校 社会（公民） 3. 経済・くらしと国際社会 お金の流通量を調整し、「発券銀行」「銀行の銀行」「政府の銀行」という3つの役割を担う日本の中心となる機関は何でしょう？ お札（日本銀行券）を発行し、民間の銀行にお金を貸し出し、国の税金の出し入れを行うのが中央銀行である「日本銀行（日銀）」です。 税金を納める人（お店など）と、実際に税金を負担する人（消費者）が異なる「間接税」にあたる税金は次のうちどれでしょう？ 「消費税」は買い物をした消費者が負担し、お店が代わりに国へ納める間接税です。一方、所得が多いほど税率が高くなる累進課税がとられる「所得税」などは直接税です。 不景気のときには、国は公共事業を増やしたり減税をしたりして、世の中に出回るお金を増やす「財政政策」を行うことがある。 正解！景気対策や道路・学校整備、社会保障の充実など、国の財政には「資源配分」「所得再分配」「景気の安定」の3つの重要な働きがあります。"}, {"id": "jh-civics-set9", "school": "jh", "schoolName": "中学校", "subject": "social_civics", "subjectName": "社会（公民）", "topic": "3. 経済・くらしと国際社会", "title": "セット9: 労働者の権利と社会保障", "description": "労働三法・労働三権、社会保障の4つの柱（社会保険・公的扶助等）についての3問。", "dataFile": "sample/junior_high/civics/civics.json", "questionCount": 3, "questionTypes": "4択・〇×", "previewQuestions": [{"type": "4choice", "question": "働く人々の権利を守るために憲法第28条で保障されている「労働三権」とは、団結権・団体交渉権とあと1つは何でしょう？"}, {"type": "4choice", "question": "日本の「社会保障制度」の4つの柱とは、社会保険・社会福祉・公衆衛生と、生活に困窮した人を支える生活保護などの何でしょう？"}, {"type": "2choice", "question": "同じ職場で同じ内容の仕事をしていれば、正社員とパートタイム労働者の間で不合理な待遇の差をつけてはならない（同一労働同一賃金）というルールがある。"}], "searchText": "セット9: 労働者の権利と社会保障 労働三法・労働三権、社会保障の4つの柱（社会保険・公的扶助等）についての3問。 中学校 社会（公民） 3. 経済・くらしと国際社会 働く人々の権利を守るために憲法第28条で保障されている「労働三権」とは、団結権・団体交渉権とあと1つは何でしょう？ 労働組合をつくる「団結権」、会社と交渉する「団体交渉権」、交渉がまとまらないときにストライキなどを行える「団体行動権（争議権）」の3つを労働三権といいます。 日本の「社会保障制度」の4つの柱とは、社会保険・社会福祉・公衆衛生と、生活に困窮した人を支える生活保護などの何でしょう？ 日本の社会保障は「社会保険（年金・医療・介護など）」「公的扶助（生活保護）」「社会福祉（高齢者・障害者・児童支援）」「公衆衛生（感染症対策や水道など）」の4本柱で支えられています。 同じ職場で同じ内容の仕事をしていれば、正社員とパートタイム労働者の間で不合理な待遇の差をつけてはならない（同一労働同一賃金）というルールがある。 正解！働き方改革の一環として、正規・非正規にかかわらず公正な処遇を目指す「同一労働同一賃金」や、長時間労働の是正などが進められています。"}, {"id": "jh-civics-set10", "school": "jh", "schoolName": "中学校", "subject": "social_civics", "subjectName": "社会（公民）", "topic": "3. 経済・くらしと国際社会", "title": "セット10: 国際連合と地球環境・SDGs", "description": "国連安保理の常任理事国、地球温暖化対策、SDGs（持続可能な開発目標）についての3問。", "dataFile": "sample/junior_high/civics/civics.json", "questionCount": 3, "questionTypes": "4択・〇×", "previewQuestions": [{"type": "4choice", "question": "国際連合の「安全保障理事会（安保理）」で、重要な決定に対して拒否権を持つ5つの常任理事国の組み合わせとして正しいものはどれでしょう？"}, {"type": "4choice", "question": "国連で採択された、2030年までに世界全体で達成を目指す「持続可能な開発目標（17のゴール）」をアルファベット4文字で何というでしょう？"}, {"type": "2choice", "question": "政府ではなく民間の立場から、災害支援・医療・環境保護などの国際協力を行う非政府組織のことを「NGO」という。"}], "searchText": "セット10: 国際連合と地球環境・SDGs 国連安保理の常任理事国、地球温暖化対策、SDGs（持続可能な開発目標）についての3問。 中学校 社会（公民） 3. 経済・くらしと国際社会 国際連合の「安全保障理事会（安保理）」で、重要な決定に対して拒否権を持つ5つの常任理事国の組み合わせとして正しいものはどれでしょう？ 第二次世界大戦の戦勝国を中心とするアメリカ・イギリス・フランス・ロシア・中国の5か国が常任理事国です。1か国でも反対（拒否権）すると決議が通らない仕組みがあります。 国連で採択された、2030年までに世界全体で達成を目指す「持続可能な開発目標（17のゴール）」をアルファベット4文字で何というでしょう？ 「誰一人取り残さない（Leave No One Behind）」を合言葉に、貧困の解消、ジェンダー平等、気候変動対策など17の目標を掲げるのが「SDGs」です。 政府ではなく民間の立場から、災害支援・医療・環境保護などの国際協力を行う非政府組織のことを「NGO」という。 正解！Non-Governmental Organizationの略がNGOです。国や自治体には手が届きにくい現場へ素早くきめ細かな支援を届ける大切な存在です。"}, {"id": "jh-bio-set1", "school": "jh", "schoolName": "中学校", "subject": "science_bio", "subjectName": "理科（生物）", "topic": "1. 植物・動物のなかま", "title": "セット1: 顕微鏡の使い方と身近な微生物", "description": "顕微鏡の正しい手順、プレパラート作り、ミジンコやアオミドロなどの微生物についての3問。", "dataFile": "sample/junior_high/biology/biology.json", "questionCount": 3, "questionTypes": "4択・〇×", "previewQuestions": [{"type": "4choice", "question": "顕微鏡でプレパラートのピントを合わせるとき、対物レンズを傷つけないための正しい操作順序はどれでしょう？"}, {"type": "4choice", "question": "池の水にいる微生物のうち、葉緑体をもち、光合成をして自分で栄養をつくる植物のなかまはどれでしょう？"}, {"type": "2choice", "question": "顕微鏡の倍率を「低倍率」から「高倍率」に変えると、見える範囲（視野）はせまくなり、明るさは暗くなる。"}], "searchText": "セット1: 顕微鏡の使い方と身近な微生物 顕微鏡の正しい手順、プレパラート作り、ミジンコやアオミドロなどの微生物についての3問。 中学校 理科（生物） 1. 植物・動物のなかま 顕微鏡でプレパラートのピントを合わせるとき、対物レンズを傷つけないための正しい操作順序はどれでしょう？ 接眼レンズをのぞいたまま対物レンズを下げると、スライドガラスにぶつけて割ってしまう危険があります。必ず「横から見ながら近づけ、のぞきながら遠ざけて」ピントを合わせます！ 池の水にいる微生物のうち、葉緑体をもち、光合成をして自分で栄養をつくる植物のなかまはどれでしょう？ アオミドロやミカヅキモは緑色の葉緑体をもっていて、日光が当たると光合成を行います。ゾウリムシやミジンコは動いて食べ物をとる動物性の微生物です。 顕微鏡の倍率を「低倍率」から「高倍率」に変えると、見える範囲（視野）はせまくなり、明るさは暗くなる。 正解！倍率が上がると細かい部分が大きく見える代わりに、視野は狭く暗くなるため、しぼりで明るさを調節します。必ず最初に低倍率で見つけてから高倍率にします。"}, {"id": "jh-bio-set2", "school": "jh", "schoolName": "中学校", "subject": "science_bio", "subjectName": "理科（生物）", "topic": "1. 植物・動物のなかま", "title": "セット2: 植物のつくりと光合成・蒸散", "description": "葉緑体での光合成とデンプン、気孔と蒸散、道管・師管の働きについての3問。", "dataFile": "sample/junior_high/biology/biology.json", "questionCount": 3, "questionTypes": "4択・〇×", "previewQuestions": [{"type": "4choice", "question": "植物が光のエネルギーを使って、二酸化炭素と水から栄養分（デンプンなど）と酸素をつくる働きを何というでしょう？"}, {"type": "4choice", "question": "植物の葉の裏側などに多く見られる、2つの孔辺細胞に囲まれたすき間で、水蒸気や気体が出入りする穴を何というでしょう？"}, {"type": "2choice", "question": "植物の茎にある維管束のうち、根から吸い上げた水や肥料分が通る管は「道管」、葉でつくられた栄養分が通る管は「師管」である。"}], "searchText": "セット2: 植物のつくりと光合成・蒸散 葉緑体での光合成とデンプン、気孔と蒸散、道管・師管の働きについての3問。 中学校 理科（生物） 1. 植物・動物のなかま 植物が光のエネルギーを使って、二酸化炭素と水から栄養分（デンプンなど）と酸素をつくる働きを何というでしょう？ 植物の細胞にある「葉緑体」で行われるのが「光合成」です。光合成でできたデンプンは「ヨウ素液」を加えると青紫色に変化します！ 植物の葉の裏側などに多く見られる、2つの孔辺細胞に囲まれたすき間で、水蒸気や気体が出入りする穴を何というでしょう？ 「気孔」から水蒸気が出ていく現象を「蒸散」といいます。蒸散は根から水を吸い上げる原動力となり、葉の温度が上がりすぎるのも防ぎます。 植物の茎にある維管束のうち、根から吸い上げた水や肥料分が通る管は「道管」、葉でつくられた栄養分が通る管は「師管」である。 正解！水の通り道が「道管」、栄養（砂糖などの形に変えて運ばれる）が通るのが「師管」です。2つをまとめて「維管束」といいます。"}, {"id": "jh-bio-set3", "school": "jh", "schoolName": "中学校", "subject": "science_bio", "subjectName": "理科（生物）", "topic": "1. 植物・動物のなかま", "title": "セット3: 花のつくりと植物の分類", "description": "被子植物と裸子植物、単子葉類と双子葉類、シダ植物・コケ植物の違いについての3問。", "dataFile": "sample/junior_high/biology/biology.json", "questionCount": 3, "questionTypes": "4択・〇×", "previewQuestions": [{"type": "4choice", "question": "マツやイチョウ、ソテツのように、子房がなく「胚珠」がむき出しになっている種子植物を何というでしょう？"}, {"type": "4choice", "question": "葉脈が「平行脈」、根が「ひげ根」、茎の維管束がバラバラに散らばっている被子植物のなかま（ツユクサ・トウモロコシ・イネ等）はどれでしょう？"}, {"type": "2choice", "question": "イヌワラビなどのシダ植物や、ゼニゴケ・スギゴケなどのコケ植物は、花や種子をつくらず「胞子」によってふえる。"}], "searchText": "セット3: 花のつくりと植物の分類 被子植物と裸子植物、単子葉類と双子葉類、シダ植物・コケ植物の違いについての3問。 中学校 理科（生物） 1. 植物・動物のなかま マツやイチョウ、ソテツのように、子房がなく「胚珠」がむき出しになっている種子植物を何というでしょう？ 胚珠が子房に包まれているのが「被子植物（サクラ・アブラナなど）」、むき出しなのが「裸子植物（マツ・イチョウ・スギなど）」です。裸子植物の多くは風で花粉を運びます。 葉脈が「平行脈」、根が「ひげ根」、茎の維管束がバラバラに散らばっている被子植物のなかま（ツユクサ・トウモロコシ・イネ等）はどれでしょう？ 子葉が1枚の「単子葉類」は「平行脈・ひげ根・維管束は散らばる」が特徴です。一方、子葉が2枚の「双子葉類」は「網状脈・主根と側根・維管束は輪状」です。 イヌワラビなどのシダ植物や、ゼニゴケ・スギゴケなどのコケ植物は、花や種子をつくらず「胞子」によってふえる。 正解！シダ植物には根・茎・葉の区別と維管束がありますが、コケ植物には根・茎・葉の区別や維管束がなく、体全体から水や養分を吸収します。どちらも「胞子」で増えます。"}, {"id": "jh-bio-set4", "school": "jh", "schoolName": "中学校", "subject": "science_bio", "subjectName": "理科（生物）", "topic": "1. 植物・動物のなかま", "title": "セット4: 動物の分類（せきつい・無せきつい）", "description": "背骨の有無、卵生・胎生、恒温動物と変温動物、節足・軟体動物についての3問。", "dataFile": "sample/junior_high/biology/biology.json", "questionCount": 3, "questionTypes": "4択・〇×", "previewQuestions": [{"type": "4choice", "question": "背骨をもつ「せきつい動物」の5つの仲間のうち、まわりの温度が変わっても体温をほぼ一定に保つ「恒温動物」の組み合わせはどれでしょう？"}, {"type": "4choice", "question": "カエルやイモリなどの「両生類」の呼吸のしかたとして正しいものはどれでしょう？"}, {"type": "2choice", "question": "バッタやエビ・カニなどの「節足動物」には背骨がなく、外骨格と呼ばれるかたい殻におおわれていて、脱皮をして成長する。"}], "searchText": "セット4: 動物の分類（せきつい・無せきつい） 背骨の有無、卵生・胎生、恒温動物と変温動物、節足・軟体動物についての3問。 中学校 理科（生物） 1. 植物・動物のなかま 背骨をもつ「せきつい動物」の5つの仲間のうち、まわりの温度が変わっても体温をほぼ一定に保つ「恒温動物」の組み合わせはどれでしょう？ 鳥類とほ乳類は体温を一定に保てる「恒温動物」です。魚類・両生類・は虫類はまわりの温度によって体温が変わる「変温動物」で、冬眠する種も多くいます。 カエルやイモリなどの「両生類」の呼吸のしかたとして正しいものはどれでしょう？ オタマジャクシ（子）のときは水中で「えら呼吸」をしますが、おとなのカエルになると「肺呼吸」に加えて湿った皮膚でも「皮膚呼吸」を行うため、水辺から離れられません。 バッタやエビ・カニなどの「節足動物」には背骨がなく、外骨格と呼ばれるかたい殻におおわれていて、脱皮をして成長する。 正解！背骨のない「無せきつい動物」のうち、体やあしに節があるのが「節足動物」、筋肉でできた「外とう膜」で内臓が包まれているイカ・アサリ・カタツムリなどが「軟体動物」です。"}, {"id": "jh-bio-set5", "school": "jh", "schoolName": "中学校", "subject": "science_bio", "subjectName": "理科（生物）", "topic": "2. 人の体のつくりとはたらき", "title": "セット5: 消化と吸収のしくみ", "description": "消化液と消化酵素（アミラーゼ・ペプシン・リパーゼ等）、小腸の柔毛についての3問。", "dataFile": "sample/junior_high/biology/biology.json", "questionCount": 3, "questionTypes": "4択・〇×", "previewQuestions": [{"type": "4choice", "question": "だ液に含まれる消化酵素「アミラーゼ」は、食べ物のどの栄養分を分解するでしょう？"}, {"type": "4choice", "question": "肝臓でつくられ、胆のうにためられる「胆汁」には消化酵素が含まれていませんが、どの栄養分の消化を助ける働きがあるでしょう？"}, {"type": "2choice", "question": "小腸の内側の壁には「柔毛（じゅうもう）」と呼ばれる無数の小さな突起があり、表面積を非常に大きくして栄養分を効率よく吸収している。"}], "searchText": "セット5: 消化と吸収のしくみ 消化液と消化酵素（アミラーゼ・ペプシン・リパーゼ等）、小腸の柔毛についての3問。 中学校 理科（生物） 2. 人の体のつくりとはたらき だ液に含まれる消化酵素「アミラーゼ」は、食べ物のどの栄養分を分解するでしょう？ ご飯（デンプン）をよくかむと甘くなるのは、だ液中の「アミラーゼ」がデンプンを麦芽糖などの糖に分解するためです！ベネジクト液と加熱すると赤褐色になります。 肝臓でつくられ、胆のうにためられる「胆汁」には消化酵素が含まれていませんが、どの栄養分の消化を助ける働きがあるでしょう？ 胆汁は消化酵素を持ちませんが、脂肪を小さな粒に散らして（乳化して）、すい液の消化酵素リパーゼが働きやすくする大切な役割があります！ 小腸の内側の壁には「柔毛（じゅうもう）」と呼ばれる無数の小さな突起があり、表面積を非常に大きくして栄養分を効率よく吸収している。 正解！ブドウ糖とアミノ酸は柔毛内の「毛細血管」へ、脂肪酸とモノグリセリドは再合成されたあと「リンパ管」へ吸収されて全身へ運ばれます。"}, {"id": "jh-bio-set6", "school": "jh", "schoolName": "中学校", "subject": "science_bio", "subjectName": "理科（生物）", "topic": "2. 人の体のつくりとはたらき", "title": "セット6: 呼吸と血液の循環", "description": "肺胞でのガス交換、血液の4つの成分、心臓と動脈・静脈の違いについての3問。", "dataFile": "sample/junior_high/biology/biology.json", "questionCount": 3, "questionTypes": "4択・〇×", "previewQuestions": [{"type": "4choice", "question": "血液の4つの成分のうち、酸素を全身の細胞へ運ぶ役割をする「ヘモグロビン」を含む成分はどれでしょう？"}, {"type": "4choice", "question": "血管を分類するとき、「心臓から送り出される血液が流れる血管」と「酸素を多く含む血液」をそれぞれ何というでしょう？"}, {"type": "2choice", "question": "肺の先にある無数の小さな袋「肺胞（はいほう）」では、毛細血管との間で酸素を取り入れ、二酸化炭素を放出するガス交換が行われている。"}], "searchText": "セット6: 呼吸と血液の循環 肺胞でのガス交換、血液の4つの成分、心臓と動脈・静脈の違いについての3問。 中学校 理科（生物） 2. 人の体のつくりとはたらき 血液の4つの成分のうち、酸素を全身の細胞へ運ぶ役割をする「ヘモグロビン」を含む成分はどれでしょう？ 赤血球（酸素を運ぶ）、白血球（細菌などを退治する）、血小板（出血を止めて血を固める）、血しょう（養分や二酸化炭素などを溶かして運ぶ液体）の4成分をしっかり区別しましょう！ 血管を分類するとき、「心臓から送り出される血液が流れる血管」と「酸素を多く含む血液」をそれぞれ何というでしょう？ 「動脈（＝心臓から出ていく血管）」「静脈（＝心臓に戻る血管）」という構造の名前と、「動脈血（＝酸素が多い血）」「静脈血（＝二酸化炭素が多い血）」という血液の性質を区別します！（※肺動脈には静脈血が流れます！） 肺の先にある無数の小さな袋「肺胞（はいほう）」では、毛細血管との間で酸素を取り入れ、二酸化炭素を放出するガス交換が行われている。 正解！肺胞も小腸の柔毛と同じく、小さな袋が大量に集まることで空気と触れ合う表面積を極限まで大きくし、効率よくガス交換をしています。"}, {"id": "jh-bio-set7", "school": "jh", "schoolName": "中学校", "subject": "science_bio", "subjectName": "理科（生物）", "topic": "2. 人の体のつくりとはたらき", "title": "セット7: 感覚器官・神経と反射・運動", "description": "目や耳のつくり、脳と脊髄（中枢神経）、意識とは無関係に起こる「反射」についての3問。", "dataFile": "sample/junior_high/biology/biology.json", "questionCount": 3, "questionTypes": "4択・〇×", "previewQuestions": [{"type": "4choice", "question": "熱いヤカンにうっかり触れたとき、大脳で考えるより先に、せきずいから直接命令が出て思わず手を引っ込める反応を何というでしょう？"}, {"type": "4choice", "question": "人間の目のつくりで、カメラのレンズのように厚みを変えてピントを合わせる部分と、光の刺激を受け取る奥の膜の名称の組み合わせはどれでしょう？"}, {"type": "2choice", "question": "腕を曲げるとき、筋肉は骨と「けん」でつながっており、筋肉が「縮む」力だけで骨を引っぱって動かしている。"}], "searchText": "セット7: 感覚器官・神経と反射・運動 目や耳のつくり、脳と脊髄（中枢神経）、意識とは無関係に起こる「反射」についての3問。 中学校 理科（生物） 2. 人の体のつくりとはたらき 熱いヤカンにうっかり触れたとき、大脳で考えるより先に、せきずいから直接命令が出て思わず手を引っ込める反応を何というでしょう？ 刺激を受けてから大脳を通らずにせきずいなどから即座に反応が返る「反射」は、危険から自分の体を素早く守る大切な仕組みです。暗い場所でひとみ（瞳孔）が広がるのも反射です。 人間の目のつくりで、カメラのレンズのように厚みを変えてピントを合わせる部分と、光の刺激を受け取る奥の膜の名称の組み合わせはどれでしょう？ 目に入った光は「水晶体（レンズ）」で屈折し、奥の「網膜」に像を結びます。その信号が「視神経」を通って脳へ伝わり、見えたと感じます。 腕を曲げるとき、筋肉は骨と「けん」でつながっており、筋肉が「縮む」力だけで骨を引っぱって動かしている。 正解！筋肉は自ら「縮む」ことしかできないため、関節を挟んで表側と裏側の2つの筋肉がペアになり、一方が縮むともう一方がゆるんで曲げ伸ばしをしています。"}, {"id": "jh-bio-set8", "school": "jh", "schoolName": "中学校", "subject": "science_bio", "subjectName": "理科（生物）", "topic": "3. 細胞・遺伝と自然界のつながり", "title": "セット8: 細胞のつくりと細胞分裂", "description": "動物細胞と植物細胞の共通点と違い、体細胞分裂の過程と染色体の観察についての3問。", "dataFile": "sample/junior_high/biology/biology.json", "questionCount": 3, "questionTypes": "4択・〇×", "previewQuestions": [{"type": "4choice", "question": "植物の細胞にはあるが、動物の細胞には「ない」つくりの組み合わせとして正しいものはどれでしょう？"}, {"type": "4choice", "question": "タマネギの根の先端など、成長が盛んな部分で観察できる「体細胞分裂」では、分裂する前の核の中にある「染色体」の数は分裂後にどうなるでしょう？"}, {"type": "2choice", "question": "植物の根が伸びるとき、根の先端近くの小さな細胞が分裂して数を増やしたあと、一つ一つの細胞が大きくなることで成長する。"}], "searchText": "セット8: 細胞のつくりと細胞分裂 動物細胞と植物細胞の共通点と違い、体細胞分裂の過程と染色体の観察についての3問。 中学校 理科（生物） 3. 細胞・遺伝と自然界のつながり 植物の細胞にはあるが、動物の細胞には「ない」つくりの組み合わせとして正しいものはどれでしょう？ 核・細胞膜・細胞質は動物・植物の両方に共通です。植物細胞には、体を支える頑丈な「細胞壁」、光合成をする「葉緑体」、水分等を貯める大きな「液胞」があります！ タマネギの根の先端など、成長が盛んな部分で観察できる「体細胞分裂」では、分裂する前の核の中にある「染色体」の数は分裂後にどうなるでしょう？ 体細胞分裂では、核の中の染色体がコピーされて同じものが2つの細胞に分かれるため、できた新しい細胞も元の細胞とまったく同じ染色体数・遺伝情報を受け継ぎます。 植物の根が伸びるとき、根の先端近くの小さな細胞が分裂して数を増やしたあと、一つ一つの細胞が大きくなることで成長する。 正解！生物の成長は、細胞分裂によって「細胞の数が増える」ことと、その後それぞれの「細胞が大きくなる」ことの2段階で進みます。"}, {"id": "jh-bio-set9", "school": "jh", "schoolName": "中学校", "subject": "science_bio", "subjectName": "理科（生物）", "topic": "3. 細胞・遺伝と自然界のつながり", "title": "セット9: 生殖と遺伝の規則性", "description": "無性生殖と有性生殖、減数分裂、メンデルの実験（顕性・潜性形質と分離の法則）についての3問。", "dataFile": "sample/junior_high/biology/biology.json", "questionCount": 3, "questionTypes": "4択・〇×", "previewQuestions": [{"type": "4choice", "question": "ジャガイモの栄養生殖やゾウリムシの分裂のように、受精を行わず1つの親から同じ遺伝子を受け継ぐ子がふえる増え方を何というでしょう？"}, {"type": "4choice", "question": "エンドウの丸い種子（AA）としわの種子（aa）をかけ合わせてできた子（Aa）はすべて丸くなりました。このとき「丸」のように子に現れやすい形質を何というでしょう？"}, {"type": "2choice", "question": "卵や精子などの生殖細胞がつくられるときには、染色体の数が半分になる特別な細胞分裂「減数分裂」が行われる。"}], "searchText": "セット9: 生殖と遺伝の規則性 無性生殖と有性生殖、減数分裂、メンデルの実験（顕性・潜性形質と分離の法則）についての3問。 中学校 理科（生物） 3. 細胞・遺伝と自然界のつながり ジャガイモの栄養生殖やゾウリムシの分裂のように、受精を行わず1つの親から同じ遺伝子を受け継ぐ子がふえる増え方を何というでしょう？ 無性生殖では親のコピー（クローン）ができるため、形質は親とまったく同じになります。一方、雌雄の生殖細胞が受精する有性生殖では、両親の遺伝子が組み合わさり多様な子が生まれます。 エンドウの丸い種子（AA）としわの種子（aa）をかけ合わせてできた子（Aa）はすべて丸くなりました。このとき「丸」のように子に現れやすい形質を何というでしょう？ 対になる遺伝子（Aとa）が揃ったときに表に現れる形質を「顕性（けんせい）形質」、隠れて現れない形質を「潜性（せんせい）形質」といいます（2017年頃から名称が整理されました）。 卵や精子などの生殖細胞がつくられるときには、染色体の数が半分になる特別な細胞分裂「減数分裂」が行われる。 正解！減数分裂で染色体が半分（n）になるからこそ、受精によって卵と精子が合体したときに再び元の数（2n）に戻り、世代を超えて染色体の数が一定に保たれます！"}, {"id": "jh-bio-set10", "school": "jh", "schoolName": "中学校", "subject": "science_bio", "subjectName": "理科（生物）", "topic": "3. 細胞・遺伝と自然界のつながり", "title": "セット10: 生態系と自然界のつながり", "description": "生産者・消費者・分解者（菌類・細菌類）、食物連鎖のピラミッド、炭素と酸素の循環についての3問。", "dataFile": "sample/junior_high/biology/biology.json", "questionCount": 3, "questionTypes": "4択・〇×", "previewQuestions": [{"type": "4choice", "question": "生態系の中で、動物の死がいやフン・落ち葉などの有機物を二酸化炭素や水・無機物へと分解し、自然の物質循環に欠かせない働きをするのはどれでしょう？"}, {"type": "4choice", "question": "「草 → ウサギ → キツネ」のような食べる・食べられるのつながりにおいて、通常もっとも個体数（生物の量）が多いのはどの段階でしょう？"}, {"type": "2choice", "question": "ある地域で肉食動物が激減して一時的に草食動物が増えすぎても、やがて植物が減ることで草食動物も減少し、もとのつり合いに戻ろうとする働きがある。"}], "searchText": "セット10: 生態系と自然界のつながり 生産者・消費者・分解者（菌類・細菌類）、食物連鎖のピラミッド、炭素と酸素の循環についての3問。 中学校 理科（生物） 3. 細胞・遺伝と自然界のつながり 生態系の中で、動物の死がいやフン・落ち葉などの有機物を二酸化炭素や水・無機物へと分解し、自然の物質循環に欠かせない働きをするのはどれでしょう？ もし菌類や細菌類などの「分解者」がいなければ、地球上は落ち葉や死がいで埋まり、植物が必要な養分や二酸化炭素が循環しなくなってしまいます！ 「草 → ウサギ → キツネ」のような食べる・食べられるのつながりにおいて、通常もっとも個体数（生物の量）が多いのはどの段階でしょう？ 食物連鎖ではピラミッドのように土台となる「生産者（植物）」が最も多く、上にいくほど個体数が少なくなって生態系のつり合いが保たれています。 ある地域で肉食動物が激減して一時的に草食動物が増えすぎても、やがて植物が減ることで草食動物も減少し、もとのつり合いに戻ろうとする働きがある。 正解！自然界には一時的にバランスが崩れても元に戻ろうとする回復力がありますが、外来種の侵入や過度な開発で急激に変化すると元に戻らなくなる危険があります。"}, {"id": "jh-astro-set1", "school": "jh", "schoolName": "中学校", "subject": "science_astro", "subjectName": "理科（天体）", "topic": "1. 地球の運動と星の動き", "title": "セット1: 地球の自転と日周運動", "description": "地球の自転の向きとスピード（1時間15度）、太陽や星の日周運動、南中高度についての3問。", "dataFile": "sample/junior_high/astronomy/astronomy.json", "questionCount": 3, "questionTypes": "4択・〇×", "previewQuestions": [{"type": "4choice", "question": "地球が地軸を中心に1日に1回転する運動を「自転」といいます。北極側から見たとき、地球はどちら向きに自転しているでしょう？"}, {"type": "4choice", "question": "日本の北の空にある「北極星」を中心に星の日周運動を観察すると、まわりの星は1時間に約何度、どちら向きに回って見えるでしょう？"}, {"type": "2choice", "question": "太陽や星が真南の空の一番高い位置にくることを「南中」といい、南の空を正面に見たとき天体は左（東）から右（西）へ動く。"}], "searchText": "セット1: 地球の自転と日周運動 地球の自転の向きとスピード（1時間15度）、太陽や星の日周運動、南中高度についての3問。 中学校 理科（天体） 1. 地球の運動と星の動き 地球が地軸を中心に1日に1回転する運動を「自転」といいます。北極側から見たとき、地球はどちら向きに自転しているでしょう？ 地球は北極の上から見ると「反時計回り（西から東）」に自転しています。だから地球から空を見ると、太陽も星も東からのぼって西へ沈む（1時間に約15度動く）ように見えます！ 日本の北の空にある「北極星」を中心に星の日周運動を観察すると、まわりの星は1時間に約何度、どちら向きに回って見えるでしょう？ 北極星は地軸の延長線上にあるためほとんど動かず、北の空の星はそのまわりを「反時計回りに1時間15度（360°÷24h）」回って見えます！（「北の空＝反時計回り」は超重要！） 太陽や星が真南の空の一番高い位置にくることを「南中」といい、南の空を正面に見たとき天体は左（東）から右（西）へ動く。 正解！南を向くと、左手が「東」、右手が「西」になります。そのため太陽や南の空の星は左から上り、南中を通って右へ沈んでいきます。"}, {"id": "jh-astro-set2", "school": "jh", "schoolName": "中学校", "subject": "science_astro", "subjectName": "理科（天体）", "topic": "1. 地球の運動と星の動き", "title": "セット2: 地球の公転と年周運動", "description": "星の年周運動（1か月約30度）、季節の星座（オリオン座・さそり座）が見え変わる理由についての3問。", "dataFile": "sample/junior_high/astronomy/astronomy.json", "questionCount": 3, "questionTypes": "4択・〇×", "previewQuestions": [{"type": "4choice", "question": "地球は太陽のまわりを1年で1周（公転）しています。毎日同じ時刻に同じ星を観察すると、1か月（30日）ごとに同じ方向に約何度ずつ位置がずれていくでしょう？"}, {"type": "4choice", "question": "夏の夜に南の空に見えていた「さそり座」が、季節が進んで秋や冬になると夜には見えなくなるのはなぜでしょう？"}, {"type": "2choice", "question": "同じ星座でも、観察する時刻が1か月前より「2時間遅い」時刻であれば、1か月前とほぼ同じ位置に見ることができる。"}], "searchText": "セット2: 地球の公転と年周運動 星の年周運動（1か月約30度）、季節の星座（オリオン座・さそり座）が見え変わる理由についての3問。 中学校 理科（天体） 1. 地球の運動と星の動き 地球は太陽のまわりを1年で1周（公転）しています。毎日同じ時刻に同じ星を観察すると、1か月（30日）ごとに同じ方向に約何度ずつ位置がずれていくでしょう？ 地球は1年（12か月）で360度公転するため、360 ÷ 12 = 1か月あたり約30度（1日あたり約1度）ずつ、星が東から西へ動いて見える「年周運動」が起こります！ 夏の夜に南の空に見えていた「さそり座」が、季節が進んで秋や冬になると夜には見えなくなるのはなぜでしょう？ 地球が太陽のまわりを公転するため、季節ごとに「夜の方向（太陽と反対側）」が変わり、夏にはオリオン座は昼の空に、冬には夜の空に見えるようになります。 同じ星座でも、観察する時刻が1か月前より「2時間遅い」時刻であれば、1か月前とほぼ同じ位置に見ることができる。 ひっかけ問題！星は1か月で西へ30度進みます。日周運動は1時間15度なので、30度分だけ「早く」進むため、同じ位置で見るには「2時間早い」時刻に観察する必要があります！"}, {"id": "jh-astro-set3", "school": "jh", "schoolName": "中学校", "subject": "science_astro", "subjectName": "理科（天体）", "topic": "1. 地球の運動と星の動き", "title": "セット3: 地軸の傾きと四季の変化", "description": "地軸の傾き（23.4度）、夏至・冬至の南中高度と昼の長さ、季節ができる本当の理由についての3問。", "dataFile": "sample/junior_high/astronomy/astronomy.json", "questionCount": 3, "questionTypes": "4択・〇×", "previewQuestions": [{"type": "4choice", "question": "地球に「四季（春夏秋冬）」の変化が生まれる最も大きな原因は次のうちどれでしょう？"}, {"type": "4choice", "question": "日本（北半球）において、1年で「太陽の南中高度が最も高く、昼の長さが最も長い日」を何というでしょう？"}, {"type": "2choice", "question": "「春分」と「秋分」の日には、太陽は真東から昇って真西に沈み、昼の長さと夜の長さがほぼ同じ（約12時間ずつ）になる。"}], "searchText": "セット3: 地軸の傾きと四季の変化 地軸の傾き（23.4度）、夏至・冬至の南中高度と昼の長さ、季節ができる本当の理由についての3問。 中学校 理科（天体） 1. 地球の運動と星の動き 地球に「四季（春夏秋冬）」の変化が生まれる最も大きな原因は次のうちどれでしょう？ 実は日本（北半球）が冬のほうが地球と太陽の距離は少し近いのです！四季がある理由は「地軸が約23.4度傾いたまま公転しているため、太陽の南中高度と昼の長さが変わるから」です。 日本（北半球）において、1年で「太陽の南中高度が最も高く、昼の長さが最も長い日」を何というでしょう？ 6月下旬ごろの「夏至」に太陽の南中高度が最高（春分・秋分より＋23.4度）になり、真東より北寄りから日が昇ります。12月下旬の「冬至」は南中高度が最低になります。 「春分」と「秋分」の日には、太陽は真東から昇って真西に沈み、昼の長さと夜の長さがほぼ同じ（約12時間ずつ）になる。 正解！春分・秋分の日は北緯L度の地点での太陽の南中高度が「90° － 緯度」でぴったり計算できます（例：北緯35度なら 90 - 35 = 55度）。"}, {"id": "jh-astro-set4", "school": "jh", "schoolName": "中学校", "subject": "science_astro", "subjectName": "理科（天体）", "topic": "2. 月・金星と日食・月食", "title": "セット4: 月の満ち欠けのしくみ", "description": "新月・上弦・満月・下弦の位置関係、夕方と明け方の月の見え方についての3問。", "dataFile": "sample/junior_high/astronomy/astronomy.json", "questionCount": 3, "questionTypes": "4択・〇×", "previewQuestions": [{"type": "4choice", "question": "月が満ち欠けして見える（新月→上弦の月→満月→下弦の月）のはなぜでしょう？"}, {"type": "4choice", "question": "夕方（午後6時ごろ）に真南の空に見える、右側（西側）が半分光っている月を何というでしょう？"}, {"type": "2choice", "question": "満月は太陽と地球を挟んで反対側にあるため、夕方ごろ東の空から昇り、真夜中に南中して、明け方に西の空へ沈む。"}], "searchText": "セット4: 月の満ち欠けのしくみ 新月・上弦・満月・下弦の位置関係、夕方と明け方の月の見え方についての3問。 中学校 理科（天体） 2. 月・金星と日食・月食 月が満ち欠けして見える（新月→上弦の月→満月→下弦の月）のはなぜでしょう？ 月は自ら光らず太陽の光を反射しています。約29.5日周期で月が地球のまわりを公転するため、太陽・地球・月の位置関係が変わり、地球から見える光る面が変化します。（※地球の影に入るのは月食！） 夕方（午後6時ごろ）に真南の空に見える、右側（西側）が半分光っている月を何というでしょう？ 夕方の南の空に半月が見えたら「上弦の月」（右半分が光り、その後西の空へ沈む）、逆に明け方の南の空に見える半月が「下弦の月」です！ 満月は太陽と地球を挟んで反対側にあるため、夕方ごろ東の空から昇り、真夜中に南中して、明け方に西の空へ沈む。 正解！太陽と反対方向にあるため、太陽が西に沈む夕方に東から上り、一晩中夜空を照らします。"}, {"id": "jh-astro-set5", "school": "jh", "schoolName": "中学校", "subject": "science_astro", "subjectName": "理科（天体）", "topic": "2. 月・金星と日食・月食", "title": "セット5: 金星の見え方（明けの明星・よいの明星）", "description": "内惑星・金星が真夜中に見えない理由、大きさと満ち欠けの変化についての3問。", "dataFile": "sample/junior_high/astronomy/astronomy.json", "questionCount": 3, "questionTypes": "4択・〇×", "previewQuestions": [{"type": "4choice", "question": "太陽系の惑星である「金星」が、真夜中（午前0時ごろ）の空に絶対に見ることができない理由は何でしょう？"}, {"type": "4choice", "question": "金星を天体望遠鏡で続けて観察すると、三日月のように大きく欠けた形に見えるときと、丸く満ちた形に見えるときで、見かけの大きさはどう変わるでしょう？"}, {"type": "2choice", "question": "夕方、太陽が沈んだ直後の「西の空」にひときわ明るく輝いて見える金星を「よいの明星」という。"}], "searchText": "セット5: 金星の見え方（明けの明星・よいの明星） 内惑星・金星が真夜中に見えない理由、大きさと満ち欠けの変化についての3問。 中学校 理科（天体） 2. 月・金星と日食・月食 太陽系の惑星である「金星」が、真夜中（午前0時ごろ）の空に絶対に見ることができない理由は何でしょう？ 水星と金星は地球の公転軌道より内側にある「内惑星」なので、地球からは常に太陽に近い方向にしか見えません。そのため「夕方（西の空＝よいの明星）」か「明け方（東の空＝明けの明星）」だけ見られます！ 金星を天体望遠鏡で続けて観察すると、三日月のように大きく欠けた形に見えるときと、丸く満ちた形に見えるときで、見かけの大きさはどう変わるでしょう？ 金星が地球に近い位置にきたときは大きく（でも太陽が向こう側なので大きく欠けた三日月形に）見え、太陽の向こう側にあるときは丸く小さく見えます。これは天動説を覆す大きな証拠になりました！ 夕方、太陽が沈んだ直後の「西の空」にひときわ明るく輝いて見える金星を「よいの明星」という。 正解！日没後の西の空に見えるのが「よいの明星」、日の出前の東の空に見えるのが「明けの明星」です。"}, {"id": "jh-astro-set6", "school": "jh", "schoolName": "中学校", "subject": "science_astro", "subjectName": "理科（天体）", "topic": "2. 月・金星と日食・月食", "title": "セット6: 日食と月食のしくみ", "description": "皆既日食・金環日食・皆既月食が起こるときの太陽・地球・月の並び方についての3問。", "dataFile": "sample/junior_high/astronomy/astronomy.json", "questionCount": 3, "questionTypes": "4択・〇×", "previewQuestions": [{"type": "4choice", "question": "「日食」が起こるとき、太陽・月・地球の3つの天体は一直線上にどの順番で並んでいるでしょう？"}, {"type": "4choice", "question": "皆既月食のときに月が真っ暗になって消えるのではなく、赤銅色（赤黒い色）にうっすら光って見えるのはなぜでしょう？"}, {"type": "2choice", "question": "「月食」は地球が太陽と月の間に入り、地球の影の中に月が入ることで起こるため、必ず「満月」のときに起こる。"}], "searchText": "セット6: 日食と月食のしくみ 皆既日食・金環日食・皆既月食が起こるときの太陽・地球・月の並び方についての3問。 中学校 理科（天体） 2. 月・金星と日食・月食 「日食」が起こるとき、太陽・月・地球の3つの天体は一直線上にどの順番で並んでいるでしょう？ 「日食」は、太陽と地球の間に「月」が入り、月の影が地球に落ちて太陽が隠れて見える現象です。つまり必ず「新月」のときに起こります！ 皆既月食のときに月が真っ暗になって消えるのではなく、赤銅色（赤黒い色）にうっすら光って見えるのはなぜでしょう？ 夕焼けが赤く見えるのと同じ原理で、地球の大気を通り抜けた長波長の赤い太陽光がわずかに屈折して地球の影の中に入り、皆既月食の月を赤銅色に照らします。 「月食」は地球が太陽と月の間に入り、地球の影の中に月が入ることで起こるため、必ず「満月」のときに起こる。 正解！月の公転面が地球の公転面に対して約5度傾いているため、毎回の新月・満月ではなく、並びがぴったり重なったときだけ日食や月食が見られます。"}, {"id": "jh-astro-set7", "school": "jh", "schoolName": "中学校", "subject": "science_astro", "subjectName": "理科（天体）", "topic": "3. 太陽・太陽系と宇宙", "title": "セット7: 太陽の特徴と表面の現象", "description": "太陽の黒点・コロナ・プロミネンス、黒点の移動からわかる太陽の自転についての3問。", "dataFile": "sample/junior_high/astronomy/astronomy.json", "questionCount": 3, "questionTypes": "4択・〇×", "previewQuestions": [{"type": "4choice", "question": "太陽の表面に見られる黒いしみのような「黒点」が、まわりより黒く見える本当の理由は何でしょう？"}, {"type": "4choice", "question": "天体望遠鏡に投影板を取り付けて太陽の黒点を数日間観察し続けると、黒点が東から西へ移動し、端にくると細長くなります。このことから何がわかるでしょう？"}, {"type": "2choice", "question": "皆既日食のときなどに太陽のまわりに見える、数百万度もの高温の希薄なガスの層を「コロナ」という。"}], "searchText": "セット7: 太陽の特徴と表面の現象 太陽の黒点・コロナ・プロミネンス、黒点の移動からわかる太陽の自転についての3問。 中学校 理科（天体） 3. 太陽・太陽系と宇宙 太陽の表面に見られる黒いしみのような「黒点」が、まわりより黒く見える本当の理由は何でしょう？ 黒点も実は約4000℃もあり猛烈に輝いていますが、まわりが約6000℃とさらに明るいため、光のコントラストで相対的に黒く見えています！ 天体望遠鏡に投影板を取り付けて太陽の黒点を数日間観察し続けると、黒点が東から西へ移動し、端にくると細長くなります。このことから何がわかるでしょう？ 黒点が同じ向きに移動し、縁に近づくにつれて細長い楕円に見えることは、太陽が「球体」で「自転している（約25〜30日で1回転）」証拠です！ 皆既日食のときなどに太陽のまわりに見える、数百万度もの高温の希薄なガスの層を「コロナ」という。 正解！太陽の縁から炎のように吹き上がるガスの柱は「プロミネンス（紅炎）」、外側を取り巻く真珠色の輝きが「コロナ」です。"}, {"id": "jh-astro-set8", "school": "jh", "schoolName": "中学校", "subject": "science_astro", "subjectName": "理科（天体）", "topic": "3. 太陽・太陽系と宇宙", "title": "セット8: 太陽系の8つの惑星", "description": "水星〜海王星までの太陽系の並び順、小惑星帯、彗星（すいせい）についての3問。", "dataFile": "sample/junior_high/astronomy/astronomy.json", "questionCount": 3, "questionTypes": "4択・〇×", "previewQuestions": [{"type": "4choice", "question": "太陽に近い順から「水・金・地・火・木・土・（　）・（　）」と並ぶ太陽系の8つの惑星。最後の2つはどれでしょう？"}, {"type": "4choice", "question": "太陽系の中で最も大きく、しま模様と「大赤斑」と呼ばれる巨大な渦巻きをもつ惑星はどれでしょう？"}, {"type": "2choice", "question": "火星と木星の間には「小惑星」と呼ばれる小さな天体が多数集まっており、日本の探査機「はやぶさ」や「はやぶさ2」は小惑星から砂や石を持ち帰った。"}], "searchText": "セット8: 太陽系の8つの惑星 水星〜海王星までの太陽系の並び順、小惑星帯、彗星（すいせい）についての3問。 中学校 理科（天体） 3. 太陽・太陽系と宇宙 太陽に近い順から「水・金・地・火・木・土・（　）・（　）」と並ぶ太陽系の8つの惑星。最後の2つはどれでしょう？ 「水金地火木土天海（すいきんちかもくどってんかい）」の8惑星です！冥王星は2006年に「準惑星」に分類が変更されました。 太陽系の中で最も大きく、しま模様と「大赤斑」と呼ばれる巨大な渦巻きをもつ惑星はどれでしょう？ 太陽系最大の惑星「木星」は、地球が約1,300個も入るほどの大きさがあります。美しい氷と岩石の輪で有名なのが「土星」です。 火星と木星の間には「小惑星」と呼ばれる小さな天体が多数集まっており、日本の探査機「はやぶさ」や「はやぶさ2」は小惑星から砂や石を持ち帰った。 正解！「はやぶさ」が小惑星イトカワ、「はやぶさ2」が小惑星リュウグウの試料を持ち帰るという世界的な快挙を成し遂げました！"}, {"id": "jh-astro-set9", "school": "jh", "schoolName": "中学校", "subject": "science_astro", "subjectName": "理科（天体）", "topic": "3. 太陽・太陽系と宇宙", "title": "セット9: 地球型惑星と木星型惑星", "description": "岩石中心の地球型惑星とガス・氷中心の木星型惑星の特徴比較についての3問。", "dataFile": "sample/junior_high/astronomy/astronomy.json", "questionCount": 3, "questionTypes": "4択・〇×", "previewQuestions": [{"type": "4choice", "question": "「水星・金星・地球・火星」の4つの『地球型惑星』の特徴として正しいものはどれでしょう？"}, {"type": "4choice", "question": "厚い二酸化炭素の大気による強い温室効果のため、表面温度が約460℃もの高温になっている地球型惑星はどれでしょう？"}, {"type": "2choice", "question": "「彗星（すいせい・ほうき星）」は氷やちりなどでできており、太陽に近づくと太陽からの風や光に押されて、太陽と「同じ側」に向かって長い尾が伸びる。"}], "searchText": "セット9: 地球型惑星と木星型惑星 岩石中心の地球型惑星とガス・氷中心の木星型惑星の特徴比較についての3問。 中学校 理科（天体） 3. 太陽・太陽系と宇宙 「水星・金星・地球・火星」の4つの『地球型惑星』の特徴として正しいものはどれでしょう？ 地球型惑星は小さくても岩石・鉄などの重い物質でできているため「密度が大きい」のが特徴。逆に木星・土星などの「木星型惑星」は巨大ですがガス中心のため「密度が小さい」です（土星は水より軽い密度！）。 厚い二酸化炭素の大気による強い温室効果のため、表面温度が約460℃もの高温になっている地球型惑星はどれでしょう？ 一番太陽に近い「水星」よりも、濃い二酸化炭素に覆われた「金星」のほうが昼も夜も約460℃と超高温です。温室効果ガスの威力がよくわかる例です。 「彗星（すいせい・ほうき星）」は氷やちりなどでできており、太陽に近づくと太陽からの風や光に押されて、太陽と「同じ側」に向かって長い尾が伸びる。 ひっかけ問題！彗星の尾は、太陽から吹き付ける太陽風や光の圧力で押し流されるため、進む向きに関係なく常に「太陽と反対側」に尾が伸びます！"}, {"id": "jh-astro-set10", "school": "jh", "schoolName": "中学校", "subject": "science_astro", "subjectName": "理科（天体）", "topic": "3. 太陽・太陽系と宇宙", "title": "セット10: 恒星・銀河系と宇宙の広がり", "description": "恒星と惑星の違い、光年、天の川と銀河系についての3問。", "dataFile": "sample/junior_high/astronomy/astronomy.json", "questionCount": 3, "questionTypes": "4択・〇×", "previewQuestions": [{"type": "4choice", "question": "夜空に輝く「天の川（あまのがわ）」の正体として正しいものはどれでしょう？"}, {"type": "4choice", "question": "宇宙の遠い距離を表す単位「1光年」とは、何の距離を表しているでしょう？"}, {"type": "2choice", "question": "太陽や北極星・ベガのように、自ら光と熱を出して輝いている天体を「恒星（こうせい）」という。"}], "searchText": "セット10: 恒星・銀河系と宇宙の広がり 恒星と惑星の違い、光年、天の川と銀河系についての3問。 中学校 理科（天体） 3. 太陽・太陽系と宇宙 夜空に輝く「天の川（あまのがわ）」の正体として正しいものはどれでしょう？ 太陽系は直径約10万光年の円盤状の「銀河系（天の川銀河）」の端のほうに位置しています。地球から円盤の内側方向を見ると星が密集して帯のように見えるのが「天の川」です！ 宇宙の遠い距離を表す単位「1光年」とは、何の距離を表しているでしょう？ 「光年」は時間ではなく「距離」の単位です！1秒間に地球を7周半する速さの光が1年かけて進む距離が1光年。太陽の次に近い恒星まででも約4.2光年かかります。 太陽や北極星・ベガのように、自ら光と熱を出して輝いている天体を「恒星（こうせい）」という。 正解！星座を形づくる星のほとんどは太陽と同じ「恒星」です。自ら光らない「惑星（地球や木星など）」とは区別しましょう。"}, {"id": "jh-chem-set1", "school": "jh", "schoolName": "中学校", "subject": "science_chem", "subjectName": "理科（科学）", "topic": "1. 身のまわりの物質と水溶液", "title": "セット1: 物質の性質・有機物と密度", "description": "金属の性質、有機物と無機物の区別、密度の計算についての3問。", "dataFile": "sample/junior_high/science/science.json", "questionCount": 3, "questionTypes": "4択・〇×", "previewQuestions": [{"type": "4choice", "question": "加熱するとこげて炭になり、二酸化炭素と水を発生させる「有機物」にあてはまる物質はどれでしょう？"}, {"type": "4choice", "question": "「金属」に共通する5つの性質のうち、たたいて薄く広げることができる性質を何というでしょう？"}, {"type": "2choice", "question": "物質1cm³あたりの質量を「密度（g/cm³）」といい、同じ種類の物質であれば大きさがちがっても密度はつねに一定である。"}], "searchText": "セット1: 物質の性質・有機物と密度 金属の性質、有機物と無機物の区別、密度の計算についての3問。 中学校 理科（科学） 1. 身のまわりの物質と水溶液 加熱するとこげて炭になり、二酸化炭素と水を発生させる「有機物」にあてはまる物質はどれでしょう？ 炭素を含む物質（ただし二酸化炭素や炭酸塩を除く）で、燃やすと炭になったり二酸化炭素を出すのが「有機物」です。砂糖・ろう・プラスチック・エタノールなどが代表例です！ 「金属」に共通する5つの性質のうち、たたいて薄く広げることができる性質を何というでしょう？ 金属には①電気をよく通す ②熱をよく伝える ③みがくと金属光沢が出る ④たたいて広がる「展性」（アルミホイルなど） ⑤引っぱってのびる「延性」（銅線など）の性質があります！ 物質1cm³あたりの質量を「密度（g/cm³）」といい、同じ種類の物質であれば大きさがちがっても密度はつねに一定である。 正解！「密度 ＝ 質量 ÷ 体積」で計算します。例えば水の密度は約1.0g/cm³なので、それより密度が小さい木や氷・油は水に浮き、大きい鉄やアルミは沈みます。"}, {"id": "jh-chem-set2", "school": "jh", "schoolName": "中学校", "subject": "science_chem", "subjectName": "理科（科学）", "topic": "1. 身のまわりの物質と水溶液", "title": "セット2: 気体の性質と集め方", "description": "酸素・二酸化炭素・水素・アンモニアの性質と、水上・上方・下方置換法についての3問。", "dataFile": "sample/junior_high/science/science.json", "questionCount": 3, "questionTypes": "4択・〇×", "previewQuestions": [{"type": "4choice", "question": "水にとけやすく空気よりとても軽いため「上方置換法」で集め、フェノールフタレイン溶液を赤く変える刺激臭のある気体はどれでしょう？"}, {"type": "4choice", "question": "気体の発生方法で、二酸化マンガンにうすい過酸化水素水（オキシドール）を加えると発生する気体は何でしょう？"}, {"type": "2choice", "question": "水にとけにくい気体（酸素・水素・窒素など）を集めるときは、純粋な気体が集めやすく集まった量も一目でわかる「水上置換法」を使うのが最もよい。"}], "searchText": "セット2: 気体の性質と集め方 酸素・二酸化炭素・水素・アンモニアの性質と、水上・上方・下方置換法についての3問。 中学校 理科（科学） 1. 身のまわりの物質と水溶液 水にとけやすく空気よりとても軽いため「上方置換法」で集め、フェノールフタレイン溶液を赤く変える刺激臭のある気体はどれでしょう？ アンモニアは水に非常によく溶けて「アルカリ性」を示すため、フェノールフタレインを赤色にします。水にとけやすいため水上置換ではなく、空気より軽いので「上方置換法」で集めます！ 気体の発生方法で、二酸化マンガンにうすい過酸化水素水（オキシドール）を加えると発生する気体は何でしょう？ 「二酸化マンガン ＋ うすい過酸化水素水 → 酸素」（火のついた線香を激しく燃やす助燃性あり！）。ちなみに石灰石＋うすい塩酸は「二酸化炭素」、亜鉛や鉄＋うすい塩酸は「水素」です。 水にとけにくい気体（酸素・水素・窒素など）を集めるときは、純粋な気体が集めやすく集まった量も一目でわかる「水上置換法」を使うのが最もよい。 正解！少しだけ水に溶ける二酸化炭素も、実験室では純度よく集めるために水上置換法が使われることが多いです（大量に集めるときは下方置換法）。"}, {"id": "jh-chem-set3", "school": "jh", "schoolName": "中学校", "subject": "science_chem", "subjectName": "理科（科学）", "topic": "1. 身のまわりの物質と水溶液", "title": "セット3: 水溶液と溶解度・再結晶", "description": "溶質・溶媒・溶液、質量パーセント濃度、溶解度曲線と再結晶についての3問。", "dataFile": "sample/junior_high/science/science.json", "questionCount": 3, "questionTypes": "4択・〇×", "previewQuestions": [{"type": "4choice", "question": "100gの水に25gの食塩を完全にとかしたとき、できた食塩水の「質量パーセント濃度」は何％になるでしょう？"}, {"type": "4choice", "question": "ミョウバンや硝酸カリウムのように「水の温度によって溶ける量（溶解度）が大きく変わる物質」を、熱いお湯にとかしたあと冷やして結晶を取り出す方法を何というでしょう？"}, {"type": "2choice", "question": "透明な水溶液の中で溶質が均一に散らばっているとき、しばらく置いておいても下に溶質が沈んだり濃さが上下で変わったりすることはない。"}], "searchText": "セット3: 水溶液と溶解度・再結晶 溶質・溶媒・溶液、質量パーセント濃度、溶解度曲線と再結晶についての3問。 中学校 理科（科学） 1. 身のまわりの物質と水溶液 100gの水に25gの食塩を完全にとかしたとき、できた食塩水の「質量パーセント濃度」は何％になるでしょう？ 超定番のひっかけ注意問題！濃度は「溶質 ÷ 溶液全体（水＋溶質） × 100」で計算します。ここでは水100g＋食塩25g＝125gなので、25 ÷ 125 × 100 ＝ 20％ になります！ ミョウバンや硝酸カリウムのように「水の温度によって溶ける量（溶解度）が大きく変わる物質」を、熱いお湯にとかしたあと冷やして結晶を取り出す方法を何というでしょう？ 温度を下げて溶けきれなくなった分を純粋な結晶として取り出す操作を「再結晶」といいます。なお、食塩は温度を変えても溶解度がほとんど変わらないため、水を蒸発させて結晶を取り出します。 透明な水溶液の中で溶質が均一に散らばっているとき、しばらく置いておいても下に溶質が沈んだり濃さが上下で変わったりすることはない。 正解！「透明」「どこをとっても同じ濃さ」「時間がたっても沈まない」「ろ紙を通り抜ける」が水溶液の性質です（青色や紫色など色がついている水溶液でも、透き通っていれば透明です）。"}, {"id": "jh-chem-set4", "school": "jh", "schoolName": "中学校", "subject": "science_chem", "subjectName": "理科（科学）", "topic": "1. 身のまわりの物質と水溶液", "title": "セット4: 状態変化と蒸留", "description": "固体・液体・気体の体積変化、融点・沸点、沸点のちがいを利用した「蒸留」についての3問。", "dataFile": "sample/junior_high/science/science.json", "questionCount": 3, "questionTypes": "4択・〇×", "previewQuestions": [{"type": "4choice", "question": "水とエタノールの混合物を加熱し、沸点のちがい（エタノール約78℃、水100℃）を利用して液体どうしを分離する方法を何というでしょう？"}, {"type": "4choice", "question": "一般的な物質が「固体 → 液体 → 気体」と状態変化するとき、粒子の動きと体積はどう変化するでしょう？（水から氷などの例外を除く）"}, {"type": "2choice", "question": "液体を熱して沸騰させるとき、急激な沸騰（突沸）を防ぐためにフラスコの中に入れておく小さな石を「沸騰石」という。"}], "searchText": "セット4: 状態変化と蒸留 固体・液体・気体の体積変化、融点・沸点、沸点のちがいを利用した「蒸留」についての3問。 中学校 理科（科学） 1. 身のまわりの物質と水溶液 水とエタノールの混合物を加熱し、沸点のちがい（エタノール約78℃、水100℃）を利用して液体どうしを分離する方法を何というでしょう？ 液体を加熱して気体にし、それを冷やして再び純度の高い液体として取り出す方法を「蒸留」といいます。石油（原油）からガソリンや灯油を分けるときも同じ原理が使われています！ 一般的な物質が「固体 → 液体 → 気体」と状態変化するとき、粒子の動きと体積はどう変化するでしょう？（水から氷などの例外を除く） 状態変化をしても物質の粒子そのものの種類や数は変わらないため「質量は変化せず一定」です。一方、粒子どうしのすき間が広がるため「体積は大きく」なります（※水は氷になるとき体積が増える特別な例外です！）。 液体を熱して沸騰させるとき、急激な沸騰（突沸）を防ぐためにフラスコの中に入れておく小さな石を「沸騰石」という。 正解！沸騰石の表面の小さな穴から気泡が穏やかに発生し続けることで、突然中身が吹き出す「突沸」を安全に防いでくれます。"}, {"id": "jh-chem-set5", "school": "jh", "schoolName": "中学校", "subject": "science_chem", "subjectName": "理科（科学）", "topic": "2. 原子・分子と化学変化", "title": "セット5: 原子・分子と化学式", "description": "ドルトンの原子説、分子をつくる物質とつくらない物質、代表的な化学式についての3問。", "dataFile": "sample/junior_high/science/science.json", "questionCount": 3, "questionTypes": "4択・〇×", "previewQuestions": [{"type": "4choice", "question": "物質を構成する最小の粒である「原子」の性質として、正しくない（誤っている）ものはどれでしょう？"}, {"type": "4choice", "question": "「二酸化炭素」「アンモニア」「塩化ナトリウム（食塩）」を化学式で表したときの正しい組み合わせはどれでしょう？"}, {"type": "2choice", "question": "「炭酸水素ナトリウム（重曹）」を加熱すると、炭酸ナトリウム・二酸化炭素・水の3つの物質に分解される（熱分解）。"}], "searchText": "セット5: 原子・分子と化学式 ドルトンの原子説、分子をつくる物質とつくらない物質、代表的な化学式についての3問。 中学校 理科（科学） 2. 原子・分子と化学変化 物質を構成する最小の粒である「原子」の性質として、正しくない（誤っている）ものはどれでしょう？ 原子は①それ以上分けられない ②なくならない ③新しくできない ④別の種類の原子に変わらない ⑤決まった質量がある、というのがドルトンの原子の性質です！（組み合わせだけが変わります） 「二酸化炭素」「アンモニア」「塩化ナトリウム（食塩）」を化学式で表したときの正しい組み合わせはどれでしょう？ 二酸化炭素＝CO₂、アンモニア＝NH₃、塩化ナトリウム＝NaCl です。なお金属（Fe, Cuなど）や塩化ナトリウム（NaCl）は「分子をつくらない物質」として多くの原子・イオンが規則正しく並んでいます。 「炭酸水素ナトリウム（重曹）」を加熱すると、炭酸ナトリウム・二酸化炭素・水の3つの物質に分解される（熱分解）。 正解！ホットケーキやカルメ焼きがふくらむのは、ベーキングパウダー中の炭酸水素ナトリウムが熱で分解されて「二酸化炭素」の泡が出るためです！"}, {"id": "jh-chem-set6", "school": "jh", "schoolName": "中学校", "subject": "science_chem", "subjectName": "理科（科学）", "topic": "2. 原子・分子と化学変化", "title": "セット6: 分解と化合（電気分解・硫化）", "description": "水の電気分解の体積比（2:1）、鉄と硫黄の化合（硫化鉄）、発熱・吸熱反応についての3問。", "dataFile": "sample/junior_high/science/science.json", "questionCount": 3, "questionTypes": "4択・〇×", "previewQuestions": [{"type": "4choice", "question": "水（水酸化ナトリウムを少量溶かした水）を電気分解したとき、陰極（－極）と陽極（＋極）に集まる気体とその体積比の正しい組み合わせはどれでしょう？"}, {"type": "4choice", "question": "鉄粉と硫黄の粉末を混ぜて加熱すると「硫化鉄」ができます。できた硫化鉄にうすい塩酸を加えると、どんな特徴のある気体が発生するでしょう？"}, {"type": "2choice", "question": "使い捨てカイロが温かくなるのは、鉄粉が空気中の酸素と結びついて酸化するときに熱を出す「発熱反応」を利用している。"}], "searchText": "セット6: 分解と化合（電気分解・硫化） 水の電気分解の体積比（2:1）、鉄と硫黄の化合（硫化鉄）、発熱・吸熱反応についての3問。 中学校 理科（科学） 2. 原子・分子と化学変化 水（水酸化ナトリウムを少量溶かした水）を電気分解したとき、陰極（－極）と陽極（＋極）に集まる気体とその体積比の正しい組み合わせはどれでしょう？ 水の化学式 H₂O の通り、水素(H₂)：酸素(O₂)＝2：1 の体積比で発生します。「陰極＝水素(2)、陽極＝酸素(1)」！（マッチを近づけるとポンッと燃えるのが陰極の水素です） 鉄粉と硫黄の粉末を混ぜて加熱すると「硫化鉄」ができます。できた硫化鉄にうすい塩酸を加えると、どんな特徴のある気体が発生するでしょう？ 鉄＋塩酸なら無臭の「水素」が出ますが、鉄と硫黄が化合した「硫化鉄」は磁石につかなくなり、塩酸を加えると有毒で腐卵臭のある「硫化水素（H₂S）」が発生します！ 使い捨てカイロが温かくなるのは、鉄粉が空気中の酸素と結びついて酸化するときに熱を出す「発熱反応」を利用している。 正解！逆に炭酸水素ナトリウムとクエン酸の反応や、水酸化バリウムと塩化アンモニウムを混ぜたときのように、まわりから熱を奪って冷たくなる反応を「吸熱反応」といいます。"}, {"id": "jh-chem-set7", "school": "jh", "schoolName": "中学校", "subject": "science_chem", "subjectName": "理科（科学）", "topic": "2. 原子・分子と化学変化", "title": "セット7: 酸化・還元と質量保存の法則", "description": "銅・マグネシウムの酸化と定比例の法則、酸化銅の炭素による還元、質量保存の法則についての3問。", "dataFile": "sample/junior_high/science/science.json", "questionCount": 3, "questionTypes": "4択・〇×", "previewQuestions": [{"type": "4choice", "question": "黒い「酸化銅」の粉末に「炭素（木炭）」の粉末を混ぜて強く加熱すると、赤茶色の「銅」と二酸化炭素ができます。このとき酸化銅が酸素を奪われる変化を何というでしょう？"}, {"type": "4choice", "question": "銅を加熱して酸化銅にすると、銅：酸素：酸化銅の質量比は常に「4：1：5」になります。銅 2.0g を完全に酸化させると、何gの酸化銅ができるでしょう？"}, {"type": "2choice", "question": "気体が発生する化学変化でも、密閉された容器の中で行えば、反応の前と後で全体の質量はまったく変わらない（質量保存の法則）。"}], "searchText": "セット7: 酸化・還元と質量保存の法則 銅・マグネシウムの酸化と定比例の法則、酸化銅の炭素による還元、質量保存の法則についての3問。 中学校 理科（科学） 2. 原子・分子と化学変化 黒い「酸化銅」の粉末に「炭素（木炭）」の粉末を混ぜて強く加熱すると、赤茶色の「銅」と二酸化炭素ができます。このとき酸化銅が酸素を奪われる変化を何というでしょう？ 酸化物から酸素が取り除かれる変化を「還元」といいます！このとき炭素は逆に酸素と結びついて「酸化」されているため、酸化と還元は必ず同時に起こります。 銅を加熱して酸化銅にすると、銅：酸素：酸化銅の質量比は常に「4：1：5」になります。銅 2.0g を完全に酸化させると、何gの酸化銅ができるでしょう？ 銅：酸素＝4：1 なので、銅2.0gには 2.0 ÷ 4 ＝ 0.5g の酸素が結びつきます。したがってできる酸化銅は 2.0 ＋ 0.5 ＝ 2.5g！（マグネシウムは 3：2：5 で覚えましょう！） 気体が発生する化学変化でも、密閉された容器の中で行えば、反応の前と後で全体の質量はまったく変わらない（質量保存の法則）。 正解！オープンなビーカーだと発生した二酸化炭素などの気体が空気中へ逃げて軽くなったように見えますが、密閉すればすべての原子が残るため質量は100%保存されます！"}, {"id": "jh-chem-set8", "school": "jh", "schoolName": "中学校", "subject": "science_chem", "subjectName": "理科（科学）", "topic": "3. イオン・科学の基礎", "title": "セット8: 電解質・イオンと電気分解", "description": "電解質と非電解質、陽イオンと陰イオン、塩化銅水溶液の電気分解についての3問。", "dataFile": "sample/junior_high/science/science.json", "questionCount": 3, "questionTypes": "4択・〇×", "previewQuestions": [{"type": "4choice", "question": "水に溶かしたときに電離して電流が流れる「電解質」ではなく、電流が流れない「非電解質」にあたる物質はどれでしょう？"}, {"type": "4choice", "question": "青色の「塩化銅水溶液」に電流を流して電気分解すると、陰極（－極）と陽極（＋極）にはそれぞれ何ができるでしょう？"}, {"type": "2choice", "question": "原子が電子を「失う」とプラスの電気を帯びた「陽イオン」になり、電子を「受け取る」とマイナスの電気を帯びた「陰イオン」になる。"}], "searchText": "セット8: 電解質・イオンと電気分解 電解質と非電解質、陽イオンと陰イオン、塩化銅水溶液の電気分解についての3問。 中学校 理科（科学） 3. イオン・科学の基礎 水に溶かしたときに電離して電流が流れる「電解質」ではなく、電流が流れない「非電解質」にあたる物質はどれでしょう？ 食塩水や塩酸・レモン汁などの「電解質」は水中で陽イオンと陰イオンに分かれる（電離する）ため電気を通します。砂糖水やエタノール水溶液はイオンにならず電気を通しません（非電解質）。 青色の「塩化銅水溶液」に電流を流して電気分解すると、陰極（－極）と陽極（＋極）にはそれぞれ何ができるでしょう？ 銅イオン（Cu²⁺）はプラスの電気を持つため陰極（－）へ引き寄せられて「銅」が付着し、塩化物イオン（Cl⁻）はマイナスの電気を持つため陽極（＋）へ引き寄せられて「塩素」が発生します！ 原子が電子を「失う」とプラスの電気を帯びた「陽イオン」になり、電子を「受け取る」とマイナスの電気を帯びた「陰イオン」になる。 正解！電子は「マイナス」の電気を持っているため、マイナスを1つ失うとプラスが1つ多い「陽イオン（例：Na⁺）」になり、マイナスを受け取ると「陰イオン（例：Cl⁻）」になります。"}, {"id": "jh-chem-set9", "school": "jh", "schoolName": "中学校", "subject": "science_chem", "subjectName": "理科（科学）", "topic": "3. イオン・科学の基礎", "title": "セット9: 酸・アルカリと中和反応・塩", "description": "水素イオンと水酸化物イオン、BTB溶液・pH、中和と塩（えん）についての3問。", "dataFile": "sample/junior_high/science/science.json", "questionCount": 3, "questionTypes": "4択・〇×", "previewQuestions": [{"type": "4choice", "question": "「酸性」の水溶液に共通する性質を決めるイオンと、「アルカリ性」の性質を決めるイオンの組み合わせはどれでしょう？"}, {"type": "4choice", "question": "塩酸（HCl）と水酸化ナトリウム水溶液（NaOH）をちょうど過不足なく混ぜ合わせて「中和」したときにできる2つの物質は何でしょう？"}, {"type": "2choice", "question": "うすい塩酸にマグネシウムや亜鉛などの金属を入れると、気体の「水素」を発生しながら溶ける。"}], "searchText": "セット9: 酸・アルカリと中和反応・塩 水素イオンと水酸化物イオン、BTB溶液・pH、中和と塩（えん）についての3問。 中学校 理科（科学） 3. イオン・科学の基礎 「酸性」の水溶液に共通する性質を決めるイオンと、「アルカリ性」の性質を決めるイオンの組み合わせはどれでしょう？ 酸性は「H⁺（水素イオン）」、アルカリ性は「OH⁻（水酸化物イオン）」が正体です！酸性はBTB溶液を黄色、アルカリ性は青色、中性は緑色にします。 塩酸（HCl）と水酸化ナトリウム水溶液（NaOH）をちょうど過不足なく混ぜ合わせて「中和」したときにできる2つの物質は何でしょう？ 酸の H⁺ とアルカリの OH⁻ が結びついて「水（H₂O）」ができ、残った陽イオンと陰イオンが結びついて「塩（えん：ここでは塩化ナトリウム）」ができます。つまり「酸＋アルカリ → 水＋塩」です！ うすい塩酸にマグネシウムや亜鉛などの金属を入れると、気体の「水素」を発生しながら溶ける。 正解！多くの酸性の水溶液は、鉄・亜鉛・マグネシウムなどの金属と反応して「水素」を発生させます（ただし銅や金などはうすい塩酸には溶けません）。"}, {"id": "jh-chem-set10", "school": "jh", "schoolName": "中学校", "subject": "science_chem", "subjectName": "理科（科学）", "topic": "3. イオン・科学の基礎", "title": "セット10: 電池・電流や光・力の科学基礎", "description": "化学電池（ダニエル電池等）、オームの法則、光の屈折と力学的エネルギーについての3問。", "dataFile": "sample/junior_high/science/science.json", "questionCount": 3, "questionTypes": "4択・〇×", "previewQuestions": [{"type": "4choice", "question": "2種類の異なる金属板（例：銅板と亜鉛板）を電解質の水溶液に入れて導線でつなぐ「化学電池」で、電子が流れ出して金属が溶けやすい（－極になる）のはどちらでしょう？"}, {"type": "4choice", "question": "電気回路において、抵抗が10Ωの電熱線に5V（ボルト）の電圧を加えたとき、この電熱線を流れる電流は何A（アンペア）になるでしょう？"}, {"type": "2choice", "question": "空気中から水やガラスの中へ光が斜めに進むとき、光は境界線で折れ曲がり（屈折し）、入射角よりも屈折角のほうが「小さく」なる。"}], "searchText": "セット10: 電池・電流や光・力の科学基礎 化学電池（ダニエル電池等）、オームの法則、光の屈折と力学的エネルギーについての3問。 中学校 理科（科学） 3. イオン・科学の基礎 2種類の異なる金属板（例：銅板と亜鉛板）を電解質の水溶液に入れて導線でつなぐ「化学電池」で、電子が流れ出して金属が溶けやすい（－極になる）のはどちらでしょう？ 亜鉛は銅よりも「陽イオンになりやすい」性質があるため、亜鉛原子が電子を金属板に残してZn²⁺として溶け出し、その電子が導線を通って銅板へ流れるため亜鉛が「－極」になります！ 電気回路において、抵抗が10Ωの電熱線に5V（ボルト）の電圧を加えたとき、この電熱線を流れる電流は何A（アンペア）になるでしょう？ オームの法則「電圧(V) ＝ 電流(A) × 抵抗(Ω)」より、電流 ＝ 電圧 ÷ 抵抗 ＝ 5V ÷ 10Ω ＝ 0.5A になります！ 空気中から水やガラスの中へ光が斜めに進むとき、光は境界線で折れ曲がり（屈折し）、入射角よりも屈折角のほうが「小さく」なる。 正解！「空気 → 水・ガラス」のときは入射角＞屈折角になり、逆に「水・ガラス → 空気」へ出るときは入射角＜屈折角になるため、一定の角度を超えるとすべて跳ね返る「全反射」が起こります。"}, {"id": "demo-space-science", "school": "general", "schoolName": "共通・お試し", "subject": "general", "subjectName": "理科・宇宙", "topic": "基本操作お試し", "title": "基本お試しサンプル（宇宙と科学 2問）", "description": "4択問題と2択（〇×）問題の動作確認ができる定番のお手本ミニセット。", "dataFile": "sample/general/demo/space_science.json", "questionCount": 2, "questionTypes": "4択・〇×", "previewQuestions": [{"type": "4choice", "question": "太陽系の中で、最も大きくて質量が重い惑星は次のうちどれでしょう？"}, {"type": "2choice", "question": "地球から見て、太陽が東からのぼって西へ沈むように見えるのは、地球が「自転」しているからである。"}], "searchText": "基本お試しサンプル（宇宙と科学 2問） 4択問題と2択（〇×）問題の動作確認ができる定番のお手本ミニセット。 共通・お試し 理科・宇宙 基本操作お試し 太陽系の中で、最も大きくて質量が重い惑星は次のうちどれでしょう？ 木星は地球の約1300倍もの体積があり、太陽系最大のガス惑星です！ 地球から見て、太陽が東からのぼって西へ沈むように見えるのは、地球が「自転」しているからである。 大正解！地球が西から東へと1日1回自転しているため、太陽や星が東から西へ動いて見えます。"}]}, "files": {"sample/general/demo/space_science.json": [{"id": "demo-space-science", "school": "general", "schoolName": "共通・お試し", "subject": "general", "subjectName": "理科・宇宙", "topic": "基本操作お試し", "title": "基本お試しサンプル（宇宙と科学 2問）", "description": "4択問題と2択（〇×）問題の動作確認ができる定番のお手本ミニセット。", "questions": [{"id": 1, "type": "4choice", "question": "太陽系の中で、最も大きくて質量が重い惑星は次のうちどれでしょう？", "options": ["火星 (Mars)", "木星 (Jupiter)", "土星 (Saturn)", "金星 (Venus)"], "correct": 2, "timeLimit": 10, "category": "宇宙・天文", "explanation": "木星は地球の約1300倍もの体積があり、太陽系最大のガス惑星です！"}, {"id": 2, "type": "2choice", "question": "地球から見て、太陽が東からのぼって西へ沈むように見えるのは、地球が「自転」しているからである。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 1, "timeLimit": 10, "category": "理科・天文", "explanation": "大正解！地球が西から東へと1日1回自転しているため、太陽や星が東から西へ動いて見えます。"}]}], "sample/junior_high/astronomy/astronomy.json": [{"id": "jh-astro-set1", "school": "jh", "schoolName": "中学校", "subject": "science_astro", "subjectName": "理科（天体）", "topic": "1. 地球の運動と星の動き", "title": "セット1: 地球の自転と日周運動", "description": "地球の自転の向きとスピード（1時間15度）、太陽や星の日周運動、南中高度についての3問。", "questions": [{"id": 1, "type": "4choice", "question": "地球が地軸を中心に1日に1回転する運動を「自転」といいます。北極側から見たとき、地球はどちら向きに自転しているでしょう？", "options": ["時計回り（東から西）", "反時計回り（西から東）", "北から南へ縦回転", "季節によって向きが逆になる"], "correct": 2, "timeLimit": 12, "category": "中学理科・天体", "explanation": "地球は北極の上から見ると「反時計回り（西から東）」に自転しています。だから地球から空を見ると、太陽も星も東からのぼって西へ沈む（1時間に約15度動く）ように見えます！"}, {"id": 2, "type": "4choice", "question": "日本の北の空にある「北極星」を中心に星の日周運動を観察すると、まわりの星は1時間に約何度、どちら向きに回って見えるでしょう？", "options": ["時計回りに約15度", "反時計回りに約15度", "時計回りに約30度", "まったく動かない"], "correct": 2, "timeLimit": 12, "category": "中学理科・天体", "explanation": "北極星は地軸の延長線上にあるためほとんど動かず、北の空の星はそのまわりを「反時計回りに1時間15度（360°÷24h）」回って見えます！（「北の空＝反時計回り」は超重要！）"}, {"id": 3, "type": "2choice", "question": "太陽や星が真南の空の一番高い位置にくることを「南中」といい、南の空を正面に見たとき天体は左（東）から右（西）へ動く。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 1, "timeLimit": 10, "category": "中学理科・天体", "explanation": "正解！南を向くと、左手が「東」、右手が「西」になります。そのため太陽や南の空の星は左から上り、南中を通って右へ沈んでいきます。"}]}, {"id": "jh-astro-set2", "school": "jh", "schoolName": "中学校", "subject": "science_astro", "subjectName": "理科（天体）", "topic": "1. 地球の運動と星の動き", "title": "セット2: 地球の公転と年周運動", "description": "星の年周運動（1か月約30度）、季節の星座（オリオン座・さそり座）が見え変わる理由についての3問。", "questions": [{"id": 1, "type": "4choice", "question": "地球は太陽のまわりを1年で1周（公転）しています。毎日同じ時刻に同じ星を観察すると、1か月（30日）ごとに同じ方向に約何度ずつ位置がずれていくでしょう？", "options": ["約1度", "約15度", "約30度", "約90度"], "correct": 3, "timeLimit": 12, "category": "中学理科・天体", "explanation": "地球は1年（12か月）で360度公転するため、360 ÷ 12 = 1か月あたり約30度（1日あたり約1度）ずつ、星が東から西へ動いて見える「年周運動」が起こります！"}, {"id": 2, "type": "4choice", "question": "夏の夜に南の空に見えていた「さそり座」が、季節が進んで秋や冬になると夜には見えなくなるのはなぜでしょう？", "options": ["さそり座の星自体が地球の裏側へ飛んでいったから", "地球の公転により、地球から見てさそり座が太陽と同じ方向（昼間の空）になったから", "冬の寒さで星の光が消えるから", "月が光をすべてさえぎるから"], "correct": 2, "timeLimit": 12, "category": "中学理科・天体", "explanation": "地球が太陽のまわりを公転するため、季節ごとに「夜の方向（太陽と反対側）」が変わり、夏にはオリオン座は昼の空に、冬には夜の空に見えるようになります。"}, {"id": 3, "type": "2choice", "question": "同じ星座でも、観察する時刻が1か月前より「2時間遅い」時刻であれば、1か月前とほぼ同じ位置に見ることができる。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 2, "timeLimit": 10, "category": "中学理科・天体", "explanation": "ひっかけ問題！星は1か月で西へ30度進みます。日周運動は1時間15度なので、30度分だけ「早く」進むため、同じ位置で見るには「2時間早い」時刻に観察する必要があります！"}]}, {"id": "jh-astro-set3", "school": "jh", "schoolName": "中学校", "subject": "science_astro", "subjectName": "理科（天体）", "topic": "1. 地球の運動と星の動き", "title": "セット3: 地軸の傾きと四季の変化", "description": "地軸の傾き（23.4度）、夏至・冬至の南中高度と昼の長さ、季節ができる本当の理由についての3問。", "questions": [{"id": 1, "type": "4choice", "question": "地球に「四季（春夏秋冬）」の変化が生まれる最も大きな原因は次のうちどれでしょう？", "options": ["夏は地球が太陽にとても近づき、冬はとても遠ざかるから", "地球が公転面に垂直な方向に対して地軸を約23.4度傾けたまま公転しているから", "太陽の燃え方が季節によって変わるから", "月の引力が季節によって変わるから"], "correct": 2, "timeLimit": 12, "category": "中学理科・天体", "explanation": "実は日本（北半球）が冬のほうが地球と太陽の距離は少し近いのです！四季がある理由は「地軸が約23.4度傾いたまま公転しているため、太陽の南中高度と昼の長さが変わるから」です。"}, {"id": 2, "type": "4choice", "question": "日本（北半球）において、1年で「太陽の南中高度が最も高く、昼の長さが最も長い日」を何というでしょう？", "options": ["春分", "夏至", "秋分", "冬至"], "correct": 2, "timeLimit": 12, "category": "中学理科・天体", "explanation": "6月下旬ごろの「夏至」に太陽の南中高度が最高（春分・秋分より＋23.4度）になり、真東より北寄りから日が昇ります。12月下旬の「冬至」は南中高度が最低になります。"}, {"id": 3, "type": "2choice", "question": "「春分」と「秋分」の日には、太陽は真東から昇って真西に沈み、昼の長さと夜の長さがほぼ同じ（約12時間ずつ）になる。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 1, "timeLimit": 10, "category": "中学理科・天体", "explanation": "正解！春分・秋分の日は北緯L度の地点での太陽の南中高度が「90° － 緯度」でぴったり計算できます（例：北緯35度なら 90 - 35 = 55度）。"}]}, {"id": "jh-astro-set4", "school": "jh", "schoolName": "中学校", "subject": "science_astro", "subjectName": "理科（天体）", "topic": "2. 月・金星と日食・月食", "title": "セット4: 月の満ち欠けのしくみ", "description": "新月・上弦・満月・下弦の位置関係、夕方と明け方の月の見え方についての3問。", "questions": [{"id": 1, "type": "4choice", "question": "月が満ち欠けして見える（新月→上弦の月→満月→下弦の月）のはなぜでしょう？", "options": ["月が地球の影に入って隠れるから", "月が自分で出す光の量が増減するから", "太陽の光が当たって光る月の「地球から見える部分」の割合が公転で変わるから", "雲が月の半分を隠しているから"], "correct": 3, "timeLimit": 12, "category": "中学理科・天体", "explanation": "月は自ら光らず太陽の光を反射しています。約29.5日周期で月が地球のまわりを公転するため、太陽・地球・月の位置関係が変わり、地球から見える光る面が変化します。（※地球の影に入るのは月食！）"}, {"id": 2, "type": "4choice", "question": "夕方（午後6時ごろ）に真南の空に見える、右側（西側）が半分光っている月を何というでしょう？", "options": ["新月", "上弦の月", "満月", "下弦の月"], "correct": 2, "timeLimit": 12, "category": "中学理科・天体", "explanation": "夕方の南の空に半月が見えたら「上弦の月」（右半分が光り、その後西の空へ沈む）、逆に明け方の南の空に見える半月が「下弦の月」です！"}, {"id": 3, "type": "2choice", "question": "満月は太陽と地球を挟んで反対側にあるため、夕方ごろ東の空から昇り、真夜中に南中して、明け方に西の空へ沈む。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 1, "timeLimit": 10, "category": "中学理科・天体", "explanation": "正解！太陽と反対方向にあるため、太陽が西に沈む夕方に東から上り、一晩中夜空を照らします。"}]}, {"id": "jh-astro-set5", "school": "jh", "schoolName": "中学校", "subject": "science_astro", "subjectName": "理科（天体）", "topic": "2. 月・金星と日食・月食", "title": "セット5: 金星の見え方（明けの明星・よいの明星）", "description": "内惑星・金星が真夜中に見えない理由、大きさと満ち欠けの変化についての3問。", "questions": [{"id": 1, "type": "4choice", "question": "太陽系の惑星である「金星」が、真夜中（午前0時ごろ）の空に絶対に見ることができない理由は何でしょう？", "options": ["真夜中は金星が裏返って真っ黒になるから", "金星は地球より内側を公転しているため、太陽から大きく離れた方向（真夜中の空）には見えないから", "金星は1日で消滅してしまうから", "地球の重力で見えなくしているから"], "correct": 2, "timeLimit": 12, "category": "中学理科・天体", "explanation": "水星と金星は地球の公転軌道より内側にある「内惑星」なので、地球からは常に太陽に近い方向にしか見えません。そのため「夕方（西の空＝よいの明星）」か「明け方（東の空＝明けの明星）」だけ見られます！"}, {"id": 2, "type": "4choice", "question": "金星を天体望遠鏡で続けて観察すると、三日月のように大きく欠けた形に見えるときと、丸く満ちた形に見えるときで、見かけの大きさはどう変わるでしょう？", "options": ["丸く見えるときが大きく、欠けているときは小さい", "欠けているとき（三日月形）のほうが地球に近く、見かけの大きさが大きく見える", "いつ見ても大きさはまったく同じ", "金星は満ち欠けしない"], "correct": 2, "timeLimit": 12, "category": "中学理科・天体", "explanation": "金星が地球に近い位置にきたときは大きく（でも太陽が向こう側なので大きく欠けた三日月形に）見え、太陽の向こう側にあるときは丸く小さく見えます。これは天動説を覆す大きな証拠になりました！"}, {"id": 3, "type": "2choice", "question": "夕方、太陽が沈んだ直後の「西の空」にひときわ明るく輝いて見える金星を「よいの明星」という。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 1, "timeLimit": 10, "category": "中学理科・天体", "explanation": "正解！日没後の西の空に見えるのが「よいの明星」、日の出前の東の空に見えるのが「明けの明星」です。"}]}, {"id": "jh-astro-set6", "school": "jh", "schoolName": "中学校", "subject": "science_astro", "subjectName": "理科（天体）", "topic": "2. 月・金星と日食・月食", "title": "セット6: 日食と月食のしくみ", "description": "皆既日食・金環日食・皆既月食が起こるときの太陽・地球・月の並び方についての3問。", "questions": [{"id": 1, "type": "4choice", "question": "「日食」が起こるとき、太陽・月・地球の3つの天体は一直線上にどの順番で並んでいるでしょう？", "options": ["太陽 － 地球 － 月", "太陽 － 月 － 地球", "月 － 太陽 － 地球", "いつも直角に並んでいる"], "correct": 2, "timeLimit": 12, "category": "中学理科・天体", "explanation": "「日食」は、太陽と地球の間に「月」が入り、月の影が地球に落ちて太陽が隠れて見える現象です。つまり必ず「新月」のときに起こります！"}, {"id": 2, "type": "4choice", "question": "皆既月食のときに月が真っ暗になって消えるのではなく、赤銅色（赤黒い色）にうっすら光って見えるのはなぜでしょう？", "options": ["月が自分で赤いマグマを出しているから", "地球の大気を通過して屈折した太陽の「赤い光」だけが月面に届くから", "火星の赤い光が月を照らしているから", "人間の目の錯覚だから"], "correct": 2, "timeLimit": 12, "category": "中学理科・天体", "explanation": "夕焼けが赤く見えるのと同じ原理で、地球の大気を通り抜けた長波長の赤い太陽光がわずかに屈折して地球の影の中に入り、皆既月食の月を赤銅色に照らします。"}, {"id": 3, "type": "2choice", "question": "「月食」は地球が太陽と月の間に入り、地球の影の中に月が入ることで起こるため、必ず「満月」のときに起こる。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 1, "timeLimit": 10, "category": "中学理科・天体", "explanation": "正解！月の公転面が地球の公転面に対して約5度傾いているため、毎回の新月・満月ではなく、並びがぴったり重なったときだけ日食や月食が見られます。"}]}, {"id": "jh-astro-set7", "school": "jh", "schoolName": "中学校", "subject": "science_astro", "subjectName": "理科（天体）", "topic": "3. 太陽・太陽系と宇宙", "title": "セット7: 太陽の特徴と表面の現象", "description": "太陽の黒点・コロナ・プロミネンス、黒点の移動からわかる太陽の自転についての3問。", "questions": [{"id": 1, "type": "4choice", "question": "太陽の表面に見られる黒いしみのような「黒点」が、まわりより黒く見える本当の理由は何でしょう？", "options": ["そこだけ穴が空いて真っ暗な宇宙が見えているから", "黒点の温度（約4000℃）が、まわりの光球（約6000℃）より低いため暗く見える", "大きな岩石が太陽にくっついているから", "月に隠れた影だから"], "correct": 2, "timeLimit": 12, "category": "中学理科・天体", "explanation": "黒点も実は約4000℃もあり猛烈に輝いていますが、まわりが約6000℃とさらに明るいため、光のコントラストで相対的に黒く見えています！"}, {"id": 2, "type": "4choice", "question": "天体望遠鏡に投影板を取り付けて太陽の黒点を数日間観察し続けると、黒点が東から西へ移動し、端にくると細長くなります。このことから何がわかるでしょう？", "options": ["太陽は四角い形をしていること", "太陽は「球形」をしており、自ら「自転」していること", "黒点は太陽のまわりを回る衛星であること", "地球が太陽の中心にあること"], "correct": 2, "timeLimit": 12, "category": "中学理科・天体", "explanation": "黒点が同じ向きに移動し、縁に近づくにつれて細長い楕円に見えることは、太陽が「球体」で「自転している（約25〜30日で1回転）」証拠です！"}, {"id": 3, "type": "2choice", "question": "皆既日食のときなどに太陽のまわりに見える、数百万度もの高温の希薄なガスの層を「コロナ」という。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 1, "timeLimit": 10, "category": "中学理科・天体", "explanation": "正解！太陽の縁から炎のように吹き上がるガスの柱は「プロミネンス（紅炎）」、外側を取り巻く真珠色の輝きが「コロナ」です。"}]}, {"id": "jh-astro-set8", "school": "jh", "schoolName": "中学校", "subject": "science_astro", "subjectName": "理科（天体）", "topic": "3. 太陽・太陽系と宇宙", "title": "セット8: 太陽系の8つの惑星", "description": "水星〜海王星までの太陽系の並び順、小惑星帯、彗星（すいせい）についての3問。", "questions": [{"id": 1, "type": "4choice", "question": "太陽に近い順から「水・金・地・火・木・土・（　）・（　）」と並ぶ太陽系の8つの惑星。最後の2つはどれでしょう？", "options": ["冥王星 と 小惑星", "天王星 と 海王星", "海王星 と 冥王星", "土星 と 冥王星"], "correct": 2, "timeLimit": 12, "category": "中学理科・天体", "explanation": "「水金地火木土天海（すいきんちかもくどってんかい）」の8惑星です！冥王星は2006年に「準惑星」に分類が変更されました。"}, {"id": 2, "type": "4choice", "question": "太陽系の中で最も大きく、しま模様と「大赤斑」と呼ばれる巨大な渦巻きをもつ惑星はどれでしょう？", "options": ["土星", "木星", "火星", "天王星"], "correct": 2, "timeLimit": 12, "category": "中学理科・天体", "explanation": "太陽系最大の惑星「木星」は、地球が約1,300個も入るほどの大きさがあります。美しい氷と岩石の輪で有名なのが「土星」です。"}, {"id": 3, "type": "2choice", "question": "火星と木星の間には「小惑星」と呼ばれる小さな天体が多数集まっており、日本の探査機「はやぶさ」や「はやぶさ2」は小惑星から砂や石を持ち帰った。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 1, "timeLimit": 10, "category": "中学理科・天体", "explanation": "正解！「はやぶさ」が小惑星イトカワ、「はやぶさ2」が小惑星リュウグウの試料を持ち帰るという世界的な快挙を成し遂げました！"}]}, {"id": "jh-astro-set9", "school": "jh", "schoolName": "中学校", "subject": "science_astro", "subjectName": "理科（天体）", "topic": "3. 太陽・太陽系と宇宙", "title": "セット9: 地球型惑星と木星型惑星", "description": "岩石中心の地球型惑星とガス・氷中心の木星型惑星の特徴比較についての3問。", "questions": [{"id": 1, "type": "4choice", "question": "「水星・金星・地球・火星」の4つの『地球型惑星』の特徴として正しいものはどれでしょう？", "options": ["体積が非常に大きく、ほとんどがガスでできている", "主に岩石や金属でできていて、大きさは小さいが「密度が大きい」", "衛星（月のような天体）をそれぞれ数十個以上持っている", "すべて美しい大きな氷の輪を持っている"], "correct": 2, "timeLimit": 12, "category": "中学理科・天体", "explanation": "地球型惑星は小さくても岩石・鉄などの重い物質でできているため「密度が大きい」のが特徴。逆に木星・土星などの「木星型惑星」は巨大ですがガス中心のため「密度が小さい」です（土星は水より軽い密度！）。"}, {"id": 2, "type": "4choice", "question": "厚い二酸化炭素の大気による強い温室効果のため、表面温度が約460℃もの高温になっている地球型惑星はどれでしょう？", "options": ["水星", "金星", "火星", "地球"], "correct": 2, "timeLimit": 12, "category": "中学理科・天体", "explanation": "一番太陽に近い「水星」よりも、濃い二酸化炭素に覆われた「金星」のほうが昼も夜も約460℃と超高温です。温室効果ガスの威力がよくわかる例です。"}, {"id": 3, "type": "2choice", "question": "「彗星（すいせい・ほうき星）」は氷やちりなどでできており、太陽に近づくと太陽からの風や光に押されて、太陽と「同じ側」に向かって長い尾が伸びる。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 2, "timeLimit": 10, "category": "中学理科・天体", "explanation": "ひっかけ問題！彗星の尾は、太陽から吹き付ける太陽風や光の圧力で押し流されるため、進む向きに関係なく常に「太陽と反対側」に尾が伸びます！"}]}, {"id": "jh-astro-set10", "school": "jh", "schoolName": "中学校", "subject": "science_astro", "subjectName": "理科（天体）", "topic": "3. 太陽・太陽系と宇宙", "title": "セット10: 恒星・銀河系と宇宙の広がり", "description": "恒星と惑星の違い、光年、天の川と銀河系についての3問。", "questions": [{"id": 1, "type": "4choice", "question": "夜空に輝く「天の川（あまのがわ）」の正体として正しいものはどれでしょう？", "options": ["宇宙に浮かぶ大量の氷の粒の帯", "地球が属している約2,000億個以上の星の大集団「銀河系」を横から見た姿", "太陽系のすぐ外側にある土星の輪の延長", "人工衛星の光が連なったもの"], "correct": 2, "timeLimit": 12, "category": "中学理科・天体", "explanation": "太陽系は直径約10万光年の円盤状の「銀河系（天の川銀河）」の端のほうに位置しています。地球から円盤の内側方向を見ると星が密集して帯のように見えるのが「天の川」です！"}, {"id": 2, "type": "4choice", "question": "宇宙の遠い距離を表す単位「1光年」とは、何の距離を表しているでしょう？", "options": ["宇宙ロケットが1年間に進む距離", "光（秒速約30万km）が1年間に進む距離（約9兆4,600億km）", "地球が1年間に太陽のまわりを公転する距離", "1年間にかかる時間の単位"], "correct": 2, "timeLimit": 12, "category": "中学理科・天体", "explanation": "「光年」は時間ではなく「距離」の単位です！1秒間に地球を7周半する速さの光が1年かけて進む距離が1光年。太陽の次に近い恒星まででも約4.2光年かかります。"}, {"id": 3, "type": "2choice", "question": "太陽や北極星・ベガのように、自ら光と熱を出して輝いている天体を「恒星（こうせい）」という。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 1, "timeLimit": 10, "category": "中学理科・天体", "explanation": "正解！星座を形づくる星のほとんどは太陽と同じ「恒星」です。自ら光らない「惑星（地球や木星など）」とは区別しましょう。"}]}], "sample/junior_high/biology/biology.json": [{"id": "jh-bio-set1", "school": "jh", "schoolName": "中学校", "subject": "science_bio", "subjectName": "理科（生物）", "topic": "1. 植物・動物のなかま", "title": "セット1: 顕微鏡の使い方と身近な微生物", "description": "顕微鏡の正しい手順、プレパラート作り、ミジンコやアオミドロなどの微生物についての3問。", "questions": [{"id": 1, "type": "4choice", "question": "顕微鏡でプレパラートのピントを合わせるとき、対物レンズを傷つけないための正しい操作順序はどれでしょう？", "options": ["接眼レンズをのぞきながら、対物レンズをプレパラートに近づける", "横から見ながら対物レンズをぎりぎりまで近づけ、のぞきながら遠ざけて合わせる", "高倍率から始めて、低倍率に変える", "反射鏡を使う前に、いきなり100倍で観察する"], "correct": 2, "timeLimit": 12, "category": "中学理科・生物", "explanation": "接眼レンズをのぞいたまま対物レンズを下げると、スライドガラスにぶつけて割ってしまう危険があります。必ず「横から見ながら近づけ、のぞきながら遠ざけて」ピントを合わせます！"}, {"id": 2, "type": "4choice", "question": "池の水にいる微生物のうち、葉緑体をもち、光合成をして自分で栄養をつくる植物のなかまはどれでしょう？", "options": ["ゾウリムシ", "ミジンコ", "アメーバ", "アオミドロ（またはミカヅキモ）"], "correct": 4, "timeLimit": 12, "category": "中学理科・生物", "explanation": "アオミドロやミカヅキモは緑色の葉緑体をもっていて、日光が当たると光合成を行います。ゾウリムシやミジンコは動いて食べ物をとる動物性の微生物です。"}, {"id": 3, "type": "2choice", "question": "顕微鏡の倍率を「低倍率」から「高倍率」に変えると、見える範囲（視野）はせまくなり、明るさは暗くなる。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 1, "timeLimit": 10, "category": "中学理科・生物", "explanation": "正解！倍率が上がると細かい部分が大きく見える代わりに、視野は狭く暗くなるため、しぼりで明るさを調節します。必ず最初に低倍率で見つけてから高倍率にします。"}]}, {"id": "jh-bio-set2", "school": "jh", "schoolName": "中学校", "subject": "science_bio", "subjectName": "理科（生物）", "topic": "1. 植物・動物のなかま", "title": "セット2: 植物のつくりと光合成・蒸散", "description": "葉緑体での光合成とデンプン、気孔と蒸散、道管・師管の働きについての3問。", "questions": [{"id": 1, "type": "4choice", "question": "植物が光のエネルギーを使って、二酸化炭素と水から栄養分（デンプンなど）と酸素をつくる働きを何というでしょう？", "options": ["呼吸", "蒸散", "光合成", "発酵"], "correct": 3, "timeLimit": 12, "category": "中学理科・生物", "explanation": "植物の細胞にある「葉緑体」で行われるのが「光合成」です。光合成でできたデンプンは「ヨウ素液」を加えると青紫色に変化します！"}, {"id": 2, "type": "4choice", "question": "植物の葉の裏側などに多く見られる、2つの孔辺細胞に囲まれたすき間で、水蒸気や気体が出入りする穴を何というでしょう？", "options": ["気孔", "道管", "師管", "根毛"], "correct": 1, "timeLimit": 12, "category": "中学理科・生物", "explanation": "「気孔」から水蒸気が出ていく現象を「蒸散」といいます。蒸散は根から水を吸い上げる原動力となり、葉の温度が上がりすぎるのも防ぎます。"}, {"id": 3, "type": "2choice", "question": "植物の茎にある維管束のうち、根から吸い上げた水や肥料分が通る管は「道管」、葉でつくられた栄養分が通る管は「師管」である。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 1, "timeLimit": 10, "category": "中学理科・生物", "explanation": "正解！水の通り道が「道管」、栄養（砂糖などの形に変えて運ばれる）が通るのが「師管」です。2つをまとめて「維管束」といいます。"}]}, {"id": "jh-bio-set3", "school": "jh", "schoolName": "中学校", "subject": "science_bio", "subjectName": "理科（生物）", "topic": "1. 植物・動物のなかま", "title": "セット3: 花のつくりと植物の分類", "description": "被子植物と裸子植物、単子葉類と双子葉類、シダ植物・コケ植物の違いについての3問。", "questions": [{"id": 1, "type": "4choice", "question": "マツやイチョウ、ソテツのように、子房がなく「胚珠」がむき出しになっている種子植物を何というでしょう？", "options": ["被子植物", "裸子植物", "シダ植物", "コケ植物"], "correct": 2, "timeLimit": 12, "category": "中学理科・生物", "explanation": "胚珠が子房に包まれているのが「被子植物（サクラ・アブラナなど）」、むき出しなのが「裸子植物（マツ・イチョウ・スギなど）」です。裸子植物の多くは風で花粉を運びます。"}, {"id": 2, "type": "4choice", "question": "葉脈が「平行脈」、根が「ひげ根」、茎の維管束がバラバラに散らばっている被子植物のなかま（ツユクサ・トウモロコシ・イネ等）はどれでしょう？", "options": ["双子葉類", "単子葉類", "裸子植物", "コケ植物"], "correct": 2, "timeLimit": 12, "category": "中学理科・生物", "explanation": "子葉が1枚の「単子葉類」は「平行脈・ひげ根・維管束は散らばる」が特徴です。一方、子葉が2枚の「双子葉類」は「網状脈・主根と側根・維管束は輪状」です。"}, {"id": 3, "type": "2choice", "question": "イヌワラビなどのシダ植物や、ゼニゴケ・スギゴケなどのコケ植物は、花や種子をつくらず「胞子」によってふえる。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 1, "timeLimit": 10, "category": "中学理科・生物", "explanation": "正解！シダ植物には根・茎・葉の区別と維管束がありますが、コケ植物には根・茎・葉の区別や維管束がなく、体全体から水や養分を吸収します。どちらも「胞子」で増えます。"}]}, {"id": "jh-bio-set4", "school": "jh", "schoolName": "中学校", "subject": "science_bio", "subjectName": "理科（生物）", "topic": "1. 植物・動物のなかま", "title": "セット4: 動物の分類（せきつい・無せきつい）", "description": "背骨の有無、卵生・胎生、恒温動物と変温動物、節足・軟体動物についての3問。", "questions": [{"id": 1, "type": "4choice", "question": "背骨をもつ「せきつい動物」の5つの仲間のうち、まわりの温度が変わっても体温をほぼ一定に保つ「恒温動物」の組み合わせはどれでしょう？", "options": ["魚類 と 両生類", "は虫類 と 鳥類", "鳥類 と ほ乳類", "両生類 と ほ乳類"], "correct": 3, "timeLimit": 12, "category": "中学理科・生物", "explanation": "鳥類とほ乳類は体温を一定に保てる「恒温動物」です。魚類・両生類・は虫類はまわりの温度によって体温が変わる「変温動物」で、冬眠する種も多くいます。"}, {"id": 2, "type": "4choice", "question": "カエルやイモリなどの「両生類」の呼吸のしかたとして正しいものはどれでしょう？", "options": ["一生えら呼吸のみを行う", "子のときはえら呼吸、おとな（成体）になると肺と皮膚で呼吸する", "一生肺呼吸のみを行う", "一生皮膚呼吸のみを行う"], "correct": 2, "timeLimit": 12, "category": "中学理科・生物", "explanation": "オタマジャクシ（子）のときは水中で「えら呼吸」をしますが、おとなのカエルになると「肺呼吸」に加えて湿った皮膚でも「皮膚呼吸」を行うため、水辺から離れられません。"}, {"id": 3, "type": "2choice", "question": "バッタやエビ・カニなどの「節足動物」には背骨がなく、外骨格と呼ばれるかたい殻におおわれていて、脱皮をして成長する。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 1, "timeLimit": 10, "category": "中学理科・生物", "explanation": "正解！背骨のない「無せきつい動物」のうち、体やあしに節があるのが「節足動物」、筋肉でできた「外とう膜」で内臓が包まれているイカ・アサリ・カタツムリなどが「軟体動物」です。"}]}, {"id": "jh-bio-set5", "school": "jh", "schoolName": "中学校", "subject": "science_bio", "subjectName": "理科（生物）", "topic": "2. 人の体のつくりとはたらき", "title": "セット5: 消化と吸収のしくみ", "description": "消化液と消化酵素（アミラーゼ・ペプシン・リパーゼ等）、小腸の柔毛についての3問。", "questions": [{"id": 1, "type": "4choice", "question": "だ液に含まれる消化酵素「アミラーゼ」は、食べ物のどの栄養分を分解するでしょう？", "options": ["タンパク質", "デンプン", "脂肪", "ビタミン"], "correct": 2, "timeLimit": 12, "category": "中学理科・生物", "explanation": "ご飯（デンプン）をよくかむと甘くなるのは、だ液中の「アミラーゼ」がデンプンを麦芽糖などの糖に分解するためです！ベネジクト液と加熱すると赤褐色になります。"}, {"id": 2, "type": "4choice", "question": "肝臓でつくられ、胆のうにためられる「胆汁」には消化酵素が含まれていませんが、どの栄養分の消化を助ける働きがあるでしょう？", "options": ["デンプン", "タンパク質", "脂肪（水を混ぜやすくして粒を細かくする）", "無機塩類"], "correct": 3, "timeLimit": 12, "category": "中学理科・生物", "explanation": "胆汁は消化酵素を持ちませんが、脂肪を小さな粒に散らして（乳化して）、すい液の消化酵素リパーゼが働きやすくする大切な役割があります！"}, {"id": 3, "type": "2choice", "question": "小腸の内側の壁には「柔毛（じゅうもう）」と呼ばれる無数の小さな突起があり、表面積を非常に大きくして栄養分を効率よく吸収している。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 1, "timeLimit": 10, "category": "中学理科・生物", "explanation": "正解！ブドウ糖とアミノ酸は柔毛内の「毛細血管」へ、脂肪酸とモノグリセリドは再合成されたあと「リンパ管」へ吸収されて全身へ運ばれます。"}]}, {"id": "jh-bio-set6", "school": "jh", "schoolName": "中学校", "subject": "science_bio", "subjectName": "理科（生物）", "topic": "2. 人の体のつくりとはたらき", "title": "セット6: 呼吸と血液の循環", "description": "肺胞でのガス交換、血液の4つの成分、心臓と動脈・静脈の違いについての3問。", "questions": [{"id": 1, "type": "4choice", "question": "血液の4つの成分のうち、酸素を全身の細胞へ運ぶ役割をする「ヘモグロビン」を含む成分はどれでしょう？", "options": ["白血球", "赤血球", "血小板", "血しょう"], "correct": 2, "timeLimit": 12, "category": "中学理科・生物", "explanation": "赤血球（酸素を運ぶ）、白血球（細菌などを退治する）、血小板（出血を止めて血を固める）、血しょう（養分や二酸化炭素などを溶かして運ぶ液体）の4成分をしっかり区別しましょう！"}, {"id": 2, "type": "4choice", "question": "血管を分類するとき、「心臓から送り出される血液が流れる血管」と「酸素を多く含む血液」をそれぞれ何というでしょう？", "options": ["静脈 と 静脈血", "動脈 と 動脈血", "動脈 と 静脈血", "毛細血管 と リンパ管"], "correct": 2, "timeLimit": 12, "category": "中学理科・生物", "explanation": "「動脈（＝心臓から出ていく血管）」「静脈（＝心臓に戻る血管）」という構造の名前と、「動脈血（＝酸素が多い血）」「静脈血（＝二酸化炭素が多い血）」という血液の性質を区別します！（※肺動脈には静脈血が流れます！）"}, {"id": 3, "type": "2choice", "question": "肺の先にある無数の小さな袋「肺胞（はいほう）」では、毛細血管との間で酸素を取り入れ、二酸化炭素を放出するガス交換が行われている。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 1, "timeLimit": 10, "category": "中学理科・生物", "explanation": "正解！肺胞も小腸の柔毛と同じく、小さな袋が大量に集まることで空気と触れ合う表面積を極限まで大きくし、効率よくガス交換をしています。"}]}, {"id": "jh-bio-set7", "school": "jh", "schoolName": "中学校", "subject": "science_bio", "subjectName": "理科（生物）", "topic": "2. 人の体のつくりとはたらき", "title": "セット7: 感覚器官・神経と反射・運動", "description": "目や耳のつくり、脳と脊髄（中枢神経）、意識とは無関係に起こる「反射」についての3問。", "questions": [{"id": 1, "type": "4choice", "question": "熱いヤカンにうっかり触れたとき、大脳で考えるより先に、せきずいから直接命令が出て思わず手を引っ込める反応を何というでしょう？", "options": ["条件反射", "反射", "細胞呼吸", "自律運動"], "correct": 2, "timeLimit": 12, "category": "中学理科・生物", "explanation": "刺激を受けてから大脳を通らずにせきずいなどから即座に反応が返る「反射」は、危険から自分の体を素早く守る大切な仕組みです。暗い場所でひとみ（瞳孔）が広がるのも反射です。"}, {"id": 2, "type": "4choice", "question": "人間の目のつくりで、カメラのレンズのように厚みを変えてピントを合わせる部分と、光の刺激を受け取る奥の膜の名称の組み合わせはどれでしょう？", "options": ["虹彩 と 角膜", "水晶体（レンズ） と 網膜", "鼓膜 と うずまき管", "ガラス体 と 視神経"], "correct": 2, "timeLimit": 12, "category": "中学理科・生物", "explanation": "目に入った光は「水晶体（レンズ）」で屈折し、奥の「網膜」に像を結びます。その信号が「視神経」を通って脳へ伝わり、見えたと感じます。"}, {"id": 3, "type": "2choice", "question": "腕を曲げるとき、筋肉は骨と「けん」でつながっており、筋肉が「縮む」力だけで骨を引っぱって動かしている。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 1, "timeLimit": 10, "category": "中学理科・生物", "explanation": "正解！筋肉は自ら「縮む」ことしかできないため、関節を挟んで表側と裏側の2つの筋肉がペアになり、一方が縮むともう一方がゆるんで曲げ伸ばしをしています。"}]}, {"id": "jh-bio-set8", "school": "jh", "schoolName": "中学校", "subject": "science_bio", "subjectName": "理科（生物）", "topic": "3. 細胞・遺伝と自然界のつながり", "title": "セット8: 細胞のつくりと細胞分裂", "description": "動物細胞と植物細胞の共通点と違い、体細胞分裂の過程と染色体の観察についての3問。", "questions": [{"id": 1, "type": "4choice", "question": "植物の細胞にはあるが、動物の細胞には「ない」つくりの組み合わせとして正しいものはどれでしょう？", "options": ["核・細胞膜・細胞質", "細胞壁・葉緑体・（発達した）液胞", "ミトコンドリア・核・細胞壁", "細胞膜・葉緑体・核"], "correct": 2, "timeLimit": 12, "category": "中学理科・生物", "explanation": "核・細胞膜・細胞質は動物・植物の両方に共通です。植物細胞には、体を支える頑丈な「細胞壁」、光合成をする「葉緑体」、水分等を貯める大きな「液胞」があります！"}, {"id": 2, "type": "4choice", "question": "タマネギの根の先端など、成長が盛んな部分で観察できる「体細胞分裂」では、分裂する前の核の中にある「染色体」の数は分裂後にどうなるでしょう？", "options": ["半分に減る", "分裂前に2倍に複製されるため、分裂後も同じ数になる", "2倍に増えたままになる", "消えてなくなる"], "correct": 2, "timeLimit": 12, "category": "中学理科・生物", "explanation": "体細胞分裂では、核の中の染色体がコピーされて同じものが2つの細胞に分かれるため、できた新しい細胞も元の細胞とまったく同じ染色体数・遺伝情報を受け継ぎます。"}, {"id": 3, "type": "2choice", "question": "植物の根が伸びるとき、根の先端近くの小さな細胞が分裂して数を増やしたあと、一つ一つの細胞が大きくなることで成長する。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 1, "timeLimit": 10, "category": "中学理科・生物", "explanation": "正解！生物の成長は、細胞分裂によって「細胞の数が増える」ことと、その後それぞれの「細胞が大きくなる」ことの2段階で進みます。"}]}, {"id": "jh-bio-set9", "school": "jh", "schoolName": "中学校", "subject": "science_bio", "subjectName": "理科（生物）", "topic": "3. 細胞・遺伝と自然界のつながり", "title": "セット9: 生殖と遺伝の規則性", "description": "無性生殖と有性生殖、減数分裂、メンデルの実験（顕性・潜性形質と分離の法則）についての3問。", "questions": [{"id": 1, "type": "4choice", "question": "ジャガイモの栄養生殖やゾウリムシの分裂のように、受精を行わず1つの親から同じ遺伝子を受け継ぐ子がふえる増え方を何というでしょう？", "options": ["有性生殖", "無性生殖", "減数分裂", "受精"], "correct": 2, "timeLimit": 12, "category": "中学理科・生物", "explanation": "無性生殖では親のコピー（クローン）ができるため、形質は親とまったく同じになります。一方、雌雄の生殖細胞が受精する有性生殖では、両親の遺伝子が組み合わさり多様な子が生まれます。"}, {"id": 2, "type": "4choice", "question": "エンドウの丸い種子（AA）としわの種子（aa）をかけ合わせてできた子（Aa）はすべて丸くなりました。このとき「丸」のように子に現れやすい形質を何というでしょう？", "options": ["潜性形質（以前の劣性形質）", "顕性形質（以前の優性形質）", "突然変異", "クローン"], "correct": 2, "timeLimit": 12, "category": "中学理科・生物", "explanation": "対になる遺伝子（Aとa）が揃ったときに表に現れる形質を「顕性（けんせい）形質」、隠れて現れない形質を「潜性（せんせい）形質」といいます（2017年頃から名称が整理されました）。"}, {"id": 3, "type": "2choice", "question": "卵や精子などの生殖細胞がつくられるときには、染色体の数が半分になる特別な細胞分裂「減数分裂」が行われる。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 1, "timeLimit": 10, "category": "中学理科・生物", "explanation": "正解！減数分裂で染色体が半分（n）になるからこそ、受精によって卵と精子が合体したときに再び元の数（2n）に戻り、世代を超えて染色体の数が一定に保たれます！"}]}, {"id": "jh-bio-set10", "school": "jh", "schoolName": "中学校", "subject": "science_bio", "subjectName": "理科（生物）", "topic": "3. 細胞・遺伝と自然界のつながり", "title": "セット10: 生態系と自然界のつながり", "description": "生産者・消費者・分解者（菌類・細菌類）、食物連鎖のピラミッド、炭素と酸素の循環についての3問。", "questions": [{"id": 1, "type": "4choice", "question": "生態系の中で、動物の死がいやフン・落ち葉などの有機物を二酸化炭素や水・無機物へと分解し、自然の物質循環に欠かせない働きをするのはどれでしょう？", "options": ["生産者（緑色植物）", "草食動物", "菌類（カビ・キノコ）や細菌類などの「分解者」", "肉食動物"], "correct": 3, "timeLimit": 12, "category": "中学理科・生物", "explanation": "もし菌類や細菌類などの「分解者」がいなければ、地球上は落ち葉や死がいで埋まり、植物が必要な養分や二酸化炭素が循環しなくなってしまいます！"}, {"id": 2, "type": "4choice", "question": "「草 → ウサギ → キツネ」のような食べる・食べられるのつながりにおいて、通常もっとも個体数（生物の量）が多いのはどの段階でしょう？", "options": ["上位の肉食動物（キツネ）", "草食動物（ウサギ）", "生産者（草などの植物）", "すべて全く同じ数"], "correct": 3, "timeLimit": 12, "category": "中学理科・生物", "explanation": "食物連鎖ではピラミッドのように土台となる「生産者（植物）」が最も多く、上にいくほど個体数が少なくなって生態系のつり合いが保たれています。"}, {"id": 3, "type": "2choice", "question": "ある地域で肉食動物が激減して一時的に草食動物が増えすぎても、やがて植物が減ることで草食動物も減少し、もとのつり合いに戻ろうとする働きがある。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 1, "timeLimit": 10, "category": "中学理科・生物", "explanation": "正解！自然界には一時的にバランスが崩れても元に戻ろうとする回復力がありますが、外来種の侵入や過度な開発で急激に変化すると元に戻らなくなる危険があります。"}]}], "sample/junior_high/civics/civics.json": [{"id": "jh-civics-set1", "school": "jh", "schoolName": "中学校", "subject": "social_civics", "subjectName": "社会（公民）", "topic": "1. 人権と日本国憲法", "title": "セット1: 現代社会と少子高齢化・情報化", "description": "少子高齢化、グローバル化、情報リテラシーとルールについての3問。", "questions": [{"id": 1, "type": "4choice", "question": "日本の人口において、65歳以上の割合が高くなり子どもの割合が減っていく社会の変化を何というでしょう？", "options": ["人口爆発", "少子高齢化", "核家族化", "都市化"], "correct": 2, "timeLimit": 12, "category": "中学社会・公民", "explanation": "日本は世界でもトップクラスの長寿国となり、65歳以上の割合が29％を超える「超高齢社会」と、出生数の減少による「少子化」が同時に進んでいます。"}, {"id": 2, "type": "4choice", "question": "インターネットやSNSから得られるたくさんの情報の中から、正しい情報を見極めて適切に使いこなす能力を何というでしょう？", "options": ["情報リテラシー（メディア・リテラシー）", "ユニバーサルデザイン", "バリアフリー", "プライバシー権"], "correct": 1, "timeLimit": 12, "category": "中学社会・公民", "explanation": "フェイクニュースや誤情報に惑わされないよう、情報の根拠を確かめ多角的に判断する力「メディア・リテラシー（情報活用能力）」が現代社会ではとても重要です。"}, {"id": 3, "type": "2choice", "question": "年齢や障害の有無、言語のちがいなどにかかわらず、最初からすべての人にとって使いやすいように設計することを「ユニバーサルデザイン」という。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 1, "timeLimit": 10, "category": "中学社会・公民", "explanation": "正解！シャンプーボトルのきざみや、ピクトグラム、ノンステップバスなどが代表例です。障害物を取り除く「バリアフリー」から一歩進んだ考え方です。"}]}, {"id": "jh-civics-set2", "school": "jh", "schoolName": "中学校", "subject": "social_civics", "subjectName": "社会（公民）", "topic": "1. 人権と日本国憲法", "title": "セット2: 日本国憲法の三大原則と平和主義", "description": "国民主権・基本的人権の尊重・平和主義、立憲主義と憲法改正の手続きについての3問。", "questions": [{"id": 1, "type": "4choice", "question": "日本国憲法第9条に定められており、戦争の放棄・戦力の不保持・交戦権の否認をうたっている三大原則の一つは何でしょう？", "options": ["国民主権", "基本的人権の尊重", "平和主義", "地方自治"], "correct": 3, "timeLimit": 12, "category": "中学社会・公民", "explanation": "日本国憲法の三大原則は「国民主権」「基本的人権の尊重」「平和主義」です。第9条では戦争を二度とくり返さない決意として平和主義が定められています。"}, {"id": 2, "type": "4choice", "question": "日本国憲法を改正する場合、衆議院と参議院それぞれの総議員のどれだけの賛成で「発議」し、その後国民投票を行う必要があるでしょう？", "options": ["過半数（2分の1以上）", "3分の2以上", "4分の3以上", "全員一致"], "correct": 2, "timeLimit": 12, "category": "中学社会・公民", "explanation": "憲法は国の最高法規であり簡単に変えられないよう、衆参各議院の「総議員の3分の2以上」の賛成で国会が発議し、さらに「国民投票の過半数の賛成」が必要です（第96条）。"}, {"id": 3, "type": "2choice", "question": "日本国憲法において、天皇は国の「元首（政治の実権を持つトップ）」と定められている。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 2, "timeLimit": 10, "category": "中学社会・公民", "explanation": "ひっかけ問題！日本国憲法第1条では、天皇は「日本国の象徴であり日本国民統合の象徴」と定められており、内閣の助言と承認により「国事行為」を行いますが、政治に関する権能は持ちません。"}]}, {"id": "jh-civics-set3", "school": "jh", "schoolName": "中学校", "subject": "social_civics", "subjectName": "社会（公民）", "topic": "1. 人権と日本国憲法", "title": "セット3: 基本的人権の尊重と新しい人権", "description": "自由権・平等権・社会権・参政権、新しい人権（知る権利・プライバシー権）についての3問。", "questions": [{"id": 1, "type": "4choice", "question": "憲法第25条の「すべて国民は、健康で文化的な最低限度の生活を営む権利を有する」は、どの人権を定めたものでしょう？", "options": ["自由権", "生存権（社会権）", "参政権", "請求権"], "correct": 2, "timeLimit": 12, "category": "中学社会・公民", "explanation": "国に人間らしい生活の保障を求めることができる「生存権」は「社会権」の中心です。教育を受ける権利（第26条）や勤労の権利（第27条）も社会権に含まれます。"}, {"id": 2, "type": "4choice", "question": "時代の変化に伴い主張されるようになった「新しい人権」のうち、自分に関する個人情報をみだりに他人に知られない権利を何というでしょう？", "options": ["環境権", "知る権利", "プライバシーの権利", "黙秘権"], "correct": 3, "timeLimit": 12, "category": "中学社会・公民", "explanation": "SNSやデジタル化が進んだ現代では、個人の情報や私生活を保護する「プライバシーの権利」や、行政に情報を公開させる「知る権利」などが重視されています。"}, {"id": 3, "type": "2choice", "question": "基本的人権は「侵すことのできない永久の権利」であるが、他人の人権を守るためなどの理由から「公共の福祉」による一定の制限を受けることがある。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 1, "timeLimit": 10, "category": "中学社会・公民", "explanation": "正解！自分の権利や自由を主張するときも、他の人の人権を傷つけてはいけません。お互いの人権を調整する基準を「公共の福祉」といいます。"}]}, {"id": "jh-civics-set4", "school": "jh", "schoolName": "中学校", "subject": "social_civics", "subjectName": "社会（公民）", "topic": "2. 政治のしくみと地方自治", "title": "セット4: 国会と内閣のしくみ", "description": "国権の最高機関（二院制）、議院内閣制、予算と法律の議決についての3問。", "questions": [{"id": 1, "type": "4choice", "question": "日本の国会は「衆議院」と「参議院」からなる二院制です。任期が4年で解散があり、「衆議院の優越」が認められている理由はなぜでしょう？", "options": ["衆議院議員のほうが年齢が高いから", "解散があり任期が短く、より最新の国民の意思を反映しているから", "参議院は法律を作れないから", "総理大臣が衆議院だけを選ぶから"], "correct": 2, "timeLimit": 12, "category": "中学社会・公民", "explanation": "衆議院は任期4年・解散ありで最新の民意が反映されやすいため、法律案・予算・条約・内閣総理大臣の指名などで「衆議院の優越」が認められています。"}, {"id": 2, "type": "4choice", "question": "内閣が国会の信任に基づいて成り立ち、国会に対して連帯して責任を負う政治の仕組みを何というでしょう？", "options": ["大統領制", "議院内閣制", "直接民主制", "一院制"], "correct": 2, "timeLimit": 12, "category": "中学社会・公民", "explanation": "日本は「議院内閣制」を採用しており、内閣総理大臣は国会議員の中から国会で指名され、国務大臣の過半数も国会議員から選ばれます。"}, {"id": 3, "type": "2choice", "question": "衆議院で可決された「予算案」が参議院で否決され、両院協議会でも意見がまとまらない場合でも、最終的には衆議院の議決が国会の議決となる。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 1, "timeLimit": 10, "category": "中学社会・公民", "explanation": "正解！予算の議決、条約の承認、内閣総理大臣の指名では、両院協議会を経ても一致しないとき、または一定期間議決しないときは衆議院の議決が国会の議決になります。"}]}, {"id": "jh-civics-set5", "school": "jh", "schoolName": "中学校", "subject": "social_civics", "subjectName": "社会（公民）", "topic": "2. 政治のしくみと地方自治", "title": "セット5: 裁判所と三権分立・裁判員制度", "description": "三権分立の抑制と均衡、三審制と違憲審査権、裁判員制度についての3問。", "questions": [{"id": 1, "type": "4choice", "question": "最高裁判所が持つ、国会で作った法律や内閣の命令が憲法に違反していないかを判断する権限を何というでしょう？", "options": ["国政調査権", "違憲審査権（違憲立法審査権）", "予算提出権", "解散権"], "correct": 2, "timeLimit": 12, "category": "中学社会・公民", "explanation": "裁判所（最終的には最高裁判所）は「憲法の番人」とも呼ばれ、法律や行政行為が憲法に違反していないかを審査する「違憲審査権」を持っています。"}, {"id": 2, "type": "4choice", "question": "同じ事件について、不服がある場合に最高3回まで裁判をやり直すことができる「三審制」が採用されている主な理由はどれでしょう？", "options": ["裁判費用を安くするため", "誤った判決を防ぎ、人権を慎重に守るため", "裁判官の仕事を増やすため", "判決まで時間をかけて忘れるため"], "correct": 2, "timeLimit": 12, "category": "中学社会・公民", "explanation": "裁判官も人間であるため、誤判（えん罪など）を絶対に防ぐ目的で、地方裁判所→高等裁判所→最高裁判所へと上訴できる「三審制」がとられています。"}, {"id": 3, "type": "2choice", "question": "重大な刑事事件の第一審の裁判に、選挙権を持つ一般の国民からくじで選ばれた6人が裁判官と参加する仕組みを「裁判員制度」という。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 1, "timeLimit": 10, "category": "中学社会・公民", "explanation": "正解！国民の健全な常識を裁判に反映させ、司法への理解を深めるために2009年から「裁判員制度」が始まりました（裁判官3人＋裁判員6人）。"}]}, {"id": "jh-civics-set6", "school": "jh", "schoolName": "中学校", "subject": "social_civics", "subjectName": "社会（公民）", "topic": "2. 政治のしくみと地方自治", "title": "セット6: 地方自治と選挙・政治参加", "description": "「民主主義の学校」地方自治、直接請求権、18歳選挙権についての3問。", "questions": [{"id": 1, "type": "4choice", "question": "都道府県や市区町村などの地方公共団体が、住民の意思にもとづいて地域の政治を自分たちで治める仕組みを何というでしょう？", "options": ["中央集権", "地方自治", "三権分立", "議院内閣制"], "correct": 2, "timeLimit": 12, "category": "中学社会・公民", "explanation": "「地方自治は民主主義の学校」と呼ばれます。住民が首長（知事・市区町村長）と地方議会議員をどちらも直接選挙で選ぶ「二元代表制」をとっています。"}, {"id": 2, "type": "4choice", "question": "住民が一定数以上の署名を集めることで、条例の制定・改廃や、首長・議員の解職（リコール）などを求めることができる権利を何というでしょう？", "options": ["請願権", "直接請求権", "違憲審査権", "国家賠償請求権"], "correct": 2, "timeLimit": 12, "category": "中学社会・公民", "explanation": "地方自治では、選挙だけでなく、一定数以上の署名を集めて住民の意思を直接政治にぶつける「直接請求権」が認められています。"}, {"id": 3, "type": "2choice", "question": "現在の日本の選挙では、衆議院・参議院および地方選挙の「選挙権（投票できる年齢）」は満18歳以上である。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 1, "timeLimit": 10, "category": "中学社会・公民", "explanation": "正解！2015年の公職選挙法改正により、満20歳以上から「満18歳以上」に引き下げられました。高校3年生のうちから政治に参加できます！"}]}, {"id": "jh-civics-set7", "school": "jh", "schoolName": "中学校", "subject": "social_civics", "subjectName": "社会（公民）", "topic": "3. 経済・くらしと国際社会", "title": "セット7: 消費生活と市場経済のしくみ", "description": "需要量と供給量・均衡価格、独占禁止法、クーリング・オフ制度についての3問。", "questions": [{"id": 1, "type": "4choice", "question": "市場において、「買いたい量（需要量）」と「売りたい量（供給量）」が一致したときに決まる価格を何というでしょう？", "options": ["公共料金", "均衡価格", "独占価格", "最低賃金"], "correct": 2, "timeLimit": 12, "category": "中学社会・公民", "explanation": "需要と供給のバランスによって自然に決まる価格を「均衡価格（市場価格）」といいます。品不足（需要＞供給）になると価格が上がり、余ると価格が下がります。"}, {"id": 2, "type": "4choice", "question": "訪問販売や電話勧誘などで契約してしまった場合でも、一定の期間内（例：8日間）であれば無条件で契約を取り消せる消費者保護制度は何でしょう？", "options": ["リコール制度", "クーリング・オフ制度", "PL法（製造物責任法）", "トレードオフ"], "correct": 2, "timeLimit": 12, "category": "中学社会・公民", "explanation": "「頭を冷やして考え直す」という意味の「クーリング・オフ制度」です。ただし店舗に出向いて買った場合や、自ら通信販売サイトで注文した場合などは原則対象外なので注意しましょう！"}, {"id": 3, "type": "2choice", "question": "大企業同士が話し合って勝手に商品の値段をつり上げる「カルテル」などを禁止し、公正で自由な競争を守る法律を「独占禁止法」という。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 1, "timeLimit": 10, "category": "中学社会・公民", "explanation": "正解！公正取引委員会が監視役となり、独占禁止法にもとづいて消費者が不利益を被らないよう自由な競争環境を守っています。"}]}, {"id": "jh-civics-set8", "school": "jh", "schoolName": "中学校", "subject": "social_civics", "subjectName": "社会（公民）", "topic": "3. 経済・くらしと国際社会", "title": "セット8: 企業・金融・財政と税の役割", "description": "株式会社のしくみ、日本銀行の役割、直接税と間接税についての3問。", "questions": [{"id": 1, "type": "4choice", "question": "お金の流通量を調整し、「発券銀行」「銀行の銀行」「政府の銀行」という3つの役割を担う日本の中心となる機関は何でしょう？", "options": ["財務省", "日本銀行（中央銀行）", "金融庁", "東京証券取引所"], "correct": 2, "timeLimit": 12, "category": "中学社会・公民", "explanation": "お札（日本銀行券）を発行し、民間の銀行にお金を貸し出し、国の税金の出し入れを行うのが中央銀行である「日本銀行（日銀）」です。"}, {"id": 2, "type": "4choice", "question": "税金を納める人（お店など）と、実際に税金を負担する人（消費者）が異なる「間接税」にあたる税金は次のうちどれでしょう？", "options": ["所得税", "法人税", "住民税", "消費税"], "correct": 4, "timeLimit": 12, "category": "中学社会・公民", "explanation": "「消費税」は買い物をした消費者が負担し、お店が代わりに国へ納める間接税です。一方、所得が多いほど税率が高くなる累進課税がとられる「所得税」などは直接税です。"}, {"id": 3, "type": "2choice", "question": "不景気のときには、国は公共事業を増やしたり減税をしたりして、世の中に出回るお金を増やす「財政政策」を行うことがある。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 1, "timeLimit": 10, "category": "中学社会・公民", "explanation": "正解！景気対策や道路・学校整備、社会保障の充実など、国の財政には「資源配分」「所得再分配」「景気の安定」の3つの重要な働きがあります。"}]}, {"id": "jh-civics-set9", "school": "jh", "schoolName": "中学校", "subject": "social_civics", "subjectName": "社会（公民）", "topic": "3. 経済・くらしと国際社会", "title": "セット9: 労働者の権利と社会保障", "description": "労働三法・労働三権、社会保障の4つの柱（社会保険・公的扶助等）についての3問。", "questions": [{"id": 1, "type": "4choice", "question": "働く人々の権利を守るために憲法第28条で保障されている「労働三権」とは、団結権・団体交渉権とあと1つは何でしょう？", "options": ["財産権", "団体行動権（争議権・ストライキ権）", "営業の自由", "居住・移転の自由"], "correct": 2, "timeLimit": 12, "category": "中学社会・公民", "explanation": "労働組合をつくる「団結権」、会社と交渉する「団体交渉権」、交渉がまとまらないときにストライキなどを行える「団体行動権（争議権）」の3つを労働三権といいます。"}, {"id": 2, "type": "4choice", "question": "日本の「社会保障制度」の4つの柱とは、社会保険・社会福祉・公衆衛生と、生活に困窮した人を支える生活保護などの何でしょう？", "options": ["公的扶助", "児童手当", "国民年金", "雇用保険"], "correct": 1, "timeLimit": 12, "category": "中学社会・公民", "explanation": "日本の社会保障は「社会保険（年金・医療・介護など）」「公的扶助（生活保護）」「社会福祉（高齢者・障害者・児童支援）」「公衆衛生（感染症対策や水道など）」の4本柱で支えられています。"}, {"id": 3, "type": "2choice", "question": "同じ職場で同じ内容の仕事をしていれば、正社員とパートタイム労働者の間で不合理な待遇の差をつけてはならない（同一労働同一賃金）というルールがある。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 1, "timeLimit": 10, "category": "中学社会・公民", "explanation": "正解！働き方改革の一環として、正規・非正規にかかわらず公正な処遇を目指す「同一労働同一賃金」や、長時間労働の是正などが進められています。"}]}, {"id": "jh-civics-set10", "school": "jh", "schoolName": "中学校", "subject": "social_civics", "subjectName": "社会（公民）", "topic": "3. 経済・くらしと国際社会", "title": "セット10: 国際連合と地球環境・SDGs", "description": "国連安保理の常任理事国、地球温暖化対策、SDGs（持続可能な開発目標）についての3問。", "questions": [{"id": 1, "type": "4choice", "question": "国際連合の「安全保障理事会（安保理）」で、重要な決定に対して拒否権を持つ5つの常任理事国の組み合わせとして正しいものはどれでしょう？", "options": ["アメリカ・イギリス・フランス・ドイツ・日本", "アメリカ・イギリス・フランス・ロシア・中国", "アメリカ・カナダ・インド・ドイツ・中国", "日本・イギリス・ロシア・イタリア・韓国"], "correct": 2, "timeLimit": 12, "category": "中学社会・公民", "explanation": "第二次世界大戦の戦勝国を中心とするアメリカ・イギリス・フランス・ロシア・中国の5か国が常任理事国です。1か国でも反対（拒否権）すると決議が通らない仕組みがあります。"}, {"id": 2, "type": "4choice", "question": "国連で採択された、2030年までに世界全体で達成を目指す「持続可能な開発目標（17のゴール）」をアルファベット4文字で何というでしょう？", "options": ["UNESCO", "SDGs", "UNICEF", "ASEAN"], "correct": 2, "timeLimit": 12, "category": "中学社会・公民", "explanation": "「誰一人取り残さない（Leave No One Behind）」を合言葉に、貧困の解消、ジェンダー平等、気候変動対策など17の目標を掲げるのが「SDGs」です。"}, {"id": 3, "type": "2choice", "question": "政府ではなく民間の立場から、災害支援・医療・環境保護などの国際協力を行う非政府組織のことを「NGO」という。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 1, "timeLimit": 10, "category": "中学社会・公民", "explanation": "正解！Non-Governmental Organizationの略がNGOです。国や自治体には手が届きにくい現場へ素早くきめ細かな支援を届ける大切な存在です。"}]}], "sample/junior_high/geography/geography.json": [{"id": "jh-geo-set1", "school": "jh", "schoolName": "中学校", "subject": "social_geo", "subjectName": "社会（地理）", "topic": "1. 世界の姿と地域", "title": "セット1: 地球の姿・緯度と経度・時差", "description": "六大陸と三大洋、赤道・本初子午線、経度と時差の計算についての3問。", "questions": [{"id": 1, "type": "4choice", "question": "地球上にある6つの大陸のうち、面積が最も大きい大陸はどれでしょう？", "options": ["アフリカ大陸", "北アメリカ大陸", "ユーラシア大陸", "南極大陸"], "correct": 3, "timeLimit": 12, "category": "中学社会・地理", "explanation": "ユーラシア大陸はアジアとヨーロッパを含む世界最大の大陸で、地球の陸地の約3分の1以上を占めています。"}, {"id": 2, "type": "4choice", "question": "イギリスのロンドンを通る、経度0度の基準となる線を何というでしょう？", "options": ["赤道", "本初子午線", "日付変更線", "北回帰線"], "correct": 2, "timeLimit": 12, "category": "中学社会・地理", "explanation": "ロンドン郊外の旧グリニッジ天文台を通る経度0度の線が「本初子午線」です。ちなみに日本の標準時子午線は東経135度（兵庫県明石市などを通過）です。"}, {"id": 3, "type": "2choice", "question": "経度が15度ちがうごとに、世界では1時間の時差が生じる。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 1, "timeLimit": 10, "category": "中学社会・地理", "explanation": "正解！地球は24時間で1回転（360度）するため、360 ÷ 24 = 15度ごとに1時間の時差が生まれます。東経135度の日本は、経度0度のロンドンより9時間進んでいます。"}]}, {"id": "jh-geo-set2", "school": "jh", "schoolName": "中学校", "subject": "social_geo", "subjectName": "社会（地理）", "topic": "1. 世界の姿と地域", "title": "セット2: 世界の気候帯と人々のくらし", "description": "熱帯・乾燥帯・温帯・冷帯・寒帯の気候区分と生活の工夫についての3問。", "questions": [{"id": 1, "type": "4choice", "question": "一年中気温が高く降水量も多い赤道周辺の「熱帯」で、スコールが降る地域に見られる住居の工夫はどれでしょう？", "options": ["レンガや日干しレンガで壁を厚くする", "風通しを良くし湿気を防ぐ高床式の家にする", "地面の氷がとけないよう地面に直接建てる", "窓を極力なくして雪の重みに耐える"], "correct": 2, "timeLimit": 12, "category": "中学社会・地理", "explanation": "熱帯の地域では、高温多湿や害虫・洪水を防ぐため、床を高くして風通しを良くした「高床式住居」が多く見られます。"}, {"id": 2, "type": "4choice", "question": "サハラ砂漠などの「乾燥帯」で、水や草を求めて移動しながらラクダやヒツジを育てる生活様式を何というでしょう？", "options": ["焼畑農業", "遊牧", "混合農業", "プランテーション"], "correct": 2, "timeLimit": 12, "category": "中学社会・地理", "explanation": "雨が少なく農作物が育ちにくいステップや砂漠の周辺では、家畜と水草を求めて移動する「遊牧」や、オアシス周辺での灌漑農業が行われます。"}, {"id": 3, "type": "2choice", "question": "同じ緯度に位置する東京とイタリアのローマを比較すると、夏は乾燥し冬に雨が多い「地中海性気候」にあたるのは東京である。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 2, "timeLimit": 10, "category": "中学社会・地理", "explanation": "ひっかけ問題！ローマなどの南ヨーロッパが「地中海性気候」（夏の乾燥に強いオリーブやブドウの栽培が盛ん）です。東京は四季の変化がはっきりした温暖湿潤気候です。"}]}, {"id": "jh-geo-set3", "school": "jh", "schoolName": "中学校", "subject": "social_geo", "subjectName": "社会（地理）", "topic": "1. 世界の姿と地域", "title": "セット3: 世界の国々と州の特色", "description": "アジア・ヨーロッパ・アフリカ・アメリカ州の地域的特徴についての3問。", "questions": [{"id": 1, "type": "4choice", "question": "アメリカ合衆国で、同じ作物（トウモロコシや小麦など）を広い土地で適した地域を選んで大規模に育てる農業の仕組みを何というでしょう？", "options": ["自給的農業", "適地適作（企業的農業）", "促成栽培", "棚田農業"], "correct": 2, "timeLimit": 12, "category": "中学社会・地理", "explanation": "アメリカでは気候や地形に合わせて、西経100度より東はトウモロコシや大豆、西は小麦や放牧など「適地適作」による大規模な商業的農業が行われています。"}, {"id": 2, "type": "4choice", "question": "ヨーロッパの多くの国が加盟し、国境を越えて人や物・お金が自由に行き来でき、共通通貨「ユーロ」も使われている地域統合組織はどれでしょう？", "options": ["ASEAN（東南アジア諸国連合）", "EU（ヨーロッパ連合）", "NAFTA", "OPEC"], "correct": 2, "timeLimit": 12, "category": "中学社会・地理", "explanation": "EU（ヨーロッパ連合）は経済や政治での協力を深めるためにつくられ、パスポートなしでの移動や単一通貨ユーロの導入などを行っています。"}, {"id": 3, "type": "2choice", "question": "アフリカ大陸の国境線には、過去の植民地支配の影響から、緯線や経線に沿った直線的な国境が多く見られる。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 1, "timeLimit": 10, "category": "中学社会・地理", "explanation": "正解！19世紀にヨーロッパ列強がアフリカを分割した際、現地の民族や地形を無視して地図上で定規を引くように国境を決めたため、直線的な国境が多く残っています。"}]}, {"id": "jh-geo-set4", "school": "jh", "schoolName": "中学校", "subject": "social_geo", "subjectName": "社会（地理）", "topic": "2. 日本の姿と産業", "title": "セット4: 日本の位置・領土と地形", "description": "日本の東西南北端、排他的経済水域（EEZ）、日本の山地と平野についての3問。", "questions": [{"id": 1, "type": "4choice", "question": "日本の領土の「最南端」と「最東端」の組み合わせとして正しいものはどれでしょう？", "options": ["与那国島 と 択捉島", "沖ノ鳥島 と 南鳥島", "沖縄島 と 小笠原諸島", "対馬 と 佐渡島"], "correct": 2, "timeLimit": 12, "category": "中学社会・地理", "explanation": "最北端が択捉島（北海道）、最西端が与那国島（沖縄県）、最南端が沖ノ鳥島（東京都）、最東端が南鳥島（東京都）です。特に沖ノ鳥島は広大な排他的経済水域（EEZ）を守る重要な島です！"}, {"id": 2, "type": "4choice", "question": "日本の国土のうち、山地や丘陵などが占める割合はおよそ何％くらいでしょう？", "options": ["約25％", "約50％", "約75％（約4分の3）", "約95％"], "correct": 3, "timeLimit": 12, "category": "中学社会・地理", "explanation": "日本の国土の約4分の3（約75％）は山地や丘陵地で、森林が国土の約3分の2を占めています。そのため川は短く流れが急で、河口には扇状地や三角州などの平野ができます。"}, {"id": 3, "type": "2choice", "question": "沿岸から200海里までの範囲で、水産資源や海底の鉱物資源を優先的に利用できる海域を「排他的経済水域（EEZ）」という。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 1, "timeLimit": 10, "category": "中学社会・地理", "explanation": "正解！領海（12海里）の外側にある「排他的経済水域」は、他国の船の航行は自由ですが、魚や石油・メタンハイドレートなどの資源に関する権利は沿岸国が独占します。"}]}, {"id": "jh-geo-set5", "school": "jh", "schoolName": "中学校", "subject": "social_geo", "subjectName": "社会（地理）", "topic": "2. 日本の姿と産業", "title": "セット5: 日本の気候と自然災害", "description": "季節風と海流、6つの気候区分、ハザードマップと防災についての3問。", "questions": [{"id": 1, "type": "4choice", "question": "冬の日本海側（北陸や東北の日本海側など）に世界有数の大雪をもたらす主な原因となる風と海流の組み合わせはどれでしょう？", "options": ["南東の季節風 と 親潮", "北西の季節風 と 対馬海流（暖流）", "偏西風 と 日本海流（黒潮）", "貿易風 と 千島海流"], "correct": 2, "timeLimit": 12, "category": "中学社会・地理", "explanation": "冬にシベリアから吹く冷たい「北西の季節風」が、日本海を流れる暖かい「対馬海流」から大量の水蒸気を受け取り、日本の脊梁山脈にぶつかって大雪を降らせます。"}, {"id": 2, "type": "4choice", "question": "九州地方と本州の間の瀬戸内海沿岸（瀬戸内の気候）に見られる気候の特徴として正しいものはどれでしょう？", "options": ["一年中雨が非常に多く、冬は豪雪になる", "南北の山地が季節風をさえぎり、一年を通じて温暖で降水量が少ない", "梅雨がなく、冬の寒さが非常に厳しい", "夏は乾燥し、冬だけに集中して雨が降る"], "correct": 2, "timeLimit": 12, "category": "中学社会・地理", "explanation": "瀬戸内地方は中国山地と四国山地に挟まれているため、季節風が山を越える際に水分を落とし、年間を通して雨が少なく温暖な気候になります（ため池が多いのもこのため）。"}, {"id": 3, "type": "2choice", "question": "洪水・津波・土砂災害などの危険が予想される場所や避難場所を示した地図を「ハザードマップ（防災マップ）」という。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 1, "timeLimit": 10, "category": "中学社会・地理", "explanation": "正解！日本は環太平洋造山帯に位置し、地震・火山・台風などの自然災害が多い国です。日頃から自宅や学校周辺のハザードマップを確認しておくことが命を守ります。"}]}, {"id": "jh-geo-set6", "school": "jh", "schoolName": "中学校", "subject": "social_geo", "subjectName": "社会（地理）", "topic": "2. 日本の姿と産業", "title": "セット6: 日本の資源・エネルギーと産業", "description": "エネルギー自給率と再生可能エネルギー、日本の工業地帯・工業地域についての3問。", "questions": [{"id": 1, "type": "4choice", "question": "日本のエネルギー自給率は先進国の中で低い水準ですが、近年注目されている太陽光・風力・地熱・水力・バイオマスなどのエネルギーをまとめて何というでしょう？", "options": ["化石燃料", "再生可能エネルギー", "シェールガス", "原子力エネルギー"], "correct": 2, "timeLimit": 12, "category": "中学社会・地理", "explanation": "自然界に常に存在する太陽や風、地熱（大分県や東北などで盛ん）などを使い、CO2をほとんど出さずにくり返し利用できるエネルギーを「再生可能エネルギー」といいます。"}, {"id": 2, "type": "4choice", "question": "愛知県を中心に自動車工業（トヨタなど）が非常に発達し、工業製品出荷額が長年日本一となっている工業地帯はどれでしょう？", "options": ["京浜工業地帯", "阪神工業地帯", "中京工業地帯", "北九州工業地帯"], "correct": 3, "timeLimit": 12, "category": "中学社会・地理", "explanation": "名古屋市や豊田市を中心とする「中京工業地帯」は、輸送用機械（自動車など）の生産が圧倒的で、日本の工業製品出荷額で第1位を誇ります。"}, {"id": 3, "type": "2choice", "question": "高速道路のインターチェンジや空港の近くに立地し、重さは軽いが値段の高いIC（集積回路）などを製造する工業を「臨海型工業」という。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 2, "timeLimit": 10, "category": "中学社会・地理", "explanation": "ひっかけ問題！ICなどの先端技術産業が内陸の高速道路や空港近くに立地する形は「内陸型工業（臨空型工業）」です。「臨海型工業」は石油化学や製鉄など重い原料を輸入する港の近くに立地します。"}]}, {"id": "jh-geo-set7", "school": "jh", "schoolName": "中学校", "subject": "social_geo", "subjectName": "社会（地理）", "topic": "3. 日本の諸地域", "title": "セット7: 九州地方・中国四国地方", "description": "シラス台地と畜産・IC産業、中国山地・瀬戸内工業地域についての3問。", "questions": [{"id": 1, "type": "4choice", "question": "鹿児島県や宮崎県南部にかけて広がる、火山灰が積もってできた水はけのよい台地で、サツマイモ栽培や肉牛・豚の畜産が盛んな場所を何というでしょう？", "options": ["関東ローム層", "シラス台地", "秋吉台（カルスト台地）", "濃尾平野"], "correct": 2, "timeLimit": 12, "category": "中学社会・地理", "explanation": "南九州の「シラス台地」は水はけが良すぎるため稲作には不向きでしたが、その特性を活かしてサツマイモなどの畑作や、全国トップクラスの畜産業が発展しました。"}, {"id": 2, "type": "4choice", "question": "九州地方で、福岡空港や大分空港、熊本空港などの周辺に多く進出し、「シリコンアイランド」とも呼ばれた産業は何でしょう？", "options": ["造船業", "繊維工業", "IC（集積回路・半導体）などの先端技術産業", "製紙・パルプ工業"], "correct": 3, "timeLimit": 12, "category": "中学社会・地理", "explanation": "豊かなきれいな水と労働力、そして空輸に便利な空港が多いことから半導体関連工場が集積し、九州は「シリコンアイランド」と呼ばれました。近年も新工場建設が進んでいます！"}, {"id": 3, "type": "2choice", "question": "温暖な高知平野（四国地方）では、ビニールハウスを利用して冬から春に出荷時期を早める「抑制栽培」が盛んに行われている。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 2, "timeLimit": 10, "category": "中学社会・地理", "explanation": "ひっかけ問題！暖かい気候やビニールハウスを利用して他の地域より「早く」出荷するのは「促成栽培（そくせいさいばい）」です！「抑制栽培」は長野県などの冷涼な高地で夏に出荷時期を「遅らせる」方法です。"}]}, {"id": "jh-geo-set8", "school": "jh", "schoolName": "中学校", "subject": "social_geo", "subjectName": "社会（地理）", "topic": "3. 日本の諸地域", "title": "セット8: 近畿地方・中部地方", "description": "京阪神大都市圏、東海・中央高地・北陸の工業や農業についての3問。", "questions": [{"id": 1, "type": "4choice", "question": "京都の西陣織や輪島塗、名古屋の陶磁器など、その土地の歴史の中で受け継がれてきた伝統的な工業を何というでしょう？", "options": ["重化学工業", "伝統的工芸品産業", "基礎素材型産業", "先端技術産業"], "correct": 2, "timeLimit": 12, "category": "中学社会・地理", "explanation": "近畿や北陸など歴史ある地域では、昔ながらの技術と地元の原料を生かした「伝統的工芸品」の生産が今も受け継がれています。"}, {"id": 2, "type": "4choice", "question": "中部地方の中央高地（長野県など）の涼しい気候を生かして、夏にレタスやキャベツを出荷する農業を何というでしょう？", "options": ["促成栽培", "抑制栽培", "二毛作", "水耕栽培"], "correct": 2, "timeLimit": 12, "category": "中学社会・地理", "explanation": "標高が高く夏でも涼しい長野県の野辺山原などでは、平地で作れない夏場に出荷を合わせる「抑制栽培（高冷地農業）」が盛んです！"}, {"id": 3, "type": "2choice", "question": "近畿地方にある日本最大の湖「琵琶湖」は、滋賀県だけでなく京都府や大阪府などの人々にとっても大切な飲み水（水がめ）となっている。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 1, "timeLimit": 10, "category": "中学社会・地理", "explanation": "正解！琵琶湖の水は瀬田川から宇治川・淀川となって大阪湾へ注いでおり、京阪神約1,400万人の生活や工業を支えるかけがえのない水源です。"}]}, {"id": "jh-geo-set9", "school": "jh", "schoolName": "中学校", "subject": "social_geo", "subjectName": "社会（地理）", "topic": "3. 日本の諸地域", "title": "セット9: 関東地方の特色と東京大都市圏", "description": "日本最大の関東平野、東京一極集中、近郊農業と輸送網についての3問。", "questions": [{"id": 1, "type": "4choice", "question": "千葉・埼玉・茨城など、大都市東京のすぐ近くで新鮮な野菜や花を育てて素早く出荷する農業を何というでしょう？", "options": ["企業的農業", "近郊農業", "焼畑農業", "遠洋漁業"], "correct": 2, "timeLimit": 12, "category": "中学社会・地理", "explanation": "大消費地である大都市の周辺で、輸送費を抑えて新鮮な作物を届ける「近郊農業」が関東平野一帯で盛んに行われています。"}, {"id": 2, "type": "4choice", "question": "昼間は通勤・通学で人口が多く、夜間になると住宅地に人が帰って人口が大きく減る、都心部に起きる現象を何というでしょう？", "options": ["過疎化", "ドーナツ化現象（昼夜間人口の差）", "ヒートアイランド現象", "少子化"], "correct": 2, "timeLimit": 12, "category": "中学社会・地理", "explanation": "都心のオフィス街などは地価が高いため郊外に住宅が広がり、都心の夜の人口が減る「ドーナツ化現象」が起きました。（近年は高層マンション増加で都心回帰も進んでいます）"}, {"id": 3, "type": "2choice", "question": "都市部にアスファルトやコンクリートが増え、冷暖房などの排熱も加わることで、郊外に比べて都市の中心部の気温が高くなる現象を「ヒートアイランド現象」という。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 1, "timeLimit": 10, "category": "中学社会・地理", "explanation": "正解！等温線を描くと都市が暖かい「島」のように見えることから「ヒートアイランド現象」と呼ばれます。屋上緑化や風の道づくりなどの対策が進められています。"}]}, {"id": "jh-geo-set10", "school": "jh", "schoolName": "中学校", "subject": "social_geo", "subjectName": "社会（地理）", "topic": "3. 日本の諸地域", "title": "セット10: 東北・北海道地方", "description": "東北の稲作（やませ対策）と祭り、北海道の酪農・畑作・青函トンネルについての3問。", "questions": [{"id": 1, "type": "4choice", "question": "夏に東北地方の太平洋側から吹き、冷害を引き起こす原因となってきた冷たく湿った風を何というでしょう？", "options": ["からっ風", "やませ", "フェーン現象", "偏西風"], "correct": 2, "timeLimit": 12, "category": "中学社会・地理", "explanation": "オホーツク海気団から吹く冷たい「やませ」から稲を守るため、東北では寒さに強い品種の改良（あきたこまち・ひとめぼれ等）が努力されてきました。"}, {"id": 2, "type": "4choice", "question": "北海道の東部に広がる「根釧（こんせん）台地」で、冷涼な気候と広い土地を生かして非常に盛んに行われている産業は何でしょう？", "options": ["稲作（米づくり）", "酪農（乳牛を育てて牛乳やバターなどを生産）", "みかん栽培", "石油化学工業"], "correct": 2, "timeLimit": 12, "category": "中学社会・地理", "explanation": "根釧台地は夏でも冷涼で濃霧が発生しやすいため穀物より牧草の育成に向いており、大規模な「酪農」が盛んです。日本の生乳生産量の半分以上は北海道です！"}, {"id": 3, "type": "2choice", "question": "青森県と北海道を海底で結び、現在は北海道新幹線も通っているトンネルは「青函（せいかん）トンネル」である。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 1, "timeLimit": 10, "category": "中学社会・地理", "explanation": "正解！「青」森と「函」館を結ぶことから「青函トンネル」（全長約53.85km）と名付けられ、1988年に開通しました。"}]}], "sample/junior_high/health/health.json": [{"id": "jh-health-set1", "school": "jh", "schoolName": "中学校", "subject": "health", "subjectName": "保健体育", "topic": "心身の発達と心の健康", "title": "セット1: 成長の急加速！「発育急進期」のひみつ", "description": "身長や体重が急激に伸びる発育急進期、成長の個人差、脳や神経の発達についての3問。", "questions": [{"id": 1, "type": "4choice", "question": "生まれてから大人になるまでに、身長や体重が急激に発育する時期は一生のうち何回あるでしょう？", "options": ["1回だけ", "2回ある", "3回ある", "毎年ずっと一定"], "correct": 2, "timeLimit": 10, "category": "中学生の保健", "explanation": "人間には身長や体重が急激に伸びる「発育急進期」が2回あります。1回目は乳児期（生後1年）、2回目は中学生前後の「思春期（第2発育急進期）」です！"}, {"id": 2, "type": "2choice", "question": "思春期（第2発育急進期）が始まる時期や成長のスピードには、一人ひとり「個人差」がある。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 1, "timeLimit": 10, "category": "中学生の保健", "explanation": "正解！思春期の成長が早く始まる人もいればゆっくり進む人もいます。背の伸び方や体の変化には大きな個人差があるため、人と比べすぎないことが大切です。"}, {"id": 3, "type": "2choice", "question": "脳や脊髄などの「神経系」は、思春期にはすでに大人とほぼ同じレベルまで発育が進んでいる。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 1, "timeLimit": 10, "category": "中学生の保健", "explanation": "正解！脳や脊髄などの神経系は幼児期から急速に発達し、思春期の頃には大人とほぼ同じ（約100%）まで発達が完了しています。"}]}, {"id": "jh-health-set2", "school": "jh", "schoolName": "中学校", "subject": "health", "subjectName": "保健体育", "topic": "心身の発達と心の健康", "title": "セット2: 肺と心臓のパワーアップ！「呼吸器と循環器」", "description": "肺活量の増大、心臓の働き、脈拍数の変化など呼吸器・循環器の発達についての3問。", "questions": [{"id": 1, "type": "4choice", "question": "呼吸器（鼻・のど・気管・肺など）の発達によって起こる体の変化として、正しいものはどれ？", "options": ["1回の呼吸で吸える肺活量が増大する", "安静時の呼吸数が大幅に増える", "少し歩いただけで息切れする", "肺の容積が小さくなる"], "correct": 1, "timeLimit": 10, "category": "中学生の保健", "explanation": "呼吸器が発達すると、肺活量（1回に吸い込める空気の量）がグンと増大し、安静時の呼吸数はかえって減少して効率の良い呼吸ができるようになります。"}, {"id": 2, "type": "4choice", "question": "血液を全身の血管へ力強く送り出す「循環器」の中心となる臓器は次のうちどれ？", "options": ["心臓（しんぞう）", "胃（い）", "肝臓（かんぞう）", "腎臓（じんぞう）"], "correct": 1, "timeLimit": 10, "category": "中学生の保健", "explanation": "循環器は心臓と血管（動脈・静脈・毛細血管）から成ります。心臓が力強いポンプとして収縮することで、酸素や栄養を乗せた血液が全身へ循環します。"}, {"id": 3, "type": "4choice", "question": "思春期に心臓や血管などの循環器が発達すると、安静時の「脈拍数」はどう変化するでしょう？", "options": ["脈拍数が少なくなる", "脈拍数が多くなる", "脈拍数がゼロになる", "一生まったく変わらない"], "correct": 1, "timeLimit": 10, "category": "中学生の保健", "explanation": "心臓が大きく強く育ち、1回の拍動で送り出せる血液量（拍出量）が増えるため、安静時の脈拍数（1分間の心拍数）は少なくなっていきます。"}]}, {"id": "jh-health-set3", "school": "jh", "schoolName": "中学校", "subject": "health", "subjectName": "保健体育", "topic": "心身の発達と心の健康", "title": "セット3: 体力を高める！「思春期の運動と持久力」", "description": "持久力を伸ばす最適期、運動強度の目安、「少しきつい」運動の継続についての3問。", "questions": [{"id": 1, "type": "4choice", "question": "思春期は、呼吸器や循環器の機能を高めるある体力を伸ばすのに最も適した時期です。その体力とは？", "options": ["持久力（スタミナ）", "握力（あくりょく）", "体の柔軟性", "瞬間的な視力"], "correct": 1, "timeLimit": 10, "category": "中学生の保健", "explanation": "思春期は肺や心臓が著しく成長するため、長く運動を続ける「持久力（全身持久力）」を高めるのに一生の中で最も適したゴールデンエイジです！"}, {"id": 2, "type": "4choice", "question": "思春期に持久力を効果的に高める運動の強さ（強度）の目安として、最も適切なものはどれ？", "options": ["「少しきつい」と感じる程度", "まったく疲れない散歩程度", "息が完全に止まる限界の運動", "1秒で倒れる全速力"], "correct": 1, "timeLimit": 10, "category": "中学生の保健", "explanation": "脈拍が適度に上がり、「少しきついな」と感じる程度の有酸素運動（ジョギング、水泳、球技など）を続けることが、心肺機能の向上に最も効果的です。"}, {"id": 3, "type": "2choice", "question": "運動の効果を高めるためには、たまに激しい運動をするよりも「継続的」に行うことが大切である。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 1, "timeLimit": 10, "category": "中学生の保健", "explanation": "正解！たまに無理な運動をするよりも、週に数回など継続して運動習慣をつけることで、呼吸器や循環器の機能が着実に高まります。"}]}, {"id": "jh-health-set4", "school": "jh", "schoolName": "中学校", "subject": "health", "subjectName": "保健体育", "topic": "心身の発達と心の健康", "title": "セット4: 体の変化の司令塔！「ホルモンと生殖器官」", "description": "下垂体からの性腺刺激ホルモン、精巣と卵巣の発達についての3問。", "questions": [{"id": 1, "type": "4choice", "question": "思春期になると、脳の底にあるどこから「性腺刺激ホルモン」が分泌され始めるでしょう？", "options": ["下垂体（かすいたい）", "小脳（しょうのう）", "延髄（えんずい）", "眼球（がんきゅう）"], "correct": 1, "timeLimit": 10, "category": "中学生の保健", "explanation": "脳の「下垂体」から性腺刺激ホルモンが血液中へ分泌され、それが精巣や卵巣を刺激して大人の体への成熟をスタートさせます。"}, {"id": 2, "type": "4choice", "question": "男子の生殖器官で、精子をつくり男性ホルモンを活発に分泌する器官はどこ？", "options": ["精巣（せいそう）", "前立腺（ぜんりつせん）", "膀胱（ぼうこう）", "胆のう（たんのう）"], "correct": 1, "timeLimit": 10, "category": "中学生の保健", "explanation": "下垂体の刺激によって「精巣」が発達し、精子がつくられ始めるとともに、男性ホルモンの働きで声変わりや筋肉の発達など男性らしい体つきになります。"}, {"id": 3, "type": "4choice", "question": "女子の生殖器官で、卵子を成熟させ女性ホルモンを活発に分泌する器官はどこ？", "options": ["卵巣（らんそう）", "子宮（しきゅう）", "胃（い）", "気管支（きかんし）"], "correct": 1, "timeLimit": 10, "category": "中学生の保健", "explanation": "「卵巣」が発達して卵子が成熟するようになり、女性ホルモンの働きによって乳房の発達や皮下脂肪の増加など女性らしい丸みのある体つきになります。"}]}, {"id": "jh-health-set5", "school": "jh", "schoolName": "中学校", "subject": "health", "subjectName": "保健体育", "topic": "心身の発達と心の健康", "title": "セット5: 生命をつなぐリズム！「排卵と月経」", "description": "成熟した卵子の排卵、子宮内膜と月経の仕組み、成熟の個人差についての3問。", "questions": [{"id": 1, "type": "4choice", "question": "卵巣の中で成熟した卵子が、周期的に卵巣の外（卵管）へ押し出される現象を何という？", "options": ["排卵（はいらん）", "着床（ちゃくしょう）", "射精（しゃせい）", "消化（しょうか）"], "correct": 1, "timeLimit": 10, "category": "中学生の保健", "explanation": "約1か月に1回、成熟した卵子が卵巣の壁を破って卵管へと飛び出す現象を「排卵」と呼びます。"}, {"id": 2, "type": "4choice", "question": "受精しなかったとき、充血して厚くなった子宮内膜がはがれ落ちて血液とともに体外へ出る現象は？", "options": ["月経（げっけい）", "排卵（はいらん）", "着床（ちゃくしょう）", "授乳（じゅにゅう）"], "correct": 1, "timeLimit": 10, "category": "中学生の保健", "explanation": "受精卵を迎えるために厚く準備された子宮内膜が、妊娠しなかった場合に不要となり剥がれて体外へ排出されるのが「月経（生理）」です。"}, {"id": 3, "type": "2choice", "question": "思春期の前半はホルモンの分泌がまだ不安定なため、月経の周期や射精の時期が不規則でも心配しすぎる必要はない。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 1, "timeLimit": 10, "category": "中学生の保健", "explanation": "正解！思春期の生殖機能は完成へと向かう途中のため、周期が乱れるのはごく自然なことです。体が成長するにつれて次第にリズムが安定していきます。"}]}, {"id": "jh-health-set6", "school": "jh", "schoolName": "中学校", "subject": "health", "subjectName": "保健体育", "topic": "心身の発達と心の健康", "title": "セット6: 命の誕生の奇跡！「受精から妊娠へ」", "description": "精子と卵子の受精、受精卵の着床、母体内での妊娠についての3問。", "questions": [{"id": 1, "type": "4choice", "question": "射精された精子が子宮を通って卵管へ進み、卵子と1つに結びつくことを何という？", "options": ["受精（じゅせい）", "排卵（はいらん）", "着床（ちゃくしょう）", "分娩（ぶんべん）"], "correct": 1, "timeLimit": 10, "category": "中学生の保健", "explanation": "数億個の精子の中からたった1つの精子が卵子と結合することを「受精」といい、ここから新しい生命の設計図が動き出します。"}, {"id": 2, "type": "4choice", "question": "細胞分裂を繰り返しながら移動した受精卵が、子宮内膜の中に潜り込んで定着することを何という？", "options": ["着床（ちゃくしょう）", "受精（じゅせい）", "射精（しゃせい）", "排卵（はいらん）"], "correct": 1, "timeLimit": 10, "category": "中学生の保健", "explanation": "受精卵が子宮の内側にしっかりと根を下ろすように定着することを「着床」といい、着床が完了した時点で「妊娠」が成立します。"}, {"id": 3, "type": "4choice", "question": "着床が完了してから赤ちゃんが生まれるまでの、母体内に胎児が宿って育っている状態を何という？", "options": ["妊娠（にんしん）", "受胎（じゅたい）", "着床（ちゃくしょう）", "思春期（ししゅんき）"], "correct": 1, "timeLimit": 10, "category": "中学生の保健", "explanation": "母体の中で胎児を育てる状態を「妊娠」と呼びます。胎児は約38週（約9〜10か月）かけて母体から酸素や栄養をもらいながら成長します。"}]}, {"id": "jh-health-set7", "school": "jh", "schoolName": "中学校", "subject": "health", "subjectName": "保健体育", "topic": "心身の発達と心の健康", "title": "セット7: こころの成長！「性意識と人間関係」", "description": "性意識の芽生え、性的欲求の自然な理解、適切な情報の選択と相談についての3問。", "questions": [{"id": 1, "type": "4choice", "question": "思春期になると、身体の発達に伴って異性への関心や好意を持つなど、心にある変化が現れます。これを何という？", "options": ["性意識（せいいしき）", "運動能力", "基礎代謝", "知能指数"], "correct": 1, "timeLimit": 10, "category": "中学生の保健", "explanation": "異性を意識したり特別な好意を抱くようになる心の働きを「性意識」と呼びます。これも思春期を迎えた誰にでも起こる自然な成長の表れです。"}, {"id": 2, "type": "2choice", "question": "思春期に性的な関心や性的欲求が高まることは、人間として恥ずかしい異常なことである。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 2, "timeLimit": 10, "category": "中学生の保健", "explanation": "誤り（×）です！性的な関心や欲求が生じるのは、ホルモンの働きによる成熟の証拠であり、ごく自然なことです。大切なのは相手を尊重し適切な行動をとることです。"}, {"id": 3, "type": "4choice", "question": "ネットやSNSなどの性情報に対処するとき、最も適切な態度は次のうちどれ？", "options": ["正しい情報を選択し、信頼できる大人に相談する", "ネットや友達の噂話をすべて信じる", "誰にも言えない秘密として一人で抱え込む", "興味本位であやしい広告やリンクを開く"], "correct": 1, "timeLimit": 10, "category": "中学生の保健", "explanation": "ネット上には誤った情報や危険な情報も混ざっています。科学的で正しい情報を選択し、不安や悩みがあれば保護者や先生、専門の相談窓口を頼りましょう。"}]}, {"id": "jh-health-set8", "school": "jh", "schoolName": "中学校", "subject": "health", "subjectName": "保健体育", "topic": "心身の発達と心の健康", "title": "セット8: こころの司令塔！「脳の働きと心の健康」", "description": "大脳の知的能力、経験による情意機能の発達、心の健康の調和についての3問。", "questions": [{"id": 1, "type": "4choice", "question": "言葉を使う・記憶する・理解する・論理的に判断するなど、高度な「知的能力」を司る脳の器官はどこ？", "options": ["大脳（だいのう）", "小脳（しょうのう）", "延髄（えんずい）", "脊髄（せきずい）"], "correct": 1, "timeLimit": 10, "category": "中学生の保健", "explanation": "大脳（大脳皮質）は、思考、学習、記憶、言葉、判断など、人間らしい高度な知的能力のすべてをコントロールしている中枢です。"}, {"id": 2, "type": "2choice", "question": "喜怒哀楽などの感情や意欲などの情意機能は、生まれつき決まっていて成長しても変化しない。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 2, "timeLimit": 10, "category": "中学生の保健", "explanation": "誤り（×）です！感情や意欲などの情意機能は、読書や友達との関わり、成功や失敗といったさまざまな「経験」や「学習」を通して豊かに発達していきます。"}, {"id": 3, "type": "2choice", "question": "「心の健康」を保つためには、知的能力・情意機能・社会性の働きがバランスよく調和することが大切である。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 1, "timeLimit": 10, "category": "中学生の保健", "explanation": "正解！正しい知識（知的能力）、思いやりや意欲（情意機能）、ルールを守り人と協調する力（社会性）がバランスよく働くことで、心が健康に保たれます。"}]}, {"id": "jh-health-set9", "school": "jh", "schoolName": "中学校", "subject": "health", "subjectName": "保健体育", "topic": "心身の発達と心の健康", "title": "セット9: おとなへのステップ！「思春期の特徴と自己形成」", "description": "精神的自立、親への反抗や葛藤、自立に向けた歩みについての3問。", "questions": [{"id": 1, "type": "4choice", "question": "大人の保護に依存していた状態から抜け出し、自分自身の考えや責任で行動しようとすることを何という？", "options": ["自立（じりつ）", "孤立（こりつ）", "退行（たいこう）", "反動（はんどう）"], "correct": 1, "timeLimit": 10, "category": "中学生の保健", "explanation": "思春期は「精神的自立」を始める大切な時期です。自分で考え、自分の責任で判断して行動できる大人へと少しずつ歩みを進めていきます。"}, {"id": 2, "type": "2choice", "question": "思春期に親や先生に対して口答えしたり反抗的な態度をとってしまうのは、自立に向けた自然な葛藤の表れである。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 1, "timeLimit": 10, "category": "中学生の保健", "explanation": "正解！自立したいという気持ちと、まだ甘えたい依存心が心の中でぶつかり合い、口答えや反抗として表れやすくなります。これも大人の階段を登る自然な過程です。"}, {"id": 3, "type": "2choice", "question": "中学生になれば、何の努力や経験もなくても誰でも簡単に自動的に自立できる。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 2, "timeLimit": 10, "category": "中学生の保健", "explanation": "誤り（×）です！自立は年齢が上がれば勝手にできるものではなく、日々の生活経験や失敗、友人や周囲の人との関わりを通して少しずつ身についていくものです。"}]}, {"id": "jh-health-set10", "school": "jh", "schoolName": "中学校", "subject": "health", "subjectName": "保健体育", "topic": "心身の発達と心の健康", "title": "セット10: 総まとめ！「思春期マスター総合クイズ」", "description": "成長の個人差の尊重、生活習慣の基本、相談の大切さについての総まとめ3問。", "questions": [{"id": 1, "type": "2choice", "question": "思春期の身体や心の発育スピードには大きな「個人差」があるため、他人と違っていても焦ったり劣等感を持つ必要はない。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 1, "timeLimit": 10, "category": "中学生の保健", "explanation": "正解！成長の早い・遅いは一人ひとり違います。自分の個性を受け止め、お互いの成長の違いを認め合って尊重することが大切です。"}, {"id": 2, "type": "2choice", "question": "思春期の心身の健康を支える基本は、「バランスの良い食事」「適度な運動」「十分な睡眠・休養」の3つである。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 1, "timeLimit": 10, "category": "中学生の保健", "explanation": "正解！急速に身体が大きくなり、勉強や部活でエネルギーを使う思春期だからこそ、食事・運動・睡眠の基本的生活習慣が健康な成長の土台になります。"}, {"id": 3, "type": "2choice", "question": "悩みや不安、希望などを何でも相談できる親友や、信頼できる大人を持つことは心の健康に役立つ。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 1, "timeLimit": 10, "category": "中学生の保健", "explanation": "正解！思春期は心に悩みや不安を抱えやすい時期です。自分の思いを話せる友人や、家族・先生・相談員など信頼できる大人を持つことが大きな支えになります。"}]}], "sample/junior_high/history/history.json": [{"id": "jh-history-set1", "school": "jh", "schoolName": "中学校", "subject": "social_history", "subjectName": "社会（歴史）", "topic": "1. 古代（縄文〜平安）", "title": "セット1: 縄文・弥生・古墳時代", "description": "縄文土器と弥生土器の違い、稲作の始まり、大仙陵古墳などの古墳時代についての3問。", "questions": [{"id": 1, "type": "4choice", "question": "約1万数千年前から始まった縄文時代の人々が、煮炊きや貯蔵に使った土器の特徴として正しいものはどれでしょう？", "options": ["表面になわの目などの文様があり、厚手で黒っぽい", "うす手でかたく、赤褐色でなめらかな表面", "ろくろを使って高温で焼いた青白い磁器", "ガラスのうわぐすりを塗ったカラフルな陶器"], "correct": 1, "timeLimit": 12, "category": "中学社会・歴史", "explanation": "縄文土器は低い温度で焼かれたため厚手で黒っぽく、表面に縄目の文様（縄文）があるのが特徴です。弥生時代になると、うす手でかたい弥生土器が使われるようになります。"}, {"id": 2, "type": "4choice", "question": "弥生時代に大陸から伝わり、人々の定住や貧富の差・身分の違いを生む大きなきっかけとなったものは何でしょう？", "options": ["牛や馬を使った牧畜", "水田での稲作（米づくり）", "鉄砲を使った狩り", "貨幣を使った商業"], "correct": 2, "timeLimit": 12, "category": "中学社会・歴史", "explanation": "弥生時代に水田での稲作が広まると、収穫したお米を貯蔵できるようになりました。その結果、食料や土地をめぐる争いや貧富の差が生まれ、やがて小さな「クニ」ができていきました。"}, {"id": 3, "type": "2choice", "question": "古墳時代に造られた「前方後円墳」の代表例である大仙陵古墳（仁徳天皇陵古墳）は、大阪府堺市にある日本最大の古墳である。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 1, "timeLimit": 10, "category": "中学社会・歴史", "explanation": "正解！鍵穴のような形をした前方後円墳は、大和政権（ヤマト王権）の強い権力を示すシンボルでした。中でも大阪府堺市の大仙陵古墳は、世界最大級の墳墓の一つです。"}]}, {"id": "jh-history-set2", "school": "jh", "schoolName": "中学校", "subject": "social_history", "subjectName": "社会（歴史）", "topic": "1. 古代（縄文〜平安）", "title": "セット2: 飛鳥時代（聖徳太子と大化の改新）", "description": "聖徳太子の政治（冠位十二階・十七条の憲法）、法隆寺、大化の改新についての3問。", "questions": [{"id": 1, "type": "4choice", "question": "推古天皇の摂政として活躍した聖徳太子が、家柄にとらわれず能力のある人を役人に登用するために定めた制度は何でしょう？", "options": ["班田収授法", "冠位十二階", "武家諸法度", "太閤検地"], "correct": 2, "timeLimit": 12, "category": "中学社会・歴史", "explanation": "「冠位十二階」は、冠の色で12の位を表し、有力豪族だけでなく才能ある人物を取り立てる仕組みでした。同じころ「十七条の憲法」も定めて役人の心構えを示しました。"}, {"id": 2, "type": "4choice", "question": "645年、中大兄皇子と中臣鎌足らが蘇我氏を倒し、天皇中心の国づくりを目指して始めた政治改革を何というでしょう？", "options": ["大化の改新", "建武の新政", "享保の改革", "明治維新"], "correct": 1, "timeLimit": 12, "category": "中学社会・歴史", "explanation": "645年に始まった「大化の改新」では、土地と人民をすべて国のものとする「公地公民」の原則が打ち出されました。日本で最初の年号「大化」が使われたことでも有名です。"}, {"id": 3, "type": "2choice", "question": "聖徳太子が建てたとされる奈良県の「法隆寺」は、現在残っている木造建築としては世界最古の建物である。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 1, "timeLimit": 10, "category": "中学社会・歴史", "explanation": "正解！法隆寺の五重塔や金堂などは飛鳥時代の建築様式を今に伝える「世界最古の木造建築群」であり、1993年に日本で初めてユネスコの世界文化遺産に登録されました。"}]}, {"id": "jh-history-set3", "school": "jh", "schoolName": "中学校", "subject": "social_history", "subjectName": "社会（歴史）", "topic": "1. 古代（縄文〜平安）", "title": "セット3: 奈良時代（平城京と天平文化）", "description": "平城京の誕生、聖武天皇と東大寺の大仏、墾田永年私財法についての3問。", "questions": [{"id": 1, "type": "4choice", "question": "710年、唐の長安をモデルにして現在の奈良県に造られた都を何というでしょう？", "options": ["藤原京", "平城京", "平安京", "鎌倉"], "correct": 2, "timeLimit": 12, "category": "中学社会・歴史", "explanation": "「なんと（710）立派な平城京」の語呂合わせで有名な平城京です！ちなみに794年に移された京都の都が「平安京（なくよ794うぐいす平安京）」です。"}, {"id": 2, "type": "4choice", "question": "奈良時代、飢きんや疫病から国を守るために「仏教の力」に頼ろうとした聖武天皇が、奈良の都に造らせたものは何でしょう？", "options": ["東大寺の大仏", "平等院鳳凰堂", "金閣寺", "厳島神社"], "correct": 1, "timeLimit": 12, "category": "中学社会・歴史", "explanation": "聖武天皇は全国に国分寺・国分尼寺を建てさせ、その中心として奈良の東大寺に巨大な大仏（盧舎那仏）を造りました。行基などの協力もあり、752年に大仏開眼供養が行われました。"}, {"id": 3, "type": "2choice", "question": "743年に朝廷が出した「墾田永年私財法」により、自分で新しく開墾した土地は、一生だけでなく永久に自分の土地（私有地）にできるようになった。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 1, "timeLimit": 10, "category": "中学社会・歴史", "explanation": "正解！口分田が不足したため、開墾を奨励する目的で「墾田永年私財法」が出されました。これにより貴族や寺社が広大な私有地（荘園）を持つようになり、公地公民の仕組みが崩れていきました。"}]}, {"id": "jh-history-set4", "school": "jh", "schoolName": "中学校", "subject": "social_history", "subjectName": "社会（歴史）", "topic": "1. 古代（縄文〜平安）", "title": "セット4: 平安時代（国風文化と武士の台頭）", "description": "藤原氏の摂関政治、かな文字と国風文化、平清盛などの武士の台頭についての3問。", "questions": [{"id": 1, "type": "4choice", "question": "平安時代の中ごろ、天皇が幼いときは「摂政」、成人してからは「関白」となって政治の実権をにぎり、全盛期を築いた一族はどれでしょう？", "options": ["蘇我氏", "藤原氏", "平氏", "源氏"], "correct": 2, "timeLimit": 12, "category": "中学社会・歴史", "explanation": "藤原道長・頼通の父子の時代に摂関政治は絶頂期を迎えました。道長が詠んだ「この世をば わが世とぞ思ふ 望月の…」の歌はとても有名ですね。"}, {"id": 2, "type": "4choice", "question": "平安時代に日本独自の「かな文字」が広まり、紫式部の『源氏物語』や清少納言の『枕草子』などが生まれた文化を何というでしょう？", "options": ["天平文化", "国風文化", "北山文化", "元禄文化"], "correct": 2, "timeLimit": 12, "category": "中学社会・歴史", "explanation": "遣唐使の廃止（894年）後、唐の文化をそのまま真似るのではなく、日本の風土や生活に合った優雅な「国風文化」が花開きました。十二単や寝殿造もこの時代の特徴です。"}, {"id": 3, "type": "2choice", "question": "平安時代の終わりごろ、武士として初めて太政大臣にまで出世し、日宋貿易で大きな利益を上げたのは「源頼朝」である。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 2, "timeLimit": 10, "category": "中学社会・歴史", "explanation": "ひっかけ問題！武士として初めて太政大臣になり日宋貿易を進めたのは「平清盛（たいらのきよもり）」です。その後、壇ノ浦の戦いで平氏を滅ぼして鎌倉幕府を開いたのが源頼朝です。"}]}, {"id": "jh-history-set5", "school": "jh", "schoolName": "中学校", "subject": "social_history", "subjectName": "社会（歴史）", "topic": "2. 中世（鎌倉〜室町）", "title": "セット5: 鎌倉時代（幕府の成立と元寇）", "description": "源頼朝の鎌倉幕府、守護と地頭、御成敗式目、2度の元寇についての3問。", "questions": [{"id": 1, "type": "4choice", "question": "鎌倉幕府を開いた源頼朝が、国ごとに置いて治安維持にあたらせた役職と、荘園・公領ごとに置いて税の取り立てをさせた役職の組み合わせはどれでしょう？", "options": ["国司と郡司", "守護と地頭", "大老と老中", "摂政と関白"], "correct": 2, "timeLimit": 12, "category": "中学社会・歴史", "explanation": "頼朝は全国の国に「守護」、荘園や公領に「地頭」を配置し、御家人との間に「ご恩と奉公」という主従関係を結びました。これが武家政治の本格的な始まりです。"}, {"id": 2, "type": "4choice", "question": "1232年、第3代執権の北条泰時が、裁判の公平さを保つために定めた武家社会で最初の成文法（ルールブック）を何というでしょう？", "options": ["十七条の憲法", "大宝律令", "御成敗式目（貞永式目）", "武家諸法度"], "correct": 3, "timeLimit": 12, "category": "中学社会・歴史", "explanation": "それまでの朝廷の法律ではなく、武士の間の道徳や慣習をまとめた全51か条の「御成敗式目」が制定されました。このルールは後の江戸時代まで長く手本とされました。"}, {"id": 3, "type": "2choice", "question": "13世紀後半にモンゴル帝国（元）が2度にわたって日本に攻めてきた「元寇（文永の役・弘安の役）」では、御家人たちの防戦や暴風雨により撃退することができた。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 1, "timeLimit": 10, "category": "中学社会・歴史", "explanation": "正解！石塁（防塁）を築いた武士たちの防戦と、暴風雨による元軍の撤退により日本を守り抜きました。しかし新しい領地が増えなかったため恩賞が不足し、幕府が衰退する原因となりました。"}]}, {"id": "jh-history-set6", "school": "jh", "schoolName": "中学校", "subject": "social_history", "subjectName": "社会（歴史）", "topic": "2. 中世（鎌倉〜室町）", "title": "セット6: 室町時代（金閣・銀閣と下剋上）", "description": "足利義満の勘合貿易・北山文化、応仁の乱、東山文化（銀閣）についての3問。", "questions": [{"id": 1, "type": "4choice", "question": "第3代将軍の足利義満が、倭寇（海賊）と区別するための「勘合（合い札）」を使って行った中国（明）との貿易を何というでしょう？", "options": ["日宋貿易", "勘合貿易（日明貿易）", "南蛮貿易", "朱印船貿易"], "correct": 2, "timeLimit": 12, "category": "中学社会・歴史", "explanation": "明との正式な貿易船であることを証明する「勘合」を持たせたことから「勘合貿易」と呼ばれます。これにより莫大な利益を得た義満は、京都に金閣（鹿苑寺）を建てました。"}, {"id": 2, "type": "4choice", "question": "1467年、将軍の後継ぎ争いなどをきっかけに京都で始まり、約11年間も続いて京都を焼け野原にした大きな戦乱は何でしょう？", "options": ["承久の乱", "応仁の乱", "島原・天草一揆", "壬申の乱"], "correct": 2, "timeLimit": 12, "category": "中学社会・歴史", "explanation": "「人の世むな（1467）しい応仁の乱」で覚えやすい大乱です。この戦乱によって幕府の権威は大きく下がり、実力のある者が上の者を倒す「下剋上」の戦国時代へと突入していきました。"}, {"id": 3, "type": "2choice", "question": "第8代将軍の足利義政が建てた「銀閣」を中心とする東山文化からは、今日の茶道や生け花（華道）、書院造などにつながる日本の伝統文化が多く生まれた。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 1, "timeLimit": 10, "category": "中学社会・歴史", "explanation": "正解！金閣の豪華な「北山文化」に対し、銀閣の「東山文化」はわび・さびを大切にする落ち着いた文化で、現在の和室（畳・障子・床の間がある書院造）の原型が完成しました。"}]}, {"id": "jh-history-set7", "school": "jh", "schoolName": "中学校", "subject": "social_history", "subjectName": "社会（歴史）", "topic": "3. 近世（安土桃山〜江戸）", "title": "セット7: 安土桃山時代（信長・秀吉の天下統一）", "description": "織田信長の楽市・楽座、豊臣秀吉の太閤検地・刀狩、鉄砲・キリスト教伝来についての3問。", "questions": [{"id": 1, "type": "4choice", "question": "織田信長が安土城の城下町などで、商工業者の組合である「座」の独占権をなくし、自由な商売を認めた政策を何というでしょう？", "options": ["楽市・楽座", "株仲間の解散", "版籍奉還", "殖産興業"], "correct": 1, "timeLimit": 12, "category": "中学社会・歴史", "explanation": "信長は「楽市・楽座」によって市場の税や関所をなくし、商業を活発にして経済力を大きく伸ばしました。また鉄砲を組織的に活用して長篠の戦いに勝利したことも有名です。"}, {"id": 2, "type": "4choice", "question": "豊臣秀吉が全国の田畑の広さや土地のよしあしを統一の基準（京枡など）で調べ、年貢の基準となる収穫高を「石高」で表した政策は何でしょう？", "options": ["地租改正", "太閤検地", "班田収授法", "田沼の政治"], "correct": 2, "timeLimit": 12, "category": "中学社会・歴史", "explanation": "「太閤検地」によって耕作者が検地帳に登録され、同時に実施した「刀狩」と合わせて、武士と農民の身分を厳しく分ける「兵農分離」が完成しました。"}, {"id": 3, "type": "2choice", "question": "1543年にポルトガル人が種子島に「鉄砲」を伝えた後、1549年にはフランシスコ・ザビエルによって日本にキリスト教が伝えられた。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 1, "timeLimit": 10, "category": "中学社会・歴史", "explanation": "正解！「いごよ（1543）く伝わる鉄砲」「いごよ（1549）く広まるキリスト教」の順です。これらをきっかけにヨーロッパの人々（南蛮人）との「南蛮貿易」が盛んになりました。"}]}, {"id": "jh-history-set8", "school": "jh", "schoolName": "中学校", "subject": "social_history", "subjectName": "社会（歴史）", "topic": "3. 近世（安土桃山〜江戸）", "title": "セット8: 江戸時代（幕藩体制・鎖国・開国）", "description": "参勤交代、鎖国と長崎出島の貿易、ペリー来航による開国についての3問。", "questions": [{"id": 1, "type": "4choice", "question": "江戸幕府の第3代将軍・徳川家光が大名たちを従わせるために義務づけた、1年おきに江戸と自分の領地を行き来させる制度を何というでしょう？", "options": ["武家諸法度の廃止", "参勤交代", "廃藩置県", "五街道の閉鎖"], "correct": 2, "timeLimit": 12, "category": "中学社会・歴史", "explanation": "大名に妻子を江戸に住まわせ、莫大な費用がかかる行列で往復させる「参勤交代」により、大名が幕府に反抗する力を弱めました。一方で街道や宿場町が発達するきっかけにもなりました。"}, {"id": 2, "type": "4choice", "question": "鎖国中も、幕府が長崎の出島に貿易を許したヨーロッパの国はどこでしょう？（中国と合わせて2か国のみ貿易）", "options": ["ポルトガル", "スペイン", "オランダ", "イギリス"], "correct": 3, "timeLimit": 12, "category": "中学社会・歴史", "explanation": "キリスト教を広めずに貿易だけを行うと約束した「オランダ」と「中国（清）」の船だけが長崎での貿易を許されました。その他、朝鮮・琉球王国・アイヌの人々とも交流を続けていました。"}, {"id": 3, "type": "2choice", "question": "1853年、アメリカ合衆国のペリーが黒船を率いて浦賀に現れ、日本に開国を求めた結果、翌年に日米和親条約が結ばれて鎖国が終わった。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 1, "timeLimit": 10, "category": "中学社会・歴史", "explanation": "正解！1854年の「日米和親条約」で下田と函館の2港を開き、さらに1858年の「日米修好通商条約」で自由貿易が始まりましたが、関税自主権がないなどの不平等条約でした。"}]}, {"id": "jh-history-set9", "school": "jh", "schoolName": "中学校", "subject": "social_history", "subjectName": "社会（歴史）", "topic": "4. 近代・現代（明治〜現代）", "title": "セット9: 明治〜大正時代（近代国家とデモクラシー）", "description": "大日本帝国憲法、大正デモクラシーと普通選挙法、明治維新の大改革についての3問。", "questions": [{"id": 1, "type": "4choice", "question": "1889年、アジアで最初の近代憲法として発布され、翌年の第1回帝国議会開設へとつながった憲法は何でしょう？", "options": ["日本国憲法", "大日本帝国憲法", "五箇条の御誓文", "憲法十七条"], "correct": 2, "timeLimit": 12, "category": "中学社会・歴史", "explanation": "伊藤博文らが中心となってプロイセン（ドイツ）の憲法を参考に作成した「大日本帝国憲法」が発布され、日本は立憲主義の国となりました。"}, {"id": 2, "type": "4choice", "question": "大正時代、国民が自由や権利を求めて盛り上がった「大正デモクラシー」の流れの中で、1925年に成立した選挙に関する法律はどれでしょう？", "options": ["男女雇用機会均等法", "農地改革法", "普通選挙法（満25歳以上の男子に選挙権）", "学制"], "correct": 3, "timeLimit": 12, "category": "中学社会・歴史", "explanation": "納税額による制限をなくし、満25歳以上のすべての男子に選挙権を与えた「普通選挙法」が1925年に成立しました。（※同じ年に社会主義運動などを取り締まる治安維持法も作られました）"}, {"id": 3, "type": "2choice", "question": "明治時代、新政府が近代化を進めるために「廃藩置県」「学制」「徴兵令」「地租改正」などの大改革を行い、富国強兵と殖産興業を目指した。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 1, "timeLimit": 10, "category": "中学社会・歴史", "explanation": "正解！これらの「明治維新」の改革と、官営模範工場の代表である富岡製糸場の設立などにより、日本は急速に近代産業国家へと発展していきました。"}]}, {"id": "jh-history-set10", "school": "jh", "schoolName": "中学校", "subject": "social_history", "subjectName": "社会（歴史）", "topic": "4. 近代・現代（明治〜現代）", "title": "セット10: 昭和〜現代（戦後復興と現代の日本）", "description": "日本国憲法の三大原則、国際連合への加盟と高度経済成長、沖縄本土復帰についての3問。", "questions": [{"id": 1, "type": "4choice", "question": "1946年に公布され、翌年5月3日に施行された「日本国憲法」の三大原則の組み合わせとして正しいものはどれでしょう？", "options": ["国民主権・基本的人権の尊重・平和主義", "公地公民・富国強兵・殖産興業", "三権分立・鎖国・武家政治", "自由放任・重商主義・保護貿易"], "correct": 1, "timeLimit": 12, "category": "中学社会・歴史", "explanation": "「国民主権」「基本的人権の尊重」「平和主義」が日本国憲法の三大原則です！ちなみに公布日の11月3日は「文化の日」、施行日の5月3日は「憲法記念日」になっています。"}, {"id": 2, "type": "4choice", "question": "日本が国際社会への復帰を果たした1956年（昭和31年）に、日本が加盟を認められた世界最大の国際組織は何でしょう？", "options": ["国際連盟", "国際連合（国連）", "欧州連合（EU）", "東南アジア諸国連合（ASEAN）"], "correct": 2, "timeLimit": 12, "category": "中学社会・歴史", "explanation": "1956年に日ソ共同宣言によってソ連と国交を回復したことで、日本は国際連合（UN）への加盟が認められました。その後、1964年には東京オリンピックや新幹線開通とともに高度経済成長が進みました。"}, {"id": 3, "type": "2choice", "question": "1972年5月15日、第二次世界大戦後からアメリカの統治下にあった沖縄が日本に返還（本土復帰）された。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 1, "timeLimit": 10, "category": "中学社会・歴史", "explanation": "正解！佐藤栄作首相らの交渉により、1972年に沖縄の施政権が日本へ返還されました。同じ1972年には日中共同声明が出され、中国との国交も正常化されました。"}]}], "sample/junior_high/science/science.json": [{"id": "jh-chem-set1", "school": "jh", "schoolName": "中学校", "subject": "science_chem", "subjectName": "理科（科学）", "topic": "1. 身のまわりの物質と水溶液", "title": "セット1: 物質の性質・有機物と密度", "description": "金属の性質、有機物と無機物の区別、密度の計算についての3問。", "questions": [{"id": 1, "type": "4choice", "question": "加熱するとこげて炭になり、二酸化炭素と水を発生させる「有機物」にあてはまる物質はどれでしょう？", "options": ["食塩", "砂糖・デンプン・プラスチック", "鉄・アルミニウム", "ガラス"], "correct": 2, "timeLimit": 12, "category": "中学理科・科学", "explanation": "炭素を含む物質（ただし二酸化炭素や炭酸塩を除く）で、燃やすと炭になったり二酸化炭素を出すのが「有機物」です。砂糖・ろう・プラスチック・エタノールなどが代表例です！"}, {"id": 2, "type": "4choice", "question": "「金属」に共通する5つの性質のうち、たたいて薄く広げることができる性質を何というでしょう？", "options": ["延性（えんせい）", "展性（てんせい）", "金属光沢", "電気伝導性"], "correct": 2, "timeLimit": 12, "category": "中学理科・科学", "explanation": "金属には①電気をよく通す ②熱をよく伝える ③みがくと金属光沢が出る ④たたいて広がる「展性」（アルミホイルなど） ⑤引っぱってのびる「延性」（銅線など）の性質があります！"}, {"id": 3, "type": "2choice", "question": "物質1cm³あたりの質量を「密度（g/cm³）」といい、同じ種類の物質であれば大きさがちがっても密度はつねに一定である。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 1, "timeLimit": 10, "category": "中学理科・科学", "explanation": "正解！「密度 ＝ 質量 ÷ 体積」で計算します。例えば水の密度は約1.0g/cm³なので、それより密度が小さい木や氷・油は水に浮き、大きい鉄やアルミは沈みます。"}]}, {"id": "jh-chem-set2", "school": "jh", "schoolName": "中学校", "subject": "science_chem", "subjectName": "理科（科学）", "topic": "1. 身のまわりの物質と水溶液", "title": "セット2: 気体の性質と集め方", "description": "酸素・二酸化炭素・水素・アンモニアの性質と、水上・上方・下方置換法についての3問。", "questions": [{"id": 1, "type": "4choice", "question": "水にとけやすく空気よりとても軽いため「上方置換法」で集め、フェノールフタレイン溶液を赤く変える刺激臭のある気体はどれでしょう？", "options": ["酸素", "二酸化炭素", "水素", "アンモニア"], "correct": 4, "timeLimit": 12, "category": "中学理科・科学", "explanation": "アンモニアは水に非常によく溶けて「アルカリ性」を示すため、フェノールフタレインを赤色にします。水にとけやすいため水上置換ではなく、空気より軽いので「上方置換法」で集めます！"}, {"id": 2, "type": "4choice", "question": "気体の発生方法で、二酸化マンガンにうすい過酸化水素水（オキシドール）を加えると発生する気体は何でしょう？", "options": ["水素", "酸素", "二酸化炭素", "窒素"], "correct": 2, "timeLimit": 12, "category": "中学理科・科学", "explanation": "「二酸化マンガン ＋ うすい過酸化水素水 → 酸素」（火のついた線香を激しく燃やす助燃性あり！）。ちなみに石灰石＋うすい塩酸は「二酸化炭素」、亜鉛や鉄＋うすい塩酸は「水素」です。"}, {"id": 3, "type": "2choice", "question": "水にとけにくい気体（酸素・水素・窒素など）を集めるときは、純粋な気体が集めやすく集まった量も一目でわかる「水上置換法」を使うのが最もよい。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 1, "timeLimit": 10, "category": "中学理科・科学", "explanation": "正解！少しだけ水に溶ける二酸化炭素も、実験室では純度よく集めるために水上置換法が使われることが多いです（大量に集めるときは下方置換法）。"}]}, {"id": "jh-chem-set3", "school": "jh", "schoolName": "中学校", "subject": "science_chem", "subjectName": "理科（科学）", "topic": "1. 身のまわりの物質と水溶液", "title": "セット3: 水溶液と溶解度・再結晶", "description": "溶質・溶媒・溶液、質量パーセント濃度、溶解度曲線と再結晶についての3問。", "questions": [{"id": 1, "type": "4choice", "question": "100gの水に25gの食塩を完全にとかしたとき、できた食塩水の「質量パーセント濃度」は何％になるでしょう？", "options": ["25％", "20％", "15％", "12.5％"], "correct": 2, "timeLimit": 12, "category": "中学理科・科学", "explanation": "超定番のひっかけ注意問題！濃度は「溶質 ÷ 溶液全体（水＋溶質） × 100」で計算します。ここでは水100g＋食塩25g＝125gなので、25 ÷ 125 × 100 ＝ 20％ になります！"}, {"id": 2, "type": "4choice", "question": "ミョウバンや硝酸カリウムのように「水の温度によって溶ける量（溶解度）が大きく変わる物質」を、熱いお湯にとかしたあと冷やして結晶を取り出す方法を何というでしょう？", "options": ["ろ過", "再結晶", "蒸留", "昇華"], "correct": 2, "timeLimit": 12, "category": "中学理科・科学", "explanation": "温度を下げて溶けきれなくなった分を純粋な結晶として取り出す操作を「再結晶」といいます。なお、食塩は温度を変えても溶解度がほとんど変わらないため、水を蒸発させて結晶を取り出します。"}, {"id": 3, "type": "2choice", "question": "透明な水溶液の中で溶質が均一に散らばっているとき、しばらく置いておいても下に溶質が沈んだり濃さが上下で変わったりすることはない。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 1, "timeLimit": 10, "category": "中学理科・科学", "explanation": "正解！「透明」「どこをとっても同じ濃さ」「時間がたっても沈まない」「ろ紙を通り抜ける」が水溶液の性質です（青色や紫色など色がついている水溶液でも、透き通っていれば透明です）。"}]}, {"id": "jh-chem-set4", "school": "jh", "schoolName": "中学校", "subject": "science_chem", "subjectName": "理科（科学）", "topic": "1. 身のまわりの物質と水溶液", "title": "セット4: 状態変化と蒸留", "description": "固体・液体・気体の体積変化、融点・沸点、沸点のちがいを利用した「蒸留」についての3問。", "questions": [{"id": 1, "type": "4choice", "question": "水とエタノールの混合物を加熱し、沸点のちがい（エタノール約78℃、水100℃）を利用して液体どうしを分離する方法を何というでしょう？", "options": ["ろ過", "蒸留（分留）", "再結晶", "中和"], "correct": 2, "timeLimit": 12, "category": "中学理科・科学", "explanation": "液体を加熱して気体にし、それを冷やして再び純度の高い液体として取り出す方法を「蒸留」といいます。石油（原油）からガソリンや灯油を分けるときも同じ原理が使われています！"}, {"id": 2, "type": "4choice", "question": "一般的な物質が「固体 → 液体 → 気体」と状態変化するとき、粒子の動きと体積はどう変化するでしょう？（水から氷などの例外を除く）", "options": ["体積はだんだん小さくなり、質量も軽くなる", "粒子の運動が激しくなり体積は大きくなるが、質量は変わらない", "質量だけが重くなる", "粒子の数は増える"], "correct": 2, "timeLimit": 12, "category": "中学理科・科学", "explanation": "状態変化をしても物質の粒子そのものの種類や数は変わらないため「質量は変化せず一定」です。一方、粒子どうしのすき間が広がるため「体積は大きく」なります（※水は氷になるとき体積が増える特別な例外です！）。"}, {"id": 3, "type": "2choice", "question": "液体を熱して沸騰させるとき、急激な沸騰（突沸）を防ぐためにフラスコの中に入れておく小さな石を「沸騰石」という。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 1, "timeLimit": 10, "category": "中学理科・科学", "explanation": "正解！沸騰石の表面の小さな穴から気泡が穏やかに発生し続けることで、突然中身が吹き出す「突沸」を安全に防いでくれます。"}]}, {"id": "jh-chem-set5", "school": "jh", "schoolName": "中学校", "subject": "science_chem", "subjectName": "理科（科学）", "topic": "2. 原子・分子と化学変化", "title": "セット5: 原子・分子と化学式", "description": "ドルトンの原子説、分子をつくる物質とつくらない物質、代表的な化学式についての3問。", "questions": [{"id": 1, "type": "4choice", "question": "物質を構成する最小の粒である「原子」の性質として、正しくない（誤っている）ものはどれでしょう？", "options": ["化学変化によって、新しくできたり消えてなくなったりしない", "種類によって決まった質量や大きさがある", "化学変化によって、ある原子が別の種類の原子に勝手に変わる", "化学変化の前後で原子の総数は変わらない"], "correct": 3, "timeLimit": 12, "category": "中学理科・科学", "explanation": "原子は①それ以上分けられない ②なくならない ③新しくできない ④別の種類の原子に変わらない ⑤決まった質量がある、というのがドルトンの原子の性質です！（組み合わせだけが変わります）"}, {"id": 2, "type": "4choice", "question": "「二酸化炭素」「アンモニア」「塩化ナトリウム（食塩）」を化学式で表したときの正しい組み合わせはどれでしょう？", "options": ["CO2、NH3、NaCl", "H2O、CO2、CuO", "O2、CH4、HCl", "CO、H2O2、NaOH"], "correct": 1, "timeLimit": 12, "category": "中学理科・科学", "explanation": "二酸化炭素＝CO₂、アンモニア＝NH₃、塩化ナトリウム＝NaCl です。なお金属（Fe, Cuなど）や塩化ナトリウム（NaCl）は「分子をつくらない物質」として多くの原子・イオンが規則正しく並んでいます。"}, {"id": 3, "type": "2choice", "question": "「炭酸水素ナトリウム（重曹）」を加熱すると、炭酸ナトリウム・二酸化炭素・水の3つの物質に分解される（熱分解）。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 1, "timeLimit": 10, "category": "中学理科・科学", "explanation": "正解！ホットケーキやカルメ焼きがふくらむのは、ベーキングパウダー中の炭酸水素ナトリウムが熱で分解されて「二酸化炭素」の泡が出るためです！"}]}, {"id": "jh-chem-set6", "school": "jh", "schoolName": "中学校", "subject": "science_chem", "subjectName": "理科（科学）", "topic": "2. 原子・分子と化学変化", "title": "セット6: 分解と化合（電気分解・硫化）", "description": "水の電気分解の体積比（2:1）、鉄と硫黄の化合（硫化鉄）、発熱・吸熱反応についての3問。", "questions": [{"id": 1, "type": "4choice", "question": "水（水酸化ナトリウムを少量溶かした水）を電気分解したとき、陰極（－極）と陽極（＋極）に集まる気体とその体積比の正しい組み合わせはどれでしょう？", "options": ["陰極：酸素(1) 、陽極：水素(2)", "陰極：水素(2) 、陽極：酸素(1)", "陰極：水素(1) 、陽極：酸素(1)", "陰極：窒素(2) 、陽極：酸素(1)"], "correct": 2, "timeLimit": 12, "category": "中学理科・科学", "explanation": "水の化学式 H₂O の通り、水素(H₂)：酸素(O₂)＝2：1 の体積比で発生します。「陰極＝水素(2)、陽極＝酸素(1)」！（マッチを近づけるとポンッと燃えるのが陰極の水素です）"}, {"id": 2, "type": "4choice", "question": "鉄粉と硫黄の粉末を混ぜて加熱すると「硫化鉄」ができます。できた硫化鉄にうすい塩酸を加えると、どんな特徴のある気体が発生するでしょう？", "options": ["無臭で火を燃やす酸素", "卵の腐ったような特有の臭いがある「硫化水素」", "刺激臭があり水に溶けてアルカリ性になるアンモニア", "石灰水を白くにごらせる二酸化炭素"], "correct": 2, "timeLimit": 12, "category": "中学理科・科学", "explanation": "鉄＋塩酸なら無臭の「水素」が出ますが、鉄と硫黄が化合した「硫化鉄」は磁石につかなくなり、塩酸を加えると有毒で腐卵臭のある「硫化水素（H₂S）」が発生します！"}, {"id": 3, "type": "2choice", "question": "使い捨てカイロが温かくなるのは、鉄粉が空気中の酸素と結びついて酸化するときに熱を出す「発熱反応」を利用している。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 1, "timeLimit": 10, "category": "中学理科・科学", "explanation": "正解！逆に炭酸水素ナトリウムとクエン酸の反応や、水酸化バリウムと塩化アンモニウムを混ぜたときのように、まわりから熱を奪って冷たくなる反応を「吸熱反応」といいます。"}]}, {"id": "jh-chem-set7", "school": "jh", "schoolName": "中学校", "subject": "science_chem", "subjectName": "理科（科学）", "topic": "2. 原子・分子と化学変化", "title": "セット7: 酸化・還元と質量保存の法則", "description": "銅・マグネシウムの酸化と定比例の法則、酸化銅の炭素による還元、質量保存の法則についての3問。", "questions": [{"id": 1, "type": "4choice", "question": "黒い「酸化銅」の粉末に「炭素（木炭）」の粉末を混ぜて強く加熱すると、赤茶色の「銅」と二酸化炭素ができます。このとき酸化銅が酸素を奪われる変化を何というでしょう？", "options": ["酸化", "還元", "中和", "電気分解"], "correct": 2, "timeLimit": 12, "category": "中学理科・科学", "explanation": "酸化物から酸素が取り除かれる変化を「還元」といいます！このとき炭素は逆に酸素と結びついて「酸化」されているため、酸化と還元は必ず同時に起こります。"}, {"id": 2, "type": "4choice", "question": "銅を加熱して酸化銅にすると、銅：酸素：酸化銅の質量比は常に「4：1：5」になります。銅 2.0g を完全に酸化させると、何gの酸化銅ができるでしょう？", "options": ["2.2g", "2.5g", "3.0g", "4.0g"], "correct": 2, "timeLimit": 12, "category": "中学理科・科学", "explanation": "銅：酸素＝4：1 なので、銅2.0gには 2.0 ÷ 4 ＝ 0.5g の酸素が結びつきます。したがってできる酸化銅は 2.0 ＋ 0.5 ＝ 2.5g！（マグネシウムは 3：2：5 で覚えましょう！）"}, {"id": 3, "type": "2choice", "question": "気体が発生する化学変化でも、密閉された容器の中で行えば、反応の前と後で全体の質量はまったく変わらない（質量保存の法則）。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 1, "timeLimit": 10, "category": "中学理科・科学", "explanation": "正解！オープンなビーカーだと発生した二酸化炭素などの気体が空気中へ逃げて軽くなったように見えますが、密閉すればすべての原子が残るため質量は100%保存されます！"}]}, {"id": "jh-chem-set8", "school": "jh", "schoolName": "中学校", "subject": "science_chem", "subjectName": "理科（科学）", "topic": "3. イオン・科学の基礎", "title": "セット8: 電解質・イオンと電気分解", "description": "電解質と非電解質、陽イオンと陰イオン、塩化銅水溶液の電気分解についての3問。", "questions": [{"id": 1, "type": "4choice", "question": "水に溶かしたときに電離して電流が流れる「電解質」ではなく、電流が流れない「非電解質」にあたる物質はどれでしょう？", "options": ["塩化ナトリウム（食塩）", "塩化水素（塩酸）", "砂糖・エタノール", "水酸化ナトリウム"], "correct": 3, "timeLimit": 12, "category": "中学理科・科学", "explanation": "食塩水や塩酸・レモン汁などの「電解質」は水中で陽イオンと陰イオンに分かれる（電離する）ため電気を通します。砂糖水やエタノール水溶液はイオンにならず電気を通しません（非電解質）。"}, {"id": 2, "type": "4choice", "question": "青色の「塩化銅水溶液」に電流を流して電気分解すると、陰極（－極）と陽極（＋極）にはそれぞれ何ができるでしょう？", "options": ["陰極：塩素（気体）、陽極：赤茶色の銅", "陰極：赤茶色の銅、陽極：塩素（プールのにおい・漂白作用）", "陰極：水素、陽極：酸素", "何も変化しない"], "correct": 2, "timeLimit": 12, "category": "中学理科・科学", "explanation": "銅イオン（Cu²⁺）はプラスの電気を持つため陰極（－）へ引き寄せられて「銅」が付着し、塩化物イオン（Cl⁻）はマイナスの電気を持つため陽極（＋）へ引き寄せられて「塩素」が発生します！"}, {"id": 3, "type": "2choice", "question": "原子が電子を「失う」とプラスの電気を帯びた「陽イオン」になり、電子を「受け取る」とマイナスの電気を帯びた「陰イオン」になる。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 1, "timeLimit": 10, "category": "中学理科・科学", "explanation": "正解！電子は「マイナス」の電気を持っているため、マイナスを1つ失うとプラスが1つ多い「陽イオン（例：Na⁺）」になり、マイナスを受け取ると「陰イオン（例：Cl⁻）」になります。"}]}, {"id": "jh-chem-set9", "school": "jh", "schoolName": "中学校", "subject": "science_chem", "subjectName": "理科（科学）", "topic": "3. イオン・科学の基礎", "title": "セット9: 酸・アルカリと中和反応・塩", "description": "水素イオンと水酸化物イオン、BTB溶液・pH、中和と塩（えん）についての3問。", "questions": [{"id": 1, "type": "4choice", "question": "「酸性」の水溶液に共通する性質を決めるイオンと、「アルカリ性」の性質を決めるイオンの組み合わせはどれでしょう？", "options": ["酸性：水酸化物イオン(OH⁻) 、アルカリ性：水素イオン(H⁺)", "酸性：水素イオン(H⁺) 、アルカリ性：水酸化物イオン(OH⁻)", "酸性：ナトリウムイオン(Na⁺) 、アルカリ性：塩化物イオン(Cl⁻)", "どちらもイオンは無関係"], "correct": 2, "timeLimit": 12, "category": "中学理科・科学", "explanation": "酸性は「H⁺（水素イオン）」、アルカリ性は「OH⁻（水酸化物イオン）」が正体です！酸性はBTB溶液を黄色、アルカリ性は青色、中性は緑色にします。"}, {"id": 2, "type": "4choice", "question": "塩酸（HCl）と水酸化ナトリウム水溶液（NaOH）をちょうど過不足なく混ぜ合わせて「中和」したときにできる2つの物質は何でしょう？", "options": ["水素 と 酸素", "水（H2O） と 塩化ナトリウム（食塩・NaCl）", "二酸化炭素 と アンモニア", "硫酸バリウム と 水"], "correct": 2, "timeLimit": 12, "category": "中学理科・科学", "explanation": "酸の H⁺ とアルカリの OH⁻ が結びついて「水（H₂O）」ができ、残った陽イオンと陰イオンが結びついて「塩（えん：ここでは塩化ナトリウム）」ができます。つまり「酸＋アルカリ → 水＋塩」です！"}, {"id": 3, "type": "2choice", "question": "うすい塩酸にマグネシウムや亜鉛などの金属を入れると、気体の「水素」を発生しながら溶ける。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 1, "timeLimit": 10, "category": "中学理科・科学", "explanation": "正解！多くの酸性の水溶液は、鉄・亜鉛・マグネシウムなどの金属と反応して「水素」を発生させます（ただし銅や金などはうすい塩酸には溶けません）。"}]}, {"id": "jh-chem-set10", "school": "jh", "schoolName": "中学校", "subject": "science_chem", "subjectName": "理科（科学）", "topic": "3. イオン・科学の基礎", "title": "セット10: 電池・電流や光・力の科学基礎", "description": "化学電池（ダニエル電池等）、オームの法則、光の屈折と力学的エネルギーについての3問。", "questions": [{"id": 1, "type": "4choice", "question": "2種類の異なる金属板（例：銅板と亜鉛板）を電解質の水溶液に入れて導線でつなぐ「化学電池」で、電子が流れ出して金属が溶けやすい（－極になる）のはどちらでしょう？", "options": ["イオンになりにくい金属（銅板など）", "イオンになりやすい金属（亜鉛板やマグネシウムなど）", "どちらも同じように＋極になる", "ガラス棒やプラスチック板"], "correct": 2, "timeLimit": 12, "category": "中学理科・科学", "explanation": "亜鉛は銅よりも「陽イオンになりやすい」性質があるため、亜鉛原子が電子を金属板に残してZn²⁺として溶け出し、その電子が導線を通って銅板へ流れるため亜鉛が「－極」になります！"}, {"id": 2, "type": "4choice", "question": "電気回路において、抵抗が10Ωの電熱線に5V（ボルト）の電圧を加えたとき、この電熱線を流れる電流は何A（アンペア）になるでしょう？", "options": ["50 A", "2.0 A", "0.5 A", "5.0 A"], "correct": 3, "timeLimit": 12, "category": "中学理科・科学", "explanation": "オームの法則「電圧(V) ＝ 電流(A) × 抵抗(Ω)」より、電流 ＝ 電圧 ÷ 抵抗 ＝ 5V ÷ 10Ω ＝ 0.5A になります！"}, {"id": 3, "type": "2choice", "question": "空気中から水やガラスの中へ光が斜めに進むとき、光は境界線で折れ曲がり（屈折し）、入射角よりも屈折角のほうが「小さく」なる。", "options": ["〇 (正しい)", "× (誤り)"], "correct": 1, "timeLimit": 10, "category": "中学理科・科学", "explanation": "正解！「空気 → 水・ガラス」のときは入射角＞屈折角になり、逆に「水・ガラス → 空気」へ出るときは入射角＜屈折角になるため、一定の角度を超えるとすべて跳ね返る「全反射」が起こります。"}]}]}};
